"""Consolidated regression suite for tgcp-bot.

All original Python, JavaScript, and integration checks live inside this one
tracked test file. During a run, they are temporarily reconstructed so that
each native test runner keeps its original assertions, imports and isolation.

Run: python -m unittest discover -s tests -v
"""
import subprocess
import sys
import unittest
from contextlib import contextmanager
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TEST_DIR = ROOT / "tests"

# Complete original sources. Do not drop a case when modifying this bundle.
_BUNDLED_CASES = {
  "__init__.py": "\"\"\"Project regression tests.\"\"\"\n",
  "operations_scenarios.py": "\"\"\"Isolated integration cases: no real server configuration or commands are loaded.\"\"\"\nimport asyncio\nimport importlib.util\nimport json\nimport sys\nimport tempfile\nimport unittest\nimport uuid\nfrom concurrent.futures import ThreadPoolExecutor\nfrom pathlib import Path\nfrom types import SimpleNamespace\nfrom unittest.mock import AsyncMock, MagicMock, Mock, patch\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\n\nfrom cryptography.fernet import Fernet\nfrom tortoise import Tortoise\n\nsys.modules[\"core.config\"] = SimpleNamespace(CIPHER_SUITE=Fernet(Fernet.generate_key()))\n\nfrom core import operations\nfrom core.models import Node, NodeOperation\nfrom node.operation_journal import OperationJournal, heartbeat_state, open_journal\n\n# Test-only encrypted envelope. The production wire cipher is not implemented here:\n# these API tests exercise authorization, secrecy and response structure.\nTEST_WEB_CIPHER = Fernet(Fernet.generate_key())\n\n\ndef encrypt_web_fixture(value):\n    if not value:\n        return \"\"\n    return TEST_WEB_CIPHER.encrypt(str(value).encode(\"utf-8\")).decode(\"ascii\")\n\n\ndef decrypt_web_fixture(value):\n    return TEST_WEB_CIPHER.decrypt(value.encode(\"ascii\")).decode(\"utf-8\")\n\n\nclass DeliveryTests(unittest.IsolatedAsyncioTestCase):\n    async def asyncSetUp(self):\n        self.temp = tempfile.TemporaryDirectory()\n        self.db_url = \"sqlite://\" + str(Path(self.temp.name) / \"master.db\")\n        await Tortoise.init(db_url=self.db_url, modules={\"models\": [\"core.models\"]})\n        await Tortoise.generate_schemas()\n        self.node = await Node.create(token_hash=\"one\", token_safe=\"secret\", name=\"One\", ip=\"127.0.0.1\")\n        self.journal = OperationJournal(Path(self.temp.name) / \"node.db\")\n\n    async def asyncTearDown(self):\n        await Tortoise.close_connections()\n        self.temp.cleanup()\n\n    async def enqueue(self, command=\"uptime\"):\n        return await operations.enqueue(\"one\", {\"command\": command, \"user_id\": 42})\n\n    async def heartbeat(self, reports=None, reliable=True, busy=False):\n        return await operations.exchange(self.node.id, reports or [], reliable=reliable, busy=busy)\n\n    async def test_lost_response_resends_same_id_and_executes_once(self):\n        op = await self.enqueue()\n        first, _, _ = await self.heartbeat()\n        resent, _, _ = await self.heartbeat()\n        self.assertEqual(first, resent)\n        command = Mock(side_effect=lambda task: self.journal.finish(task[\"operation_id\"], \"done\"))\n        self.journal.execute(first[0], command)\n        self.journal.execute(resent[0], command)\n        command.assert_called_once()\n        tasks, notices, ack = await self.heartbeat(self.journal.reports())\n        self.assertEqual(tasks, [])\n        self.assertEqual(notices, [{\"user_id\": 42, \"command\": \"uptime\", \"result\": \"done\"}])\n        # Losing the acknowledgement does not duplicate notifications or erase the result.\n        self.assertEqual(await self.heartbeat(self.journal.reports()), ([], [], ack))\n        self.journal.acknowledge(ack)\n        self.assertEqual(self.journal.reports(), [])\n        self.journal.execute(first[0], command)\n        command.assert_called_once()\n        saved = await NodeOperation.get(id=op.id)\n        self.assertEqual(saved.status, \"finished\")\n        self.assertEqual(json.loads(saved.result), \"done\")\n\n    async def test_concurrent_enqueue_does_not_overwrite_commands(self):\n        await asyncio.gather(*(self.enqueue(str(i)) for i in range(40)))\n        self.assertEqual(await NodeOperation.all().count(), 40)\n        tasks, _, _ = await self.heartbeat()\n        self.assertEqual(len(tasks), 20)\n        for task in tasks:\n            self.journal.claim(task[\"operation_id\"])\n        next_tasks, _, _ = await self.heartbeat(self.journal.reports())\n        self.assertEqual(len(next_tasks), 20)\n        self.assertTrue(set(t[\"operation_id\"] for t in tasks).isdisjoint(t[\"operation_id\"] for t in next_tasks))\n\n    async def test_legacy_queue_migrates_once_and_retains_old_task_shape(self):\n        old_task = {\"command\": \"reboot\", \"user_id\": 42}\n        self.node.tasks = [old_task]\n        await self.node.save(update_fields=[\"tasks\"])\n        self.assertEqual((await self.heartbeat(reliable=False))[0], [old_task])\n        self.assertEqual((await self.heartbeat(reliable=False))[0], [])\n        self.assertEqual(await NodeOperation.all().count(), 1)\n        self.assertEqual((await NodeOperation.first()).status, \"legacy_sent\")\n        self.assertEqual((await Node.get(id=self.node.id)).tasks, [])\n\n    async def test_schema_upgrade_keeps_existing_node_and_queued_task(self):\n        # This is a disposable database created in asyncSetUp, never the application database.\n        await Tortoise.get_connection(\"default\").execute_script(\"DROP TABLE node_operations\")\n        self.node.tasks = [{\"command\": \"uptime\", \"user_id\": 42}]\n        await self.node.save(update_fields=[\"tasks\"])\n        await Tortoise.generate_schemas()\n        tasks, _, _ = await self.heartbeat()\n        self.assertEqual(len(tasks), 1)\n        self.assertEqual(tasks[0][\"command\"], \"uptime\")\n        self.assertEqual((await Node.get(id=self.node.id)).token_safe, \"secret\")\n\n    async def test_concurrent_legacy_heartbeats_deliver_only_once(self):\n        await self.enqueue(\"reboot\")\n        first, second = await asyncio.gather(self.heartbeat(reliable=False), self.heartbeat(reliable=False))\n        self.assertEqual(len(first[0]) + len(second[0]), 1)\n\n    async def test_downgrade_never_repeats_dispatched_commands(self):\n        await self.enqueue(\"reboot\")\n        await self.heartbeat()\n        await self.enqueue(\"uptime\")\n        tasks, _, _ = await self.heartbeat(reliable=False)\n        self.assertEqual([t[\"command\"] for t in tasks], [\"uptime\"])\n\n    async def test_busy_client_acknowledges_results_without_receiving_commands(self):\n        await self.enqueue()\n        task = (await self.heartbeat())[0][0]\n        self.journal.execute(task, Mock())\n        await self.enqueue()\n        tasks, _, ack = await self.heartbeat(self.journal.reports(), busy=True)\n        self.assertEqual(tasks, [])\n        self.assertEqual(ack, [task[\"operation_id\"]])\n\n    async def test_report_cannot_change_another_nodes_operation(self):\n        op = await self.enqueue()\n        other = await Node.create(token_hash=\"two\", token_safe=\"secret\", name=\"Two\", ip=\"127.0.0.2\")\n        result = await operations.exchange(other.id, [{\"id\": op.delivery_id.hex, \"status\": \"finished\"}], reliable=True, busy=True)\n        self.assertEqual(result, ([], [], []))\n        self.assertEqual((await NodeOperation.get(id=op.id)).status, \"queued\")\n\n    async def test_interrupted_execution_becomes_unknown_without_retry(self):\n        op = await self.enqueue()\n        task = (await self.heartbeat())[0][0]\n        self.journal.claim(task[\"operation_id\"])\n        journal = OperationJournal(self.journal.path)\n        command = Mock()\n        journal.execute(task, command)\n        command.assert_not_called()\n        await self.heartbeat(journal.reports())\n        self.assertEqual((await NodeOperation.get(id=op.id)).status, \"unknown\")\n\n    async def test_database_reopen_preserves_queue_and_history(self):\n        op = await self.enqueue()\n        await Tortoise.close_connections()\n        await Tortoise.init(db_url=self.db_url, modules={\"models\": [\"core.models\"]})\n        await Tortoise.generate_schemas()\n        self.assertEqual((await self.heartbeat())[0][0][\"operation_id\"], op.delivery_id.hex)\n\n    async def test_history_pagination_and_filters(self):\n        await asyncio.gather(*(self.enqueue() for _ in range(53)))\n        rows, before = await operations.history(node_id=self.node.id, status=\"queued\")\n        self.assertEqual(len(rows), 50)\n        older, end = await operations.history(before=before)\n        self.assertEqual(len(older), 3)\n        self.assertIsNone(end)\n        self.assertTrue({r.id for r in rows}.isdisjoint(r.id for r in older))\n        self.assertEqual(await operations.history(status=\"failed\"), ([], None))\n\n    async def test_payload_and_result_encrypted_at_rest(self):\n        op = await self.enqueue()\n        op.result = json.dumps(\"private output\")\n        await op.save()\n        raw = await Tortoise.get_connection(\"default\").execute_query_dict(\"SELECT payload,result FROM node_operations\")\n        self.assertNotIn(\"uptime\", raw[0][\"payload\"])\n        self.assertNotIn(\"private output\", raw[0][\"result\"])\n\n    async def test_invalid_reports_are_ignored(self):\n        for report in (None, 1, {\"id\": \"bad\", \"status\": \"finished\"}, {\"id\": uuid.uuid4().hex, \"status\": []}):\n            self.assertEqual(await self.heartbeat([report]), ([], [], []))\n\n    async def test_traffic_samples_reuse_one_card_with_new_delivery_ids(self):\n        task = {\"command\": \"traffic\", \"user_id\": 42, \"traffic_session\": uuid.uuid4().hex}\n        operation = await operations.enqueue(\"one\", task)\n        created_at = operation.created_at\n        first = (await self.heartbeat())[0][0]\n        self.journal.execute(first, lambda job: self.journal.finish(job[\"operation_id\"], \"sample one\"))\n        _, notices, lost_ack = await self.heartbeat(self.journal.reports())\n        self.assertEqual(notices[0][\"traffic_session\"], task[\"traffic_session\"])\n        operation = await operations.enqueue(\"one\", task, traffic_operation_id=operation.id)\n        self.assertNotEqual(operation.delivery_id.hex, first[\"operation_id\"])\n        self.assertEqual(operation.created_at, created_at)\n        self.assertEqual(json.loads(operation.result), \"sample one\")\n        second, notices, ack = await self.heartbeat(self.journal.reports())\n        self.assertEqual(ack, lost_ack)\n        self.assertEqual(notices, [])  # A repeated old receipt must not replace the new sample.\n        self.journal.acknowledge(ack)\n        self.journal.claim(second[0][\"operation_id\"])\n        await self.heartbeat(self.journal.reports())\n        self.assertEqual(json.loads((await NodeOperation.get(id=operation.id)).result), \"sample one\")\n        self.journal.finish(second[0][\"operation_id\"], \"sample two\")\n        await self.heartbeat(self.journal.reports())\n        self.assertEqual(json.loads((await NodeOperation.get(id=operation.id)).result), \"sample two\")\n        self.assertEqual(await NodeOperation.all().count(), 1)\n\n    async def test_traffic_polling_does_not_accumulate_offline_or_inflight_tasks(self):\n        task = {\"command\": \"traffic\", \"user_id\": 42, \"traffic_session\": uuid.uuid4().hex}\n        operation = await operations.enqueue(\"one\", task)\n        for status in (\"queued\", \"dispatched\", \"running\"):\n            operation.status = status\n            await operation.save()\n            await asyncio.gather(*(operations.enqueue(\"one\", task, traffic_operation_id=operation.id) for _ in range(5)))\n            saved = await NodeOperation.get(id=operation.id)\n            self.assertEqual(saved.delivery_id, operation.delivery_id)\n            self.assertEqual(saved.status, status)\n        self.assertEqual(await NodeOperation.all().count(), 1)\n\n    async def test_concurrent_traffic_refresh_rotates_delivery_id_only_once(self):\n        task = {\"command\": \"traffic\", \"user_id\": 42, \"traffic_session\": uuid.uuid4().hex}\n        operation = await operations.enqueue(\"one\", task)\n        operation.status = \"finished\"\n        await operation.save()\n        refreshed = await asyncio.gather(*(operations.enqueue(\"one\", task, traffic_operation_id=operation.id) for _ in range(5)))\n        self.assertEqual(len({row.delivery_id for row in refreshed}), 1)\n        self.assertNotEqual(refreshed[0].delivery_id, operation.delivery_id)\n\n    async def test_sessions_users_and_one_shot_commands_stay_separate(self):\n        task = {\"command\": \"traffic\", \"user_id\": 42, \"traffic_session\": uuid.uuid4().hex}\n        operation = await operations.enqueue(\"one\", task)\n        for changed in ({\"traffic_session\": uuid.uuid4().hex}, {\"user_id\": 43}, {\"command\": \"reboot\"}):\n            with self.assertRaises(ValueError):\n                await operations.enqueue(\"one\", {**task, **changed}, traffic_operation_id=operation.id)\n        second = await operations.enqueue(\"one\", {**task, \"traffic_session\": uuid.uuid4().hex})\n        self.assertNotEqual(second.id, operation.id)\n        self.assertNotEqual((await self.enqueue()).id, (await self.enqueue()).id)\n\n    async def test_legacy_traffic_client_uses_same_card_and_original_payload(self):\n        task = {\"command\": \"traffic\", \"user_id\": 42, \"traffic_session\": uuid.uuid4().hex}\n        operation = await operations.enqueue(\"one\", task)\n        first = (await self.heartbeat(reliable=False))[0]\n        await operations.enqueue(\"one\", task, traffic_operation_id=operation.id)\n        second = (await self.heartbeat(reliable=False))[0]\n        self.assertEqual(first, second)\n        self.assertNotIn(\"operation_id\", second[0])\n        self.assertEqual(await NodeOperation.all().count(), 1)\n\n\nclass JournalTests(unittest.TestCase):\n    def setUp(self):\n        self.temp = tempfile.TemporaryDirectory()\n        self.addCleanup(self.temp.cleanup)\n        self.journal = OperationJournal(Path(self.temp.name) / \"node.db\")\n        self.id = uuid.uuid4().hex\n\n    def test_concurrent_claim_has_one_winner(self):\n        with ThreadPoolExecutor(max_workers=8) as executor:\n            outcomes = list(executor.map(self.journal.claim, [self.id] * 16))\n        self.assertEqual(sum(outcomes), 1)\n\n    def test_failure_is_persistent_and_not_retried(self):\n        command = Mock(side_effect=RuntimeError(\"offline\"))\n        task = {\"operation_id\": self.id}\n        with self.assertRaises(RuntimeError):\n            self.journal.execute(task, command)\n        self.journal.execute(task, command)\n        command.assert_called_once()\n        self.assertEqual(self.journal.reports()[0][\"status\"], \"failed\")\n\n    def test_legacy_command_keeps_existing_execution_path(self):\n        command = Mock()\n        self.journal.execute({\"command\": \"uptime\"}, command)\n        command.assert_called_once_with({\"command\": \"uptime\"})\n        self.assertEqual(self.journal.reports(), [])\n\n    def test_ack_cannot_remove_running_command(self):\n        self.journal.claim(self.id)\n        self.journal.acknowledge([self.id])\n        self.assertEqual(self.journal.reports()[0][\"status\"], \"running\")\n        self.journal.acknowledge(None)\n\n    def test_unavailable_journal_pauses_commands_without_stopping_heartbeat(self):\n        with self.assertLogs(level=\"ERROR\"):\n            journal = open_journal(Path(self.temp.name) / \"missing\" / \"node.db\")\n        self.assertIsNone(journal)\n        self.assertEqual(heartbeat_state(journal), ([], True))\n        with patch.object(self.journal, \"reports\", side_effect=OSError(\"disk unavailable\")), self.assertLogs(level=\"ERROR\"):\n            self.assertEqual(heartbeat_state(self.journal), ([], True))\n        self.assertEqual(heartbeat_state(self.journal), ([], False))\n\n\nclass HistoryRenderingTests(unittest.TestCase):\n    def test_service_action_names_target_without_exposing_other_parameters(self):\n        sensitive_token = uuid.uuid4().hex\n        with patch.dict(sys.modules, {\"core.i18n\": Mock(), \"core.utils\": Mock()}):\n            from core.web.operation_history import present\n        row = SimpleNamespace(\n            id=1, node_id=2, command=\"service_action\", status=\"queued\", requested_by=42,\n            result=None, created_at=1, updated_at=1,\n            payload=json.dumps({\"action\": \"restart\", \"service\": \"nginx\", \"token\": sensitive_token}),\n        )\n        view = present(row, {2: \"Server\"}, \"en\")\n        self.assertEqual(view[\"command\"], \"Restart: nginx\")\n        self.assertNotIn(sensitive_token, json.dumps(view))\n\n    def test_filters_reject_invalid_values(self):\n        for query in ({\"node_id\": \"abc\"}, {\"node_id\": \"-1\"}, {\"status\": \"<script>\"}, {\"before\": \"-1\"}):\n            with self.assertRaises(ValueError):\n                operations.parse_filters(query)\n\n    def test_template_escapes_server_names_and_results_in_both_languages(self):\n        from jinja2 import Environment, FileSystemLoader, select_autoescape\n        with patch.dict(sys.modules, {\"core.i18n\": Mock(), \"core.utils\": Mock()}):\n            from core.web.operation_history import LABELS\n        env = Environment(loader=FileSystemLoader(Path(__file__).resolve().parents[1] / \"core/templates\"), autoescape=select_autoescape())\n        malicious = '<script>alert(\"private\")</script>'\n        for lang in (\"ru\", \"en\"):\n            rendered = env.get_template(\"operations.html\").render(\n                lang=lang, labels=LABELS[lang], filters={\"node_id\": 0, \"status\": \"\", \"before\": 0},\n                nodes={1: malicious}, statuses=[\"queued\"], next_before=None,\n                rows=[{\"node_id\": 1, \"node_name\": malicious, \"result\": malicious, \"status\": \"finished\"}],\n            )\n            self.assertNotIn(malicious, rendered)\n            self.assertIn(\"&lt;script&gt;\", rendered)\n            self.assertIn(LABELS[lang][\"title\"], rendered)\n\n\nclass HistoryAccessTests(unittest.IsolatedAsyncioTestCase):\n    async def asyncSetUp(self):\n        from aiohttp import web\n        from aiohttp.test_utils import TestClient, TestServer\n        root = Path(__file__).resolve().parents[1]\n        auth = Mock()\n        self.auth = auth\n        auth.get_current_user.side_effect = lambda request: {\n            \"owner\": {\"id\": 1, \"role\": \"users\"}, \"admin\": {\"id\": 2, \"role\": \"admins\"},\n            \"reader\": {\"id\": 3, \"role\": \"users\"},\n        }.get(request.headers.get(\"X-Test-User\"))\n        config = SimpleNamespace(\n            BASE_DIR=str(root), ADMIN_USER_ID=1, DEFAULT_LANGUAGE=\"en\", TG_BOT_NAME=\"Test\",\n            NODE_OFFLINE_TIMEOUT=20,\n        )\n        utils = MagicMock()\n        utils.get_app_version.return_value = \"vtest\"\n        utils.get_web_key.return_value = \"fixture-only-web-key\"\n        utils.encrypt_for_web.side_effect = encrypt_web_fixture\n        utils.encrypted_json_response.side_effect = lambda data, status=200: web.json_response(\n            {\"d\": encrypt_web_fixture(json.dumps(data))}, status=status,\n        )\n        i18n = Mock()\n        i18n.get_user_lang.return_value = \"en\"\n        i18n.get_text.side_effect = lambda key, lang, **kwargs: key\n        deps = {\n            \"core.config\": config, \"core.utils\": utils, \"core.i18n\": i18n,\n            \"core.shared_state\": SimpleNamespace(ALLOWED_USERS={}), \"core.keyboards\": Mock(),\n            \"core.web.auth\": auth, \"core.web.avatar\": Mock(), \"core.nodes_db\": Mock(),\n            \"core.node_updates\": Mock(), \"core.messaging\": Mock(), \"modules.services\": Mock(),\n        }\n        self.modules = patch.dict(sys.modules, deps)\n        self.modules.start()\n        self.addCleanup(self.modules.stop)\n        asset_spec = importlib.util.spec_from_file_location(\"core.web.test_private_assets\", root / \"core/web/private_assets.py\")\n        assets = importlib.util.module_from_spec(asset_spec)\n        asset_spec.loader.exec_module(assets)\n        app = web.Application(middlewares=[assets.protect_private_assets])\n        assets.register_private_assets(app)\n        app.router.add_static(\"/static\", str(root / \"core/static\"))\n        self.shutdown = asyncio.Event()\n        app[\"shutdown_event\"] = self.shutdown\n\n        async def on_shutdown(app):\n            self.shutdown.set()\n\n        app.on_shutdown.append(on_shutdown)\n        for name in (\"views\", \"api_nodes\"):\n            spec = importlib.util.spec_from_file_location(f\"core.web.test_{name}\", root / \"core/web\" / f\"{name}.py\")\n            subject = importlib.util.module_from_spec(spec)\n            spec.loader.exec_module(subject)\n            handler = subject.handle_operations_page if name == \"views\" else subject.list_operations\n            app.router.add_get(\"/operations\" if name == \"views\" else \"/api/operations\", handler)\n            if name == \"api_nodes\":\n                self.api = subject\n                app.router.add_get(\"/api/operations/stream\", subject.stream_operations)\n                app.router.add_get(\"/api/services\", subject.handle_services_list)\n                app.router.add_get(\"/api/services/available\", subject.handle_available_services)\n                app.router.add_get(\"/api/services/info/{name}\", subject.handle_service_info)\n        self.client = TestClient(TestServer(app))\n        await self.client.start_server()\n        self.addAsyncCleanup(self.client.close)\n\n    async def test_service_streams_preserve_authorization_headers_and_event_payloads(self):\n        cases = (\n            (\"/api/services\", \"get_all_services_status\", \"services_list\", False),\n            (\"/api/services/available\", \"get_all_available_services\", \"available_services\", False),\n            (\"/api/services/info/nginx?type=systemd\", \"get_service_info\", \"service_info\", True),\n        )\n        for path, provider_name, event, is_async in cases:\n            with self.subTest(path=path):\n                payload = {\"name\": \"nginx\", \"status\": \"running\"}\n                provider = AsyncMock(return_value=payload) if is_async else Mock(return_value=payload)\n                with patch.object(self.api, provider_name, provider):\n                    anonymous = await self.client.get(path)\n                    self.assertEqual(anonymous.status, 401)\n                    self.assertNotIn(\"text/event-stream\", anonymous.headers.get(\"Content-Type\", \"\"))\n                    provider.assert_not_called()\n                    response = await self.client.get(path, headers={\"X-Test-User\": \"owner\"})\n                    self.assertEqual(response.status, 200)\n                    self.assertEqual(response.headers[\"Content-Type\"], \"text/event-stream\")\n                    self.assertEqual(response.headers[\"Cache-Control\"], \"no-cache\")\n                    self.assertEqual(response.headers[\"Connection\"], \"keep-alive\")\n                    self.assertEqual(await response.text(), f\"event: {event}\\ndata: {json.dumps(payload)}\\n\\n\")\n                    if is_async:\n                        provider.assert_awaited_once_with(\"nginx\", \"systemd\")\n                    else:\n                        provider.assert_called_once_with()\n\n    async def test_anonymous_and_readonly_users_cannot_read_history(self):\n        for path in (\"/operations\", \"/api/operations\", \"/api/operations/stream?ids=1\"):\n            for user in (\"\", \"reader\"):\n                response = await self.client.get(path, headers={\"X-Test-User\": user}, allow_redirects=False)\n                self.assertIn(response.status, (302, 401, 403))\n                self.assertNotIn(\"Server response\", await response.text())\n\n    async def test_owner_and_admin_have_access_without_cache(self):\n        with patch.object(operations, \"history\", return_value=([], None)), patch.object(Node, \"all\", return_value=asyncio.sleep(0, result=[])):\n            response = await self.client.get(\"/operations\", headers={\"X-Test-User\": \"owner\"})\n            self.assertEqual(response.status, 200)\n            self.assertEqual(response.headers[\"Cache-Control\"], \"no-store\")\n            self.assertIn(\"Operations center\", await response.text())\n        with patch.object(operations, \"history\", return_value=([], None)):\n            response = await self.client.get(\"/api/operations\", headers={\"X-Test-User\": \"admin\"})\n            self.assertEqual(response.status, 200)\n            envelope = await response.json()\n            self.assertEqual(json.loads(decrypt_web_fixture(envelope[\"d\"])), {\"operations\": [], \"next_before\": None})\n\n    async def test_bad_filters_return_400(self):\n        for path in (\"/operations\", \"/api/operations\"):\n            response = await self.client.get(path + \"?before=-1\", headers={\"X-Test-User\": \"admin\"})\n            self.assertEqual(response.status, 400)\n\n    async def test_stream_returns_card_updates_and_stops_on_shutdown(self):\n        row = SimpleNamespace(id=8, node_id=1, command=\"traffic\", status=\"finished\", requested_by=42,\n                              payload=\"{}\", result=json.dumps(\"<script>sample</script>\"), created_at=1, updated_at=2)\n        query = Mock()\n        query.order_by = AsyncMock(return_value=[row])\n        with patch.object(NodeOperation, \"filter\", return_value=query) as select:\n            response = await self.client.get(\"/api/operations/stream?ids=8\", headers={\"X-Test-User\": \"admin\"})\n            self.assertEqual(response.status, 200)\n            self.assertEqual(response.headers[\"Cache-Control\"], \"no-store\")\n            self.assertEqual(await response.content.readline(), b\"event: operations\\n\")\n            data = (await response.content.readline()).decode()[6:]\n            self.assertNotIn(\"<script>\", data)\n            updates = json.loads(decrypt_web_fixture(json.loads(data)[\"d\"]))\n            self.assertEqual(updates[0][\"id\"], 8)\n            self.assertEqual(updates[0][\"result\"], \"<script>sample</script>\")\n            self.assertNotIn(\"payload\", updates[0])\n            select.assert_called_once_with(id__in=[8])\n            self.shutdown.set()\n            await asyncio.wait_for(response.read(), timeout=2)\n\n    async def test_stream_rejects_invalid_or_excessive_ids(self):\n        for ids in (\"\", \"-1\", \"abc\", str(2**63), \",\".join(str(i) for i in range(1, 52))):\n            response = await self.client.get(\"/api/operations/stream?ids=\" + ids, headers={\"X-Test-User\": \"admin\"})\n            self.assertEqual(response.status, 400)\n\n    async def test_stream_rechecks_permissions_after_connection(self):\n        self.auth.get_current_user.side_effect = [{\"id\": 2, \"role\": \"admins\"}, None]\n        response = await self.client.get(\"/api/operations/stream?ids=8\", headers={\"X-Test-User\": \"admin\"})\n        self.assertIn(\"event: session_expired\", await response.text())\n\n    async def test_operation_assets_require_admin_even_through_static_aliases(self):\n        for path in (\"/static/js/operations.js\", \"/static/css/operations.css\", \"/static/js//operations.js\"):\n            response = await self.client.get(path)\n            self.assertEqual(response.status, 401)\n            response = await self.client.get(path, headers={\"X-Test-User\": \"reader\"})\n            self.assertEqual(response.status, 403)\n        response = await self.client.get(\"/static/js/operations.js\", headers={\"X-Test-User\": \"admin\"})\n        self.assertEqual(response.status, 200)\n        self.assertEqual(response.headers[\"Cache-Control\"], \"no-store\")\n        self.assertIn(\"initOperations\", await response.text())\n        response = await self.client.get(\"/static/js/panel_navigation.js\", headers={\"X-Test-User\": \"reader\"})\n        self.assertEqual(response.status, 200)\n\n    async def test_initial_history_encrypts_private_display_fields(self):\n        row = SimpleNamespace(id=8, node_id=1, command=\"traffic\", status=\"finished\", requested_by=7654321,\n                              payload=\"{}\", result=json.dumps(\"private output\"), created_at=1, updated_at=2)\n        with patch.object(operations, \"history\", return_value=([row], None)), patch.object(\n            Node, \"all\", return_value=asyncio.sleep(0, result=[SimpleNamespace(id=1, name=\"private node\")]),\n        ):\n            response = await self.client.get(\"/operations\", headers={\"X-Test-User\": \"owner\"})\n            html = await response.text()\n            self.assertEqual(response.status, 200)\n            for private in (\"private node\", \"private output\", \"7654321\"):\n                self.assertNotIn(private, html)\n            self.assertIn(\"data-operation-encrypted\", html)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "support.py": "\"\"\"Dependency stubs for tests that do not need the Telegram runtime.\"\"\"\nimport sys\nfrom types import SimpleNamespace\nfrom unittest.mock import MagicMock\n\n\nCORE_DEPENDENCIES = (\n    \"aiohttp\", \"aiohttp.web\", \"argon2\", \"argon2.exceptions\", \"aiosqlite\",\n    \"requests\", \"PIL\", \"PIL.Image\", \"qrcode\", \"netifaces\", \"sentry_sdk\",\n    \"yaml\", \"docker\", \"asyncssh\", \"tortoise\",\n)\nAIOGRAM_DEPENDENCIES = (\n    \"aiogram\", \"aiogram.filters\", \"aiogram.fsm\", \"aiogram.fsm.context\",\n    \"aiogram.fsm.state\", \"aiogram.fsm.storage\", \"aiogram.fsm.storage.memory\",\n    \"aiogram.types\", \"aiogram.exceptions\",\n)\n\n\ndef mock_optional_modules(names):\n    for name in names:\n        if name not in sys.modules:\n            module = MagicMock()\n            module.__path__ = []\n            module.__spec__ = SimpleNamespace(name=name, origin=None, submodule_search_locations=[])\n            sys.modules[name] = module\n",
  "test_backups.py": "import os\nimport shutil\nimport sys\nimport tempfile\nimport types\nimport unittest\nimport json\nimport time\nimport asyncio\nfrom base64 import b64encode\nfrom unittest.mock import MagicMock, patch, AsyncMock\n\nos.environ.setdefault(\"DATA_ENCRYPTION_KEY\", b64encode(b\"0\" * 32).decode())\nos.environ.setdefault(\"TG_BOT_TOKEN\", \"123456789:TEST_BOT_TOKEN\")\nos.environ.setdefault(\"TG_ADMIN_ID\", \"12345\")\n\nmodules_to_mock = [\n    \"aiohttp\", \"aiohttp.web\", \"argon2\", \"argon2.exceptions\", \"aiosqlite\",\n    \"requests\", \"PIL\", \"PIL.Image\", \"qrcode\",\n    \"netifaces\", \"sentry_sdk\", \"yaml\", \"docker\", \"asyncssh\", \"tortoise\",\n    \"aiogram\", \"aiogram.filters\", \"aiogram.fsm\", \"aiogram.fsm.context\",\n    \"aiogram.fsm.state\", \"aiogram.fsm.storage\", \"aiogram.fsm.storage.memory\",\n    \"aiogram.types\", \"aiogram.exceptions\",\n]\n\nfor m in modules_to_mock:\n    if m not in sys.modules:\n        mod = MagicMock()\n        mod.__path__ = []\n        mod.__spec__ = types.SimpleNamespace(name=m, origin=None, submodule_search_locations=[])\n        sys.modules[m] = mod\n\n# Add project root to sys.path\nsys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), \"..\")))\n\nfrom core import config\nfrom modules import backups\n\n\nclass TestBackups(unittest.TestCase):\n    def setUp(self):\n        self.test_dir = tempfile.mkdtemp()\n        self.orig_config_dir = config.CONFIG_DIR\n        self.orig_log_dir = config.LOG_DIR\n        self.orig_traffic_backup = config.TRAFFIC_BACKUP_DIR\n        self.orig_config_backup = config.CONFIG_BACKUP_DIR\n        self.orig_logs_backup = config.LOGS_BACKUP_DIR\n        self.orig_nodes_backup = config.NODES_BACKUP_DIR\n\n        config.CONFIG_DIR = os.path.join(self.test_dir, \"config\")\n        config.LOG_DIR = os.path.join(self.test_dir, \"logs\")\n        config.TRAFFIC_BACKUP_DIR = os.path.join(self.test_dir, \"backups\", \"traffic\")\n        config.CONFIG_BACKUP_DIR = os.path.join(self.test_dir, \"backups\", \"config\")\n        config.LOGS_BACKUP_DIR = os.path.join(self.test_dir, \"backups\", \"logs\")\n        config.NODES_BACKUP_DIR = os.path.join(self.test_dir, \"backups\", \"nodes\")\n\n        for d in [\n            config.CONFIG_DIR,\n            config.LOG_DIR,\n            config.TRAFFIC_BACKUP_DIR,\n            config.CONFIG_BACKUP_DIR,\n            config.LOGS_BACKUP_DIR,\n            config.NODES_BACKUP_DIR,\n        ]:\n            os.makedirs(d, exist_ok=True)\n\n        # Update BACKUP_TYPES to point to test paths\n        backups.BACKUP_TYPES[\"traffic\"][\"dir\"] = config.TRAFFIC_BACKUP_DIR\n        backups.BACKUP_TYPES[\"config\"][\"dir\"] = config.CONFIG_BACKUP_DIR\n        backups.BACKUP_TYPES[\"logs\"][\"dir\"] = config.LOGS_BACKUP_DIR\n        backups.BACKUP_TYPES[\"nodes\"][\"dir\"] = config.NODES_BACKUP_DIR\n\n    def tearDown(self):\n        config.CONFIG_DIR = self.orig_config_dir\n        config.LOG_DIR = self.orig_log_dir\n        config.TRAFFIC_BACKUP_DIR = self.orig_traffic_backup\n        config.CONFIG_BACKUP_DIR = self.orig_config_backup\n        config.LOGS_BACKUP_DIR = self.orig_logs_backup\n        config.NODES_BACKUP_DIR = self.orig_nodes_backup\n\n        backups.BACKUP_TYPES[\"traffic\"][\"dir\"] = config.TRAFFIC_BACKUP_DIR\n        backups.BACKUP_TYPES[\"config\"][\"dir\"] = config.CONFIG_BACKUP_DIR\n        backups.BACKUP_TYPES[\"logs\"][\"dir\"] = config.LOGS_BACKUP_DIR\n        backups.BACKUP_TYPES[\"nodes\"][\"dir\"] = config.NODES_BACKUP_DIR\n\n        shutil.rmtree(self.test_dir, ignore_errors=True)\n\n    def test_backups_tier_is_always_on_in_bot(self):\n        \"\"\"Verify modules.backups is ALWAYS_ON so auto-backup background task starts and is not killed.\"\"\"\n        import ast\n        bot_path = os.path.join(os.path.dirname(__file__), \"..\", \"bot.py\")\n        with open(bot_path, \"r\", encoding=\"utf-8\") as f:\n            tree = ast.parse(f.read(), filename=\"bot.py\")\n\n        tier_found = None\n        for node in tree.body:\n            if isinstance(node, ast.Assign):\n                for target in node.targets:\n                    if isinstance(target, ast.Name) and target.id == \"MODULE_CONFIG\":\n                        if isinstance(node.value, ast.Dict):\n                            for k, v in zip(node.value.keys, node.value.values):\n                                if isinstance(k, ast.Constant) and k.value == \"modules.backups\":\n                                    if isinstance(v, ast.Dict):\n                                        for subk, subv in zip(v.keys, v.values):\n                                            if isinstance(subk, ast.Constant) and subk.value == \"tier\":\n                                                if isinstance(subv, ast.Attribute):\n                                                    tier_found = subv.attr\n        self.assertEqual(tier_found, \"ALWAYS_ON\")\n\n    def test_create_config_backup(self):\n        \"\"\"Verify config backup zip creation.\"\"\"\n        dummy_file = os.path.join(config.CONFIG_DIR, \"system_config.json\")\n        with open(dummy_file, \"w\") as f:\n            f.write('{\"test\": 123}')\n\n        filepath = backups._create_backup_file(\"config\")\n        self.assertIsNotNone(filepath)\n        self.assertTrue(os.path.exists(filepath))\n        self.assertTrue(filepath.endswith(\".zip\"))\n\n    def test_create_logs_backup(self):\n        \"\"\"Verify logs backup zip creation.\"\"\"\n        dummy_log = os.path.join(config.LOG_DIR, \"bot.log\")\n        with open(dummy_log, \"w\") as f:\n            f.write(\"test log line\")\n\n        filepath = backups._create_backup_file(\"logs\")\n        self.assertIsNotNone(filepath)\n        self.assertTrue(os.path.exists(filepath))\n        self.assertTrue(filepath.endswith(\".zip\"))\n\n    def test_create_nodes_backup(self):\n        \"\"\"Verify nodes backup zip creation.\"\"\"\n        nodes_db = os.path.join(config.CONFIG_DIR, \"nodes.db\")\n        with open(nodes_db, \"wb\") as f:\n            f.write(b\"SQLITE_DUMMY_DATA\")\n\n        filepath = backups._create_backup_file(\"nodes\")\n        self.assertIsNotNone(filepath)\n        self.assertTrue(os.path.exists(filepath))\n        self.assertTrue(filepath.endswith(\".zip\"))\n\n    @patch(\"modules.traffic.get_current_traffic_total\", return_value=(1024, 2048))\n    @patch(\"modules.traffic.save_backup_file\")\n    def test_create_traffic_backup(self, mock_save, mock_get_total):\n        \"\"\"Verify traffic backup creates a file and saves total traffic.\"\"\"\n        def fake_save(rx, tx):\n            ts = int(time.time())\n            path = os.path.join(config.TRAFFIC_BACKUP_DIR, f\"traffic_backup_{ts}.json\")\n            with open(path, \"w\") as f:\n                json.dump({\"rx\": rx, \"tx\": tx}, f)\n        mock_save.side_effect = fake_save\n\n        filepath = backups._create_backup_file(\"traffic\")\n        self.assertIsNotNone(filepath)\n        self.assertTrue(os.path.exists(filepath))\n\n    def test_rotate_backups(self):\n        \"\"\"Verify backup rotation keeps at most MAX_BACKUPS_PER_TYPE files.\"\"\"\n        for i in range(backups.MAX_BACKUPS_PER_TYPE + 3):\n            file_path = os.path.join(config.CONFIG_BACKUP_DIR, f\"config_backup_{i}.zip\")\n            with open(file_path, \"w\") as f:\n                f.write(\"content\")\n            # Set staggered mtimes\n            os.utime(file_path, (1000 + i, 1000 + i))\n\n        backups._rotate_backups(\"config\")\n        remaining = backups._list_backup_files(\"config\")\n        self.assertEqual(len(remaining), backups.MAX_BACKUPS_PER_TYPE)\n\n    def test_periodic_backups_task_triggers_all_types(self):\n        \"\"\"Verify periodic_backups_task invokes backups for traffic, config, logs, and nodes.\"\"\"\n        created_types = []\n\n        def fake_create(backup_type):\n            created_types.append(backup_type)\n            return f\"fake_{backup_type}.zip\"\n\n        with patch(\"asyncio.sleep\", new_callable=AsyncMock) as mock_sleep:\n            call_count = 0\n            async def fast_sleep(dur):\n                nonlocal call_count\n                call_count += 1\n                if call_count >= 3:\n                    raise asyncio.CancelledError()\n            mock_sleep.side_effect = fast_sleep\n\n            with patch.object(config, \"BACKUP_INTERVAL\", 10), \\\n                 patch.object(backups, \"BACKUP_INTERVAL_STEP\", 10), \\\n                 patch.object(backups, \"_create_backup_file\", side_effect=fake_create):\n                try:\n                    asyncio.run(backups.periodic_backups_task())\n                except asyncio.CancelledError:\n                    pass\n\n        self.assertIn(\"traffic\", created_types)\n        self.assertIn(\"config\", created_types)\n        self.assertIn(\"logs\", created_types)\n        self.assertIn(\"nodes\", created_types)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
    "test_browser_utils.cjs": "const assert = require('node:assert/strict');\nconst fs = require('node:fs');\nconst vm = require('node:vm');\nconst { test } = require('node:test');\n\nconst helpers = fs.readFileSync('core/static/js/browser_utils.js', 'utf8');\nconst common = fs.readFileSync('core/static/js/common.js', 'utf8');\nconst actions = common.slice(common.indexOf('window.clearLogs ='), common.indexOf(\"document.addEventListener('keydown'\", common.indexOf('window.clearLogs =')));\n\nfunction fixture({ fixedSize = true, confirmed = true, response = { ok: true }, error } = {}) {\n    const classes = new Set(['bg-red-50']);\n    const button = {\n        childNodes: [{ markup: '<span>Original</span>' }], disabled: false,\n        replaceChildren(...nodes) { this.childNodes = nodes; },\n        dataset: { fixedSize: String(fixedSize) }, style: { width: '', height: '' },\n        classList: {\n            add(...names) { for (const name of names) classes.add(name); },\n            remove(...names) { for (const name of names) classes.delete(name); },\n        },\n    };\n    Object.defineProperty(button, 'className', {\n        get: () => [...classes].join(' '),\n        set: value => {\n            classes.clear();\n            button.classList.add(...value.split(/\\s+/).filter(Boolean));\n        },\n    });\n    const requests = [], alerts = [], timers = [], sanitized = [];\n    const context = {\n        window: {\n            showModalConfirm: async () => confirmed,\n            showModalAlert: async (...args) => alerts.push(args),\n        },\n        document: { cookie: 'other_csrf_token=bad; csrf_token=a%2Bb%3D', getElementById: () => button },\n        I18N: {\n            web_error: 'Error: {error}', web_conn_error: 'Connection: {error}',\n            web_error_short: 'Error title', web_conn_error_short: 'Connection title',\n            web_logs_cleared_alert: 'Cleared!', web_logs_clearing: 'Clearing...',\n            web_clear_logs_confirm: 'Clear?', web_traffic_reset_confirm: 'Reset?',\n            web_traffic_reset_no_emoji: 'Done!', modal_title_confirm: 'Confirm',\n        },\n        DOMPurify: { sanitize: html => { sanitized.push(html); return { markup: html }; } },\n        getComputedStyle: () => ({ width: '120px', height: '40px' }),\n        setTimeout: (callback, delay, ...args) => timers.push({ callback, delay, args }),\n        fetch: async (url, options) => {\n            requests.push({ url, options });\n            if (error) throw error;\n            return response;\n        },\n    };\n    createBrowserContext(context);\n    vm.runInContext(helpers + '\\n' + actions, context);\n    return { context, button, classes, requests, alerts, timers, sanitized };\n}\n\nfor (const fixedSize of [true, false]) {\n    test(`maintenance actions preserve their requests and button layout (fixed: ${fixedSize})`, async () => {\n        for (const [action, url, payload] of [\n            ['clearLogs', '/api/logs/clear', { type: 'all' }],\n            ['resetTrafficSettings', '/api/traffic/reset', undefined],\n        ]) {\n            const { context, button, classes, requests, timers, sanitized } = fixture({ fixedSize });\n            const original = button.childNodes[0];\n            await context.window[action]();\n            assert.equal(requests[0].url, url);\n            assert.equal(requests[0].options.method, 'POST');\n            assert.equal(requests[0].options.body, payload && JSON.stringify(payload));\n            if (payload) assert.equal(requests[0].options.headers['Content-Type'], 'application/json');\n            assert.equal(button.disabled, true);\n            assert.equal(button.style.width, fixedSize ? '120px' : '');\n            assert.equal(classes.has('bg-green-600'), true);\n            assert.equal(timers.length, 1);\n            assert.equal(timers[0].delay, 2000);\n            assert.match(sanitized[0], /animate-spin/);\n            assert.match(button.childNodes[0].markup, action === 'clearLogs' ? /Cleared!/ : /Done!/);\n            timers[0].callback(...timers[0].args);\n            assert.equal(button.childNodes[0], original);\n            assert.equal(button.disabled, false);\n            assert.equal(button.style.width, '');\n            assert.equal(classes.has('bg-green-600'), false);\n            assert.equal(classes.has('bg-red-50'), true);\n        }\n    });\n}\n\ntest('cancelled confirmation leaves both maintenance actions untouched', async () => {\n    const { context, requests, button, timers } = fixture({ confirmed: false });\n    await context.window.clearLogs();\n    await context.window.resetTrafficSettings();\n    assert.equal(requests.length, 0);\n    assert.equal(timers.length, 0);\n    assert.equal(button.childNodes[0].markup, '<span>Original</span>');\n    assert.equal(button.disabled, false);\n});\n\ntest('API and network failures restore button contents, dimensions and availability', async () => {\n    for (const options of [\n        { response: { ok: false, json: async () => ({ error: 'Denied' }) } },\n        { error: new Error('offline') },\n        { response: { ok: false, json: async () => { throw new Error('invalid JSON'); } } },\n    ]) {\n        const { context, button, alerts, timers } = fixture(options);\n        button.style.width = '80%';\n        await context.window.clearLogs();\n        assert.equal(alerts.length, 1);\n        assert.match(alerts[0][0], options.error ? /offline/ : /Denied|invalid JSON/);\n        assert.equal(button.childNodes[0].markup, '<span>Original</span>');\n        assert.equal(button.disabled, false);\n        assert.equal(button.style.width, '80%');\n        assert.equal(button.style.height, '');\n        assert.equal(timers.length, 0);\n    }\n});\n\ntest('shared CSRF reader matches the complete cookie name and decodes its value', () => {\n    const { context } = fixture();\n    assert.equal(context.getCsrfToken(), 'a+b=');\n    context.document.cookie = 'other_csrf_token=bad';\n    assert.equal(context.getCsrfToken(), '');\n});\n\ntest('mutating panel fetches still attach the shared CSRF token', async () => {\n    const { context, requests } = fixture();\n    context.window.fetch = context.fetch;\n    context.window.location = { origin: 'https://panel.example' };\n    context.URL = URL;\n    context.Headers = Headers;\n    context.Request = Request;\n    const patchStart = common.indexOf('(function patchFetchWithCsrf()');\n    const patchEnd = common.indexOf('})();', patchStart) + 5;\n    vm.runInContext(common.slice(patchStart, patchEnd), context);\n    await context.window.fetch('/api/logs/clear', { method: 'POST' });\n    assert.equal(requests[0].options.headers.get('X-CSRF-Token'), 'a+b=');\n});\n\ntest('secureFetch confines requests and redirects to the panel', async () => {\n    const { context, requests } = fixture({ response: { status: 200, json: async () => ({ ok: true }) } });\n    context.window.location = { origin: 'https://panel.example' };\n    context.window.fetch = context.fetch;\n    Object.assign(context, { URL, Request });\n    vm.runInContext(common.slice(common.indexOf('async function secureFetch('), common.indexOf('function sseRequest(')), context);\n    for (const url of ['https://other.example/api', '//other.example/api', 'https://user@panel.example/api']) {\n        await assert.rejects(context.secureFetch(url), /same-origin/);\n    }\n    assert.equal(requests.length, 0);\n    await context.secureFetch('/api/status', { mode: 'cors', redirect: 'follow' });\n    assert.equal(requests[0].url.url, 'https://panel.example/api/status');\n    assert.equal(requests[0].options.mode, 'same-origin');\n    assert.equal(requests[0].options.redirect, 'error');\n});\n\ntest('browser reads authenticated Fernet data from Python and rejects a changed signature', () => {\n    const { context } = fixture();\n    context.CryptoJS = require('../core/static/vendor/crypto-js.min.js');\n    context.WEB_KEY = '000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f';\n    const token = 'fw1:gAAAAABq_ee1pAlIymOv4G_crpl1swi6iIL4p1MaN2o5RFxwLTRfw2PLMdNcMB8JBc6468VdIRx5cyeiTm9rYEpcMQffnUZz0l6aBIxsK8UX2kyvw5HC-Qz6Pj1hUaBbhPhp39B81vuKRsKuD3-BYYRbQHN8gQkezw==';\n    assert.equal(context.decryptData(token), 'Проверка веб-панели: status ✓');\n    const bytes = Buffer.from(token.slice(4), 'base64url');\n    bytes[bytes.length - 1] ^= 1;\n    assert.throws(() => context.decryptData('fw1:' + bytes.toString('base64url')));\n    assert.equal(context.decryptData('2001:db8::1'), '2001:db8::1');\n    assert.equal(context.decryptData(context.encryptData('Проверка веб-панели: status ✓')), 'Проверка веб-панели: status ✓');\n});\n\ntest('settings action failures are handled and the expanded button is always restored', async () => {\n    const source = fs.readFileSync('core/static/js/settings.js', 'utf8');\n    const start = source.indexOf('let settingsBtnTimer = null;');\n    const end = source.indexOf('// --- Meta/SEO Modal Logic ---', start);\n    for (const fail of [false, true]) {\n        const classes = new Set();\n        const timers = [], errors = [], messages = [];\n        let calls = 0, blurred = false;\n        const button = {\n            closest: () => null,\n            classList: { add: name => classes.add(name), remove: name => classes.delete(name) },\n            blur() { blurred = true; }\n        };\n        const context = createBrowserContext({\n            window: { I18N: {}, showToast: message => messages.push(message) },\n            document: { documentElement: { lang: 'ru' } },\n            console: { error: (...args) => errors.push(args) },\n            setTimeout: callback => { timers.push(callback); return 1; }, clearTimeout() {}\n        });\n        vm.runInContext(source.slice(start, end), context);\n        await context.handleSettingsBtnClick(button, async () => {\n            calls++;\n            if (fail) throw new Error('request failed');\n        });\n        assert.equal(calls, 1);\n        assert.equal(errors.length, fail ? 1 : 0);\n        assert.equal(messages.length, fail ? 1 : 0);\n        assert.equal(classes.has('force-expanded'), true);\n        assert.equal(timers.length, 1);\n        timers[0]();\n        assert.equal(classes.has('force-expanded'), false);\n        assert.equal(blurred, true);\n    }\n});\n\n\ntest('animation randomness rejects biased tail values and invalid limits', () => {\n    const samples = [0xffffffff, 7, 0xffffffff];\n    let calls = 0;\n    const context = createBrowserContext({\n        crypto: { getRandomValues(buffer) { calls++; buffer[0] = samples.shift(); return buffer; } }\n    });\n    const start = common.indexOf('function randomInteger(');\n    const end = common.indexOf('window.startScrambleAnimation', start);\n    vm.runInContext(common.slice(start, end), context);\n    assert.equal(context.randomInteger(3), 1);\n    assert.equal(calls, 2);\n    assert.equal(context.randomAnimationFraction(), 0xffffffff / 0x100000000);\n    for (const invalid of [0, -1, 1.5, NaN, Infinity, 0x100000001]) {\n        assert.throws(() => context.randomInteger(invalid), { name: 'RangeError' });\n    }\n    assert.equal(calls, 3);\n});\n\nfunction createBrowserContext(globals) {\n    if (globals.window === globals) return vm.createContext(globals);\n    const browser = globals.window || {};\n    Object.assign(globals, browser);\n    for (const key of Object.keys(globals)) {\n        if (key === 'window') continue;\n        Object.defineProperty(browser, key, {\n            configurable: true,\n            get: () => globals[key],\n            set: value => { globals[key] = value; }\n        });\n    }\n    globals.window = new Proxy(browser, {\n        get: (target, key) => Reflect.has(target, key) ? Reflect.get(target, key) : Reflect.get(globals, key),\n        set: (target, key, value) => { globals[key] = value; Reflect.set(target, key, value); return true; }\n    });\n    return vm.createContext(globals);\n}\n\nfunction runBrowserCode(source, globals) { return vm.runInContext(source, createBrowserContext(globals)); }\n",
  "test_chart_range.cjs": "const assert = require('node:assert/strict');\nconst fs = require('node:fs');\nconst vm = require('node:vm');\nconst { test } = require('node:test');\n\nconst source = fs.readFileSync('core/static/js/chart_range.js', 'utf8');\n\nfunction fixture() {\n    const saved = new Map();\n    const context = {\n        window: { addEventListener() {} },\n        document: { addEventListener() {}, removeEventListener() {}, hidden: false },\n        localStorage: {\n            getItem: key => saved.get(key) ?? null,\n            setItem: (key, value) => saved.set(key, value),\n            removeItem: key => saved.delete(key),\n        },\n        URLSearchParams, clearTimeout, setTimeout, console,\n        EventSource: class {\n            constructor(url) { this.url = url; }\n            addEventListener() {}\n            close() {}\n        },\n    };\n    vm.runInNewContext(source, context);\n    function make(id, opts = {}) {\n        return context.window.createChartRangeController({\n            key: id ? 'nodeNetChart' : 'agentChart', network: true,\n            getSource: () => id ? { source: 'node', node_id: id } : { source: 'agent' },\n            ...opts,\n        });\n    }\n    return { context, saved, make };\n}\n\ntest('restores independent agent and node choices, including first stream request', () => {\n    const { make } = fixture();\n    for (const [id, name] of [[null, 'docker0'], [1, 'eth0'], [2, 'ens3']]) {\n        const original = make(id);\n        original.setInterface(name);\n        original.destroy();\n    }\n    for (const [id, name] of [[null, 'docker0'], [1, 'eth0'], [2, 'ens3']]) {\n        const restored = make(id).start();\n        assert.equal(restored.getInterface(), name);\n        const params = new URL(restored.stream.url, 'https://example.test').searchParams;\n        assert.equal(params.get('interface'), name);\n        assert.equal(params.get('node_id'), id ? String(id) : null);\n        restored.destroy();\n    }\n});\n\ntest('reset removes persisted choice and notifies only on change', () => {\n    const { make, saved } = fixture();\n    const changes = [];\n    const ctl = make(1, { onInterfaceChange: value => changes.push(value) });\n    ctl.setInterface('eth0');\n    ctl.setInterface('eth0');\n    ctl.setInterface('');\n    assert.deepEqual(changes, ['eth0', '']);\n    assert.equal(make(1).getInterface(), '');\n    assert.equal(saved.has('chartInterface:nodeNetChart_node_1'), false);\n});\n\ntest('explicit initial interface wins and invalid values normalize consistently', () => {\n    const { make } = fixture();\n    make(1).setInterface('eth0');\n    assert.equal(make(1, { initialInterface: 'wg0' }).getInterface(), 'wg0');\n    for (const value of [null, 123, {}, '']) {\n        const ctl = make(1, { initialInterface: value });\n        assert.equal(ctl.getInterface(), '');\n        ctl.setInterface(value);\n        assert.equal(ctl.getInterface(), '');\n    }\n});\n\ntest('disabled localStorage does not break selection or streaming', () => {\n    const { context, make } = fixture();\n    for (const operation of ['getItem', 'setItem', 'removeItem']) {\n        context.localStorage[operation] = () => { throw Error('storage disabled'); };\n    }\n    const ctl = make(1);\n    assert.equal(ctl.getInterface(), '');\n    ctl.setInterface('eth0').start();\n    assert.equal(new URL(ctl.stream.url, 'https://example.test').searchParams.get('interface'), 'eth0');\n    ctl.setInterface('');\n    ctl.destroy();\n});\n",
  "test_click_spam.cjs": "const assert = require('node:assert/strict');\nconst fs = require('node:fs');\nconst vm = require('node:vm');\nconst { test } = require('node:test');\nconst dashboard = fs.readFileSync('core/static/js/dashboard.js', 'utf8');\nconst common = fs.readFileSync('core/static/js/common.js', 'utf8');\n\nfunction fixture() {\n    let nextTimer = 0;\n    const timers = new Map();\n    const sources = [];\n    const logs = { style: {}, offsetHeight: 200, innerHTML: '', classList: { remove() {}, add() {} } };\n    const services = { innerHTML: '' };\n    const elements = new Map([['logsContainer', logs], ['services-container', services]]);\n    class EventSource {\n        constructor(url) { this.url = url; this.readyState = 0; this.listeners = new Map(); sources.push(this); }\n        addEventListener(name, fn) { this.listeners.set(name, fn); }\n        close() { this.readyState = 2; }\n        emit(name, data) { this.listeners.get(name)?.({ data: JSON.stringify(data) }); }\n    }\n    const context = vm.createContext({\n        console: { error() {}, log() {}, debug() {} }, EventSource, USER_ROLE: 'admins', I18N: {},\n        document: { getElementById: id => elements.get(id) || null, addEventListener() {} },\n        localStorage: { getItem: () => null, setItem() {} },\n        addEventListener() {},\n        setTimeout(fn, delay) { const id = ++nextTimer; timers.set(id, { fn, delay }); return id; },\n        clearTimeout(id) { timers.delete(id); }, clearInterval() {},\n        DOMPurify: { sanitize: html => html }, decryptApiResponse: value => value,\n        showModalConfirm: async () => true, showModalAlert() {}, i18n: {},\n    });\n    context.window = context;\n    vm.runInContext(common.slice(common.indexOf('const pendingSSERequests ='), common.indexOf('window.__chartRegistry =')), context);\n    vm.runInContext(dashboard, context);\n    vm.runInContext(`\n        selectLogFilter = () => {};\n        renderServiceLogsTab = () => {};\n        closeServiceLogsDropdown = () => {};\n        setLogLoading = () => {};\n        renderServices = () => {};\n    `, context);\n    return {\n        context, sources, elements, timers,\n        runTimers(delay) {\n            for (const [id, timer] of [...timers]) {\n                if (timer.delay !== delay) continue;\n                timers.delete(id); timer.fn();\n            }\n        },\n        call(code) { return vm.runInContext(code, context); }\n    };\n}\n\ntest('log click spam opens one stream and an active or connecting stream is reused', () => {\n    const f = fixture();\n    for (let i = 0; i < 100; i++) f.context.switchLogType('bot');\n    assert.equal(f.sources.length, 0);\n    f.runTimers(150);\n    assert.equal(f.sources.length, 1);\n    for (let i = 0; i < 100; i++) f.context.switchLogType('bot');\n    f.runTimers(150);\n    assert.equal(f.sources.length, 1);\n    f.sources[0].readyState = 1;\n    f.context.switchLogType('bot');\n    f.runTimers(150);\n    assert.equal(f.sources.length, 1);\n});\n\ntest('rapid log switching opens only the final selection and can reopen a closed stream', () => {\n    const f = fixture();\n    for (let i = 0; i < 50; i++) f.context.switchLogType(i % 2 ? 'sys' : 'bot');\n    f.runTimers(150);\n    assert.equal(f.sources.length, 1);\n    assert.ok(f.sources[0].url.endsWith('type=sys'));\n    f.sources[0].close();\n    f.context.switchLogType('sys');\n    f.runTimers(150);\n    assert.equal(f.sources.length, 2);\n});\n\ntest('same service reads share one pending request and failures release the lock', async () => {\n    const f = fixture();\n    const first = f.context.sseRequest('/api/services', 'services_list');\n    for (let i = 0; i < 50; i++) assert.equal(f.context.sseRequest('/api/services', 'services_list'), first);\n    assert.equal(f.sources.length, 1);\n    f.sources[0].emit('services_list', { services: [] });\n    await first;\n    const retry = f.context.sseRequest('/api/services', 'services_list');\n    assert.equal(f.sources.length, 2);\n    f.sources[1].emit('error', {});\n    await assert.rejects(retry, /SSE Error/);\n    const third = f.context.sseRequest('/api/services', 'services_list');\n    f.sources[2].emit('services_list', {});\n    await third;\n});\n\ntest('service reads time out rather than retaining the spam lock forever', async () => {\n    const f = fixture();\n    const request = f.context.sseRequest('/api/services', 'services_list');\n    f.runTimers(15000);\n    await assert.rejects(request, /timed out/);\n    assert.equal(f.sources[0].readyState, 2);\n    const retry = f.context.sseRequest('/api/services', 'services_list');\n    f.sources[1].emit('services_list', {});\n    await retry;\n});\n\ntest('service refresh spam renders once and reuses the live subscription', async () => {\n    const f = fixture();\n    const first = f.call('loadServices()');\n    for (let i = 0; i < 100; i++) assert.equal(f.call('loadServices()'), first);\n    assert.equal(f.sources.length, 1);\n    f.sources[0].emit('services_list', []);\n    await first;\n    assert.equal(f.sources.length, 2);\n    const refresh = f.call('loadServices()');\n    f.sources[2].emit('services_list', []);\n    await refresh;\n    assert.equal(f.sources.filter(source => source.url === '/api/events/services').length, 1);\n});\n\ntest('leaving the dashboard closes services and cancels queued log switches and reconnects', () => {\n    const f = fixture();\n    f.call('initServicesSSE()');\n    f.sources[0].onerror(new Error('offline'));\n    f.context.switchLogType('bot');\n    f.call('cleanupDashboardSources()');\n    f.runTimers(150);\n    f.runTimers(5000);\n    assert.equal(f.sources.length, 1);\n    assert.equal(f.sources[0].readyState, 2);\n});\n\ntest('service controls ignore repeat clicks while confirming and executing', async () => {\n    const f = fixture();\n    let confirm, finish, requests = 0;\n    f.context.showModalConfirm = () => new Promise(resolve => { confirm = resolve; });\n    f.context.fetch = async () => { requests++; await new Promise(resolve => { finish = resolve; }); return { json: async () => ({ status: 'ok' }) }; };\n    f.call('loadServices = () => {}');\n    const first = f.call(\"controlService('nginx', 'systemd', 'restart')\");\n    for (let i = 0; i < 50; i++) await f.call(\"controlService('nginx', 'systemd', 'restart')\");\n    confirm(true);\n    await new Promise(resolve => setImmediate(resolve));\n    assert.equal(requests, 1);\n    for (let i = 0; i < 50; i++) await f.call(\"controlService('nginx', 'systemd', 'restart')\");\n    finish(); await first;\n    assert.equal(f.call('pendingServiceControls.size'), 0);\n});\n\ntest('dashboard cleanup closes an active services stream and ignores its late events', () => {\n    const f = fixture();\n    let renders = 0;\n    f.context.renderServices = () => { renders++; };\n    f.call('initServicesSSE()');\n    f.call('cleanupDashboardSources()');\n    assert.equal(f.sources[0].readyState, 2);\n    f.sources[0].emit('services', { services: [] });\n    assert.equal(renders, 0);\n});\n\ntest('cancelled service confirmations release the lock for another attempt', async () => {\n    const f = fixture();\n    let confirmations = 0;\n    f.context.showModalConfirm = async () => { confirmations++; return false; };\n    await f.call(\"controlService('nginx', 'systemd', 'restart')\");\n    await f.call(\"controlService('nginx', 'systemd', 'restart')\");\n    assert.equal(confirmations, 2);\n    assert.equal(f.call('pendingServiceControls.size'), 0);\n});\n",
  "test_client_alerts.py": "\"\"\"\ntests/test_client_alerts.py - Comprehensive tests for client alerts features:\nsettings (mute all messages, mute broadcasts, per-node mute), media buffering,\nkeyboard generation, pinning, broadcast deletion, and service message filtering.\n\"\"\"\n\nimport os\nimport sys\nimport unittest\nfrom base64 import b64encode\nfrom contextlib import contextmanager\nfrom unittest.mock import AsyncMock, MagicMock, patch\n\nfrom tests.support import CORE_DEPENDENCIES, mock_optional_modules\n\n\nclass MockInlineKeyboardButton:\n    def __init__(self, text=\"\", callback_data=None, url=None, **kwargs):\n        self.text = text\n        self.callback_data = callback_data\n        self.url = url\n\n\nclass MockKeyboardButton:\n    def __init__(self, text=\"\", **kwargs):\n        self.text = text\n\n\nclass MockReplyKeyboardMarkup:\n    def __init__(self, keyboard=None, **kwargs):\n        self.keyboard = keyboard or []\n\n\nclass MockInlineKeyboardMarkup:\n    def __init__(self, inline_keyboard=None, **kwargs):\n        self.inline_keyboard = inline_keyboard or []\n\n\nclass MockStatesGroup:\n    pass\n\n\nclass ClientAlertsFeatureTests(unittest.IsolatedAsyncioTestCase):\n    @classmethod\n    def setUpClass(cls):\n        os.environ.setdefault(\"DATA_ENCRYPTION_KEY\", b64encode(b\"0\" * 32).decode())\n        os.environ.setdefault(\"TG_BOT_TOKEN\", \"123456789:TEST_BOT_TOKEN\")\n        os.environ.setdefault(\"TG_ADMIN_ID\", \"12345\")\n        os.environ.setdefault(\"ALERT_BOT_TOKEN\", \"987654321:TEST_ALERT_TOKEN\")\n\n        mock_optional_modules((*CORE_DEPENDENCIES, \"psutil\"))\n\n        mock_aiogram = MagicMock()\n        mock_types = MagicMock()\n        mock_types.InlineKeyboardButton = MockInlineKeyboardButton\n        mock_types.InlineKeyboardMarkup = MockInlineKeyboardMarkup\n        mock_types.KeyboardButton = MockKeyboardButton\n        mock_types.ReplyKeyboardMarkup = MockReplyKeyboardMarkup\n        mock_aiogram.types = mock_types\n\n        mock_dp = MagicMock()\n        mock_dp.message.return_value = lambda f: f\n        mock_dp.callback_query.return_value = lambda f: f\n        mock_dp.message_reaction.return_value = lambda f: f\n        mock_dp.poll_answer.return_value = lambda f: f\n        mock_aiogram.Dispatcher.return_value = mock_dp\n        mock_aiogram.fsm.state.StatesGroup = MockStatesGroup\n        mock_aiogram.fsm.state.State = MagicMock\n\n        sys.modules[\"aiogram\"] = mock_aiogram\n        sys.modules[\"aiogram.types\"] = mock_types\n        sys.modules[\"aiogram.filters\"] = mock_aiogram.filters\n        sys.modules[\"aiogram.exceptions\"] = mock_aiogram.exceptions\n        sys.modules[\"aiogram.utils\"] = mock_aiogram.utils\n        sys.modules[\"aiogram.utils.backoff\"] = mock_aiogram.utils.backoff\n        sys.modules[\"aiogram.fsm\"] = mock_aiogram.fsm\n        sys.modules[\"aiogram.fsm.context\"] = mock_aiogram.fsm.context\n        sys.modules[\"aiogram.fsm.state\"] = mock_aiogram.fsm.state\n        sys.modules[\"aiogram.fsm.storage\"] = mock_aiogram.fsm.storage\n        sys.modules[\"aiogram.fsm.storage.memory\"] = mock_aiogram.fsm.storage.memory\n\n        import core\n        from core import config\n\n        core.nodes_db = MagicMock()\n        sys.modules[\"core.nodes_db\"] = core.nodes_db\n\n        from modules import client_alerts\n\n        cls.config = config\n        cls.alerts = client_alerts\n\n    @classmethod\n    def tearDownClass(cls):\n        import contextlib\n        import shutil\n        for f in [cls.alerts.BROADCASTS_FILE, cls.alerts.POLLS_FILE, cls.alerts.SUBSCRIBERS_FILE]:\n            with contextlib.suppress(OSError):\n                if os.path.exists(f):\n                    os.remove(f)\n        config_dir = os.path.dirname(cls.alerts.BROADCASTS_FILE)\n        with contextlib.suppress(OSError):\n            if os.path.exists(config_dir) and not os.listdir(config_dir):\n                shutil.rmtree(config_dir, ignore_errors=True)\n\n    def test_render_broadcast_confirm_text(self):\n        text_default = self.alerts._render_broadcast_confirm_text(10, pin=False, silent=False)\n        self.assertIn(\"Получателей: <b>10</b>\", text_default)\n        self.assertIn(\"Закрепить у всех: <b>Нет</b>\", text_default)\n        self.assertIn(\"Доставка: <b>со звуком</b>\", text_default)\n        self.assertIn(\"Кнопка: <i>не задана</i>\", text_default)\n\n        text_custom = self.alerts._render_broadcast_confirm_text(\n            5, pin=True, silent=True, btn_title=\"Новости\", btn_url=\"https://t.me/news\"\n        )\n        self.assertIn(\"Закрепить у всех: <b>Да</b>\", text_custom)\n        self.assertIn(\"Доставка: <b>без звука</b>\", text_custom)\n        self.assertIn(\"Новости\", text_custom)\n        self.assertIn(\"https://t.me/news\", text_custom)\n\n    def test_get_broadcast_confirm_keyboard(self):\n        kb_default = self.alerts._get_broadcast_confirm_keyboard(pin=False, silent=False, btn_info=None)\n        button_texts = [btn.text for row in kb_default.inline_keyboard for btn in row]\n        self.assertIn(\"📌 Закрепить: НЕТ\", button_texts)\n        self.assertIn(\"🔔 Со звуком\", button_texts)\n        self.assertIn(\"🔘 Добавить кнопку\", button_texts)\n        self.assertIn(\"✅ Отправить всем\", button_texts)\n\n        kb_active = self.alerts._get_broadcast_confirm_keyboard(pin=True, silent=True, btn_info=\"Ссылка на чат\")\n        btn_active_texts = [btn.text for row in kb_active.inline_keyboard for btn in row]\n        self.assertIn(\"📌 Закрепить: ДА\", btn_active_texts)\n        self.assertIn(\"🔕 Без звука\", btn_active_texts)\n        self.assertTrue(any(\"Ссылка на чат\" in t for t in btn_active_texts))\n\n    async def test_client_settings_keyboard_mute_all_active(self):\n        fake_subscribers = {\n            1001: {\"name\": \"User 1\", \"mute_all\": True, \"muted_nodes\": []}\n        }\n        with patch(\"modules.client_alerts._load_subscribers\", return_value=fake_subscribers), \\\n             patch(\"core.nodes_db.get_all_nodes\", AsyncMock(return_value={\"tok1\": {\"name\": \"Node Alpha\"}})):\n            kb = await self.alerts._get_client_settings_keyboard(1001)\n            btn_texts = [btn.text for row in kb.inline_keyboard for btn in row]\n            callback_datas = [btn.callback_data for row in kb.inline_keyboard for btn in row]\n\n            # Should contain mute_all toggle showing it is ON (muted)\n            self.assertIn(\"cst_toggle_all\", callback_datas)\n            self.assertTrue(any(\"заглушены\" in t or \"Muted\" in t for t in btn_texts))\n            # When mute_all is True, sub-toggles (broadcasts, nodes) should be hidden\n            self.assertNotIn(\"cst_toggle_broadcasts\", callback_datas)\n            self.assertFalse(any(\"Node Alpha\" in t for t in btn_texts))\n\n    async def test_client_settings_keyboard_mute_all_inactive(self):\n        fake_subscribers = {\n            1002: {\"name\": \"User 2\", \"mute_all\": False, \"mute_broadcasts\": False, \"muted_nodes\": [\"tok2\"]}\n        }\n        all_nodes = {\n            \"tok1\": {\"name\": \"Node Alpha\"},\n            \"tok2\": {\"name\": \"Node Beta\"}\n        }\n        with patch(\"modules.client_alerts._load_subscribers\", return_value=fake_subscribers), \\\n             patch(\"core.nodes_db.get_all_nodes\", AsyncMock(return_value=all_nodes)):\n            kb = await self.alerts._get_client_settings_keyboard(1002)\n            btn_texts = [btn.text for row in kb.inline_keyboard for btn in row]\n            callback_datas = [btn.callback_data for row in kb.inline_keyboard for btn in row]\n\n            self.assertIn(\"cst_toggle_all\", callback_datas)\n            self.assertTrue(any(\"включены\" in t or \"Active\" in t for t in btn_texts))\n            # Sub-toggles should be visible\n            self.assertIn(\"cst_toggle_broadcasts\", callback_datas)\n            self.assertIn(\"cst_node_tok1\", callback_datas)\n            self.assertIn(\"cst_node_tok2\", callback_datas)\n\n            # Node Beta should be shown as muted (🔕), Node Alpha as active (🔔)\n            self.assertTrue(any(\"🔕 Node Beta\" in t for t in btn_texts))\n            self.assertTrue(any(\"🔔 Node Alpha\" in t for t in btn_texts))\n\n    def test_is_node_muted_for_user(self):\n        fake_subscribers = {\n            2001: {\"name\": \"All Muted\", \"mute_all\": True, \"muted_nodes\": []},\n            2002: {\"name\": \"Node Muted\", \"mute_all\": False, \"muted_nodes\": [\"tok_down\"]},\n            2003: {\"name\": \"Nothing Muted\", \"mute_all\": False, \"muted_nodes\": []},\n        }\n        with patch(\"modules.client_alerts._load_subscribers\", return_value=fake_subscribers):\n            # User with mute_all=True has all nodes muted\n            self.assertTrue(self.alerts.is_node_muted_for_user(2001, \"tok_down\"))\n            self.assertTrue(self.alerts.is_node_muted_for_user(2001, \"tok_random\"))\n\n            # User with specific node muted\n            self.assertTrue(self.alerts.is_node_muted_for_user(2002, \"tok_down\"))\n            self.assertFalse(self.alerts.is_node_muted_for_user(2002, \"tok_other\"))\n\n            # User with nothing muted\n            self.assertFalse(self.alerts.is_node_muted_for_user(2003, \"tok_down\"))\n\n    async def test_broadcast_system_alert_skips_muted_all(self):\n        fake_subscribers = {\n            3001: {\"name\": \"Normal\", \"mute_all\": False},\n            3002: {\"name\": \"Muted\", \"mute_all\": True},\n        }\n        mock_bot = AsyncMock()\n        mock_bot.send_message.return_value = MagicMock(message_id=999)\n\n        with patch(\"modules.client_alerts._load_subscribers\", return_value=fake_subscribers), \\\n             patch(\"modules.client_alerts.alert_bot\", mock_bot):\n            await self.alerts.broadcast_system_alert(\"Внимание: сервер перезагружается\")\n            # Only user 3001 should receive message\n            self.assertEqual(mock_bot.send_message.call_count, 1)\n            args, _ = mock_bot.send_message.call_args\n            self.assertEqual(args[0], 3001)\n\n    async def test_broadcast_confirm_skips_muted_all_and_muted_broadcasts(self):\n        fake_subscribers = {\n            4001: {\"name\": \"User 1\", \"mute_all\": False, \"mute_broadcasts\": False},\n            4002: {\"name\": \"User 2\", \"mute_all\": True, \"mute_broadcasts\": False},\n            4003: {\"name\": \"User 3\", \"mute_all\": False, \"mute_broadcasts\": True},\n        }\n        mock_callback = AsyncMock()\n        mock_callback.from_user.id = int(os.environ[\"TG_ADMIN_ID\"])\n        mock_callback.message = AsyncMock()\n        mock_state = AsyncMock()\n        mock_state.get_data.return_value = {\n            \"broadcast_payload\": {\"type\": \"text\", \"text\": \"Тестовое объявление\"},\n            \"broadcast_pin\": False,\n            \"broadcast_silent\": False,\n        }\n\n        mock_send = AsyncMock(return_value=MagicMock(message_id=101))\n\n        with patch(\"modules.client_alerts._load_subscribers\", return_value=fake_subscribers), \\\n             patch(\"modules.client_alerts._send_payload_via_alert_bot\", mock_send), \\\n             patch(\"modules.client_alerts.alert_bot\", AsyncMock()):\n            await self.alerts._broadcast_confirm(mock_callback, mock_state)\n            # Only user 4001 should receive the broadcast (4002 has mute_all, 4003 has mute_broadcasts)\n            self.assertEqual(mock_send.call_count, 1)\n            args, _ = mock_send.call_args\n            self.assertEqual(args[0], 4001)\n\n    @contextmanager\n    def subscriber_settings(self, user_id=5001, **settings):\n        subscribers = {user_id: {\"name\": \"User\", **settings}}\n        saved = {}\n\n        def save(data):\n            saved.clear()\n            saved.update(data)\n\n        callback = AsyncMock()\n        callback.from_user.id = user_id\n        callback.message = AsyncMock()\n        with (\n            patch(\"modules.client_alerts._load_subscribers\", return_value=subscribers),\n            patch(\"modules.client_alerts._save_subscribers\", side_effect=save),\n            patch(\"modules.client_alerts._get_client_settings_keyboard\", AsyncMock(return_value=MagicMock())),\n        ):\n            yield saved, callback\n\n    async def test_toggle_all_shows_warning_dialog(self):\n        with self.subscriber_settings(mute_all=False) as (saved, mock_callback):\n            await self.alerts._cq_client_settings_toggle_all(mock_callback)\n            # Should NOT mutate mute_all yet\n            self.assertFalse(saved.get(5001, {}).get(\"mute_all\", False))\n            # Should edit message to display warning with OK and Cancel buttons\n            mock_callback.message.edit_text.assert_called_once()\n            args, kwargs = mock_callback.message.edit_text.call_args\n            self.assertIn(\"тишины\", args[0])\n            buttons = [b.callback_data for row in kwargs[\"reply_markup\"].inline_keyboard for b in row]\n            self.assertIn(\"cst_confirm_mute_all\", buttons)\n            self.assertIn(\"cst_cancel_mute_all\", buttons)\n            mock_callback.answer.assert_called_once()\n\n    async def test_confirm_mute_all_callback(self):\n        with self.subscriber_settings(mute_all=False) as (saved, mock_callback):\n            await self.alerts._cq_client_confirm_mute_all(mock_callback)\n            # Should set mute_all to True\n            self.assertTrue(saved[5001][\"mute_all\"])\n            mock_callback.message.edit_text.assert_called_once()\n            mock_callback.answer.assert_called_once()\n\n    async def test_cancel_mute_all_callback(self):\n        with self.subscriber_settings(mute_all=False) as (saved, mock_callback):\n            await self.alerts._cq_client_cancel_mute_all(mock_callback)\n            # Should NOT save mute_all as True\n            self.assertFalse(saved.get(5001, {}).get(\"mute_all\", False))\n            mock_callback.message.edit_text.assert_called_once()\n            mock_callback.answer.assert_called_once()\n\n    async def test_toggle_all_unmutes_directly_when_already_muted(self):\n        with self.subscriber_settings(mute_all=True) as (saved, mock_callback):\n            await self.alerts._cq_client_settings_toggle_all(mock_callback)\n            # Should toggle back to False directly without warning\n            self.assertFalse(saved[5001][\"mute_all\"])\n            mock_callback.message.edit_reply_markup.assert_called_once()\n            mock_callback.answer.assert_called_once()\n\n    async def test_client_alerts_uses_main_bot_language(self):\n        fake_subscribers = {7001: {\"name\": \"User\", \"mute_all\": False}}\n        with patch(\"modules.client_alerts.get_user_lang\", return_value=\"en\"), \\\n             patch(\"modules.client_alerts._load_subscribers\", return_value=fake_subscribers), \\\n             patch(\"core.nodes_db.get_all_nodes\", AsyncMock(return_value={})):\n            kb = await self.alerts._get_client_settings_keyboard(7001)\n            btn_texts = [btn.text for row in kb.inline_keyboard for btn in row]\n            self.assertTrue(any(\"All messages: Active\" in t for t in btn_texts))\n\n            main_kb = self.alerts._get_client_main_keyboard()\n            # In English, settings button is Settings\n            main_btn = main_kb.keyboard[0][0].text\n            self.assertIn(\"Settings\", main_btn)\n\n    async def test_toggle_broadcasts_callback(self):\n        with self.subscriber_settings(user_id=6001, mute_broadcasts=False) as (saved, mock_callback):\n            await self.alerts._cq_client_settings_toggle_broadcasts(mock_callback)\n            self.assertTrue(saved[6001][\"mute_broadcasts\"])\n            mock_callback.answer.assert_called_once()\n\n    async def test_send_payload_caching(self):\n        mock_bot = AsyncMock()\n        sent_message = MagicMock()\n        sent_photo = MagicMock()\n        sent_photo.file_id = \"alert_bot_cached_file_id\"\n        sent_message.photo = [sent_photo]\n        mock_bot.send_photo.return_value = sent_message\n\n        payload = {\n            \"type\": \"photo\",\n            \"media_bytes\": b\"fake_image_bytes\",\n            \"filename\": \"test.jpg\",\n            \"file_id\": \"original_main_file_id\",\n            \"caption\": \"Test Photo\"\n        }\n\n        with patch(\"modules.client_alerts.alert_bot\", mock_bot):\n            # First send: sends media bytes and caches file_id\n            await self.alerts._send_payload_via_alert_bot(12345, payload)\n            self.assertEqual(payload.get(\"cached_file_id\"), \"alert_bot_cached_file_id\")\n\n            # Second send: should use cached_file_id directly\n            await self.alerts._send_payload_via_alert_bot(67890, payload)\n            call_args = mock_bot.send_photo.call_args_list\n            self.assertEqual(len(call_args), 2)\n            self.assertEqual(call_args[1].args[1], \"alert_bot_cached_file_id\")\n\n    async def test_broadcast_deletion(self):\n        history_store = []\n\n        def save_h(h):\n            history_store.clear()\n            history_store.extend(h)\n\n        mock_bot = AsyncMock()\n        mock_bot.unpin_chat_message.return_value = True\n        mock_bot.unpin_all_chat_messages.return_value = True\n        mock_bot.delete_message.return_value = True\n\n        with patch(\"modules.client_alerts.alert_bot\", mock_bot), \\\n             patch(\"modules.client_alerts._load_broadcast_history\", side_effect=lambda: list(history_store)), \\\n             patch(\"modules.client_alerts._save_broadcast_history\", side_effect=save_h):\n            bc_id = self.alerts._record_broadcast(\"Проверочная рассылка\", {111: 501, 222: 502}, is_pinned=True)\n            self.assertTrue(bc_id.startswith(\"bc_\"))\n\n            del_ok, del_fail = await self.alerts._delete_broadcast_for_all(bc_id)\n            self.assertEqual(del_ok, 2)\n            self.assertEqual(del_fail, 0)\n            self.assertEqual(mock_bot.unpin_chat_message.call_count, 2)\n            self.assertEqual(mock_bot.unpin_all_chat_messages.call_count, 2)\n            # 2 messages + 2 service messages (mid+1) = 4 delete calls\n            self.assertEqual(mock_bot.delete_message.call_count, 4)\n\n    async def test_broadcast_deletion_unpinned(self):\n        history_store = []\n\n        def save_h(h):\n            history_store.clear()\n            history_store.extend(h)\n\n        mock_bot = AsyncMock()\n        mock_bot.delete_message.return_value = True\n\n        with patch(\"modules.client_alerts.alert_bot\", mock_bot), \\\n             patch(\"modules.client_alerts._load_broadcast_history\", side_effect=lambda: list(history_store)), \\\n             patch(\"modules.client_alerts._save_broadcast_history\", side_effect=save_h):\n            bc_id = self.alerts._record_broadcast(\"Обычная рассылка\", {111: 601, 222: 602}, is_pinned=False)\n\n            del_ok, del_fail = await self.alerts._delete_broadcast_for_all(bc_id)\n            self.assertEqual(del_ok, 2)\n            self.assertEqual(del_fail, 0)\n            # When unpinned, NO unpin calls and only 2 delete calls (no mid+1 bubble calls)\n            mock_bot.unpin_chat_message.assert_not_called()\n            mock_bot.unpin_all_chat_messages.assert_not_called()\n            self.assertEqual(mock_bot.delete_message.call_count, 2)\n\n    async def test_pinned_service_message_ignored(self):\n        mock_msg = MagicMock()\n        mock_msg.pinned_message = MagicMock()\n        mock_msg.answer = AsyncMock()\n        mock_msg.delete = AsyncMock()\n\n        with patch(\"modules.client_alerts.alert_bot\", MagicMock()):\n            await self.alerts.alert_message_handler(mock_msg)\n            mock_msg.answer.assert_not_called()\n            mock_msg.delete.assert_called_once()\n\n    async def test_broadcast_unsupported_type_rejected(self):\n        mock_msg = MagicMock()\n        mock_msg.text = None\n        mock_msg.caption = None\n        mock_msg.photo = None\n        mock_msg.video = None\n        mock_msg.audio = None\n        mock_msg.document = None\n        mock_msg.voice = None\n        mock_msg.video_note = None\n        mock_msg.sticker = None\n        mock_msg.animation = None\n        mock_msg.poll = None\n        mock_msg.location = None\n        mock_msg.venue = None\n        mock_msg.contact = None\n        mock_msg.dice = None\n        mock_msg.html_text = None\n        mock_msg.caption_entities = None\n        mock_msg.answer = AsyncMock()\n        mock_state = AsyncMock()\n\n        await self.alerts._broadcast_message_received(mock_msg, mock_state)\n        # Should NOT save to state\n        mock_state.update_data.assert_not_called()\n        # Should reply with unsupported type error\n        mock_msg.answer.assert_called_once()\n        args, _ = mock_msg.answer.call_args\n        self.assertIn(\"не поддерживается\", args[0])\n\n    async def test_send_poll_payload(self):\n        mock_bot = AsyncMock()\n        mock_bot.send_poll.return_value = MagicMock(message_id=777)\n        poll_payload = {\n            \"type\": \"poll\",\n            \"question\": \"Все работает?\",\n            \"options\": [\"Да\", \"Нет\"],\n            \"is_anonymous\": True,\n        }\n        with patch(\"modules.client_alerts.alert_bot\", mock_bot):\n            res = await self.alerts._send_payload_via_alert_bot(12345, poll_payload)\n            self.assertEqual(res.message_id, 777)\n            mock_bot.send_poll.assert_called_once()\n\n    async def test_reaction_handler_new_and_removed(self):\n        mock_main_bot = AsyncMock()\n        mock_main_module = MagicMock(bot=mock_main_bot)\n\n        mock_user = MagicMock(id=555123, full_name=\"Alice User\", username=\"alice\", is_bot=False)\n        mock_emoji_type = MagicMock(emoji=\"🔥\", custom_emoji_id=None)\n        mock_event_new = MagicMock(\n            user=mock_user,\n            message_id=9876,\n            new_reaction=[mock_emoji_type],\n            old_reaction=[],\n        )\n\n        with patch.dict(sys.modules, {\"bot\": mock_main_module}):\n            await self.alerts.alert_reaction_handler(mock_event_new)\n            mock_main_bot.send_message.assert_called_once()\n            call_args = mock_main_bot.send_message.call_args[0]\n            self.assertEqual(call_args[0], self.config.ADMIN_USER_ID)\n            self.assertIn(\"Реакция на сообщение\", call_args[1])\n            self.assertIn(\"🔥\", call_args[1])\n            self.assertIn(\"Alice User\", call_args[1])\n\n        mock_main_bot.reset_mock()\n        mock_event_removed = MagicMock(\n            user=mock_user,\n            message_id=9876,\n            new_reaction=[],\n            old_reaction=[mock_emoji_type],\n        )\n\n        with patch.dict(sys.modules, {\"bot\": mock_main_module}):\n            await self.alerts.alert_reaction_handler(mock_event_removed)\n            mock_main_bot.send_message.assert_called_once()\n            call_args = mock_main_bot.send_message.call_args[0]\n            self.assertIn(\"Реакция снята\", call_args[1])\n            self.assertIn(\"🔥\", call_args[1])\n\n    async def test_poll_answer_handler_and_aggregated_results(self):\n        bc_id = \"bc_test_poll\"\n        self.alerts._save_broadcast_history([{\n            \"id\": bc_id,\n            \"timestamp\": 1234567.0,\n            \"date_str\": \"26.10 21:00\",\n            \"preview\": \"Опрос: Довольны ли вы скоростью?\",\n            \"sent\": {\"444111\": 7001},\n            \"is_pinned\": False,\n            \"reactions\": {},\n            \"poll\": {\n                \"question\": \"Довольны ли вы скоростью?\",\n                \"options\": [\"Да\", \"Нет\", \"Частично\"],\n                \"votes\": {},\n            }\n        }])\n        self.alerts._save_polls_registry({\n            \"poll_id_999\": {\n                \"bc_id\": bc_id,\n                \"user_id\": 444111,\n                \"message_id\": 7001,\n                \"question\": \"Довольны ли вы скоростью?\",\n                \"options\": [\"Да\", \"Нет\", \"Частично\"]\n            }\n        })\n\n        mock_main_bot = AsyncMock()\n        mock_main_module = MagicMock(bot=mock_main_bot)\n        mock_user = MagicMock(id=444111, full_name=\"Bob Voter\", username=\"bob\", is_bot=False)\n\n        # 1. Client votes for \"Да\" (index 0)\n        mock_answer_vote = MagicMock(\n            poll_id=\"poll_id_999\",\n            user=mock_user,\n            option_ids=[0]\n        )\n\n        with patch.dict(sys.modules, {\"bot\": mock_main_module}):\n            await self.alerts.alert_poll_answer_handler(mock_answer_vote)\n            mock_main_bot.send_message.assert_called_once()\n            call_args = mock_main_bot.send_message.call_args[0]\n            self.assertIn(\"Ответ в опросе\", call_args[1])\n            self.assertIn(\"Да\", call_args[1])\n            self.assertIn(\"Bob Voter\", call_args[1])\n\n        history = self.alerts._load_broadcast_history()\n        bc = next(b for b in history if b[\"id\"] == bc_id)\n        self.assertEqual(bc[\"poll\"][\"votes\"].get(\"444111\"), [0])\n\n        # 2. Check _cq_view_broadcast displays aggregated stats\n        mock_cq = AsyncMock()\n        mock_cq.from_user.id = self.config.ADMIN_USER_ID\n        mock_cq.data = f\"alert_view_bc_{bc_id}\"\n        mock_cq.message.edit_text = AsyncMock()\n\n        await self.alerts._cq_view_broadcast(mock_cq)\n        mock_cq.message.edit_text.assert_called_once()\n        text_shown = mock_cq.message.edit_text.call_args[0][0]\n        self.assertIn(\"Результаты опроса:\", text_shown)\n        self.assertIn(\"Да: <b>1</b> (100.0%)\", text_shown)\n        self.assertIn(\"Всего проголосовало: <b>1</b>\", text_shown)\n\n        # 3. Client retracts vote\n        mock_main_bot.reset_mock()\n        mock_answer_retract = MagicMock(\n            poll_id=\"poll_id_999\",\n            user=mock_user,\n            option_ids=[]\n        )\n\n        with patch.dict(sys.modules, {\"bot\": mock_main_module}):\n            await self.alerts.alert_poll_answer_handler(mock_answer_retract)\n            mock_main_bot.send_message.assert_called_once()\n            call_args = mock_main_bot.send_message.call_args[0]\n            self.assertIn(\"Отзыв голоса в опросе\", call_args[1])\n\n        history = self.alerts._load_broadcast_history()\n        bc = next(b for b in history if b[\"id\"] == bc_id)\n        self.assertNotIn(\"444111\", bc[\"poll\"][\"votes\"])\n\n    def test_alert_panel_keyboard_localization(self):\n        \"\"\"Test Alert Module control panel keyboards in ru and en.\"\"\"\n        kb_ru = self.alerts._get_alert_panel_keyboard(\"ru\")\n        ru_texts = [btn.text for row in kb_ru.inline_keyboard for btn in row]\n        self.assertIn(\"📣 Рассылка\", ru_texts)\n        self.assertIn(\"🔙 Назад в меню\", ru_texts)\n\n        kb_en = self.alerts._get_alert_panel_keyboard(\"en\")\n        en_texts = [btn.text for row in kb_en.inline_keyboard for btn in row]\n        self.assertIn(\"📣 Broadcast\", en_texts)\n        self.assertIn(\"🔙 Back to menu\", en_texts)\n\n    async def test_client_bot_settings_language_toggle(self):\n        \"\"\"Test subscriber language toggle in Alert Bot.\"\"\"\n        fake_subscribers = {\n            777: {\"name\": \"Test User\", \"mute_all\": False, \"mute_broadcasts\": False, \"muted_nodes\": [], \"lang\": \"ru\"}\n        }\n        with patch(\"modules.client_alerts._load_subscribers\", return_value=fake_subscribers), \\\n             patch(\"core.nodes_db.get_all_nodes\", AsyncMock(return_value={})):\n            kb = await self.alerts._get_client_settings_keyboard(777)\n            texts = [btn.text for row in kb.inline_keyboard for btn in row]\n            self.assertIn(\"🌐 Язык: 🇷🇺 русский\", texts)\n\n        fake_subscribers_en = {\n            777: {\"name\": \"Test User\", \"mute_all\": False, \"mute_broadcasts\": False, \"muted_nodes\": [], \"lang\": \"en\"}\n        }\n        with patch(\"modules.client_alerts._load_subscribers\", return_value=fake_subscribers_en), \\\n             patch(\"core.nodes_db.get_all_nodes\", AsyncMock(return_value={})):\n            kb_en = await self.alerts._get_client_settings_keyboard(777)\n            texts_en = [btn.text for row in kb_en.inline_keyboard for btn in row]\n            self.assertIn(\"🌐 Language: 🇬🇧 English\", texts_en)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_codacy_core.py": "import os\nimport socket\nimport unittest\nfrom types import SimpleNamespace\nfrom unittest.mock import AsyncMock, patch\n\nimport manage\nfrom core.web.avatar import get_avatar_html\nfrom network_validation import (\n    is_valid_iperf_server,\n    is_valid_network_host,\n    parse_public_ip,\n    resolve_public_host,\n)\n\n\nclass CodacyCoreRegressionTests(unittest.IsolatedAsyncioTestCase):\n    def test_compose_profile_is_limited_to_configured_profiles(self):\n        with patch.dict(os.environ, {\"COMPOSE_PROFILES\": \"secure\"}, clear=False):\n            self.assertEqual(manage._docker_compose_profile(), \"secure\")\n\n        with patch.dict(os.environ, {\"COMPOSE_PROFILES\": \"--help\"}, clear=False):\n            with self.assertRaises(ValueError):\n                manage._docker_compose_profile()\n\n    def test_avatar_html_escapes_user_controlled_values(self):\n        avatar = get_avatar_html({\"photo_url\": '\"><script>alert(1)</script>'})\n        self.assertNotIn(\"<script>\", avatar)\n        self.assertIn(\"&lt;script&gt;\", avatar)\n\n    def test_avatar_images_require_https(self):\n        avatar = get_avatar_html({\"photo_url\": \"http://images.example/avatar.png\"})\n        self.assertNotIn(\"<img\", avatar)\n        self.assertIn(\"http://images.example/avatar.png\", avatar)\n\n    def test_server_list_hosts_are_validated_before_ping(self):\n        self.assertTrue(\n            is_valid_iperf_server(\n                {\"IP/HOST\": \"iperf.example.net\", \"PORT\": \"5201\"}\n            )\n        )\n        self.assertFalse(\n            is_valid_iperf_server(\n                {\"IP/HOST\": \"--help\", \"PORT\": \"5201\"}\n            )\n        )\n        self.assertFalse(is_valid_network_host(\"https://example.net\"))\n        self.assertFalse(is_valid_network_host(\"127.0.0.1\"))\n        self.assertEqual(resolve_public_host(\"8.8.8.8\"), \"8.8.8.8\")\n        with patch(\n            \"network_validation.socket.getaddrinfo\",\n            return_value=[(socket.AF_INET, socket.SOCK_STREAM, 6, \"\", (\"127.0.0.1\", 0))],\n        ):\n            self.assertIsNone(resolve_public_host(\"iperf.example.net\"))\n\n    def test_public_ip_parser_rejects_non_public_or_malformed_values(self):\n        self.assertEqual(str(parse_public_ip(\"8.8.8.8\")), \"8.8.8.8\")\n        self.assertIsNone(parse_public_ip(\"127.0.0.1\"))\n        self.assertIsNone(parse_public_ip(\"https://example.net\"))\n\n    async def test_docker_compose_command_prefers_docker_and_uses_static_strings(self):\n        process = SimpleNamespace(wait=AsyncMock(return_value=0), returncode=0, kill=lambda: None)\n        spawn = AsyncMock(return_value=process)\n\n        def mock_which_docker(binary, **kw):\n            return f\"/usr/bin/{binary}\" if binary == \"docker\" else None\n\n        with (\n            patch(\"manage.shutil.which\", side_effect=mock_which_docker),\n            patch(\"manage.asyncio.create_subprocess_exec\", spawn),\n        ):\n            cmd = await manage._docker_compose_command()\n            self.assertEqual(cmd, [\"/usr/bin/docker\", \"compose\"])\n            self.assertEqual(spawn.call_args.args, (\"docker\", \"compose\", \"version\"))\n\n    async def test_docker_compose_command_falls_back_to_docker_compose(self):\n        process = SimpleNamespace(wait=AsyncMock(return_value=0), returncode=0, kill=lambda: None)\n        spawn = AsyncMock(return_value=process)\n\n        def mock_which_compose(binary, **kw):\n            return f\"/usr/local/bin/{binary}\" if binary == \"docker-compose\" else None\n\n        with (\n            patch(\"manage.shutil.which\", side_effect=mock_which_compose),\n            patch(\"manage.asyncio.create_subprocess_exec\", spawn),\n        ):\n            cmd = await manage._docker_compose_command()\n            self.assertEqual(cmd, [\"/usr/local/bin/docker-compose\"])\n            self.assertEqual(spawn.call_args.args, (\"docker-compose\", \"version\"))\n\n    async def test_docker_compose_command_raises_when_neither_available(self):\n        with patch(\"manage.shutil.which\", return_value=None):\n            with self.assertRaises(RuntimeError):\n                await manage._docker_compose_command()\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_codacy_modules.py": "import ast\nimport asyncio\nimport importlib.util\nimport json\nimport re\nimport sys\nimport unittest\nfrom datetime import datetime, timedelta, timezone\nfrom pathlib import Path\nfrom types import SimpleNamespace\nfrom unittest.mock import AsyncMock, MagicMock, Mock, mock_open, patch\n\n\nROOT = Path(__file__).resolve().parents[1]\n\n\ndef load_functions(filename, names, **dependencies):\n    \"\"\"Load backend functions without requiring the optional Telegram runtime.\"\"\"\n    imports = {\n        name: MagicMock()\n        for name in (\n            \"aiohttp\", \"yaml\", \"psutil\", \"aiogram\", \"aiogram.types\",\n            \"aiogram.exceptions\", \"core\", \"core.auth\", \"core.config\",\n            \"core.i18n\", \"core.keyboards\", \"core.messaging\", \"core.rbac\",\n            \"core.shared_state\", \"core.utils\", \"core.network_addresses\",\n        )\n    }\n    imports[\"core\"].config.CONFIG_DIR = \"config\"\n    spec = importlib.util.spec_from_file_location(\n        f\"codacy_modules_{Path(filename).stem}\", ROOT / \"modules\" / filename,\n    )\n    if spec is None or spec.loader is None:\n        raise ImportError(f\"Unable to load module {filename}\")\n    subject = importlib.util.module_from_spec(spec)\n    with patch.dict(sys.modules, imports):\n        spec.loader.exec_module(subject)\n    for name, value in dependencies.items():\n        setattr(subject, name, value)\n    for name in names:\n        if not callable(getattr(subject, name)):\n            raise TypeError(f\"Expected a function: {name}\")\n    return subject\n\n\nclass ModuleFallbackTests(unittest.TestCase):\n    def test_speedtest_loads_without_node_installation(self):\n        with patch.dict(sys.modules, {\"node\": None, \"node.input_validation\": None}):\n            subject = load_functions(\n                \"speedtest.py\", [\"speedtest_handler\", \"get_speedtest_mode\"],\n            )\n        self.assertEqual(subject.resolve_public_host(\"8.8.8.8\"), \"8.8.8.8\")\n        self.assertIsNone(subject.resolve_public_host(\"127.0.0.1\"))\n\n    def test_changed_modules_have_no_silent_broad_exception_handlers(self):\n        filenames = (\n            \"backups.py\", \"client_alerts.py\", \"nodes.py\", \"notifications.py\",\n            \"optimize.py\", \"selftest.py\", \"services.py\", \"speedtest.py\", \"traffic.py\",\n        )\n        for filename in filenames:\n            source = ast.parse((ROOT / \"modules\" / filename).read_text(encoding=\"utf-8\"))\n            for node in ast.walk(source):\n                if not isinstance(node, ast.ExceptHandler):\n                    continue\n                if not isinstance(node.type, ast.Name) or node.type.id != \"Exception\":\n                    continue\n                with self.subTest(filename=filename, line=node.lineno):\n                    self.assertFalse(\n                        len(node.body) == 1 and isinstance(node.body[0], (ast.Pass, ast.Continue)),\n                    )\n\n    def test_speedtest_detection_survives_unreadable_config_and_missing_binary(self):\n        for installed, expected in ((\"iperf3\", \"IPERF3\"), (None, \"AUTO\")):\n            with self.subTest(installed=installed):\n                runner = Mock(side_effect=FileNotFoundError(\"speedtest\"))\n                subject = load_functions(\n                    \"speedtest.py\", [\"get_speedtest_mode\"],\n                    _SPEEDTEST_MODE_CACHE=None,\n                    SPEEDTEST_MODE_FILE=\"mode\",\n                    os=SimpleNamespace(path=SimpleNamespace(exists=lambda path: True)),\n                    shutil=SimpleNamespace(which=lambda name: installed),\n                )\n                with (\n                    patch.object(subject.subprocess, \"run\", runner),\n                    patch(\"builtins.open\", side_effect=PermissionError(\"mode\")),\n                    self.assertLogs(level=\"DEBUG\"),\n                ):\n                    self.assertEqual(subject.get_speedtest_mode(), expected)\n                runner.assert_called_once_with(\n                    [\"speedtest\", \"--version\"], capture_output=True, timeout=5,\n                )\n\n    def test_speedtest_config_keeps_priority_over_binary_detection(self):\n        runner = Mock()\n        subject = load_functions(\n            \"speedtest.py\", [\"get_speedtest_mode\"],\n            _SPEEDTEST_MODE_CACHE=None,\n            SPEEDTEST_MODE_FILE=\"mode\",\n            os=SimpleNamespace(path=SimpleNamespace(exists=lambda path: True)),\n        )\n        with (\n            patch.object(subject.subprocess, \"run\", runner),\n            patch(\"builtins.open\", mock_open(read_data=\"ru\\n\")),\n        ):\n            self.assertEqual(subject.get_speedtest_mode(), \"IPERF3\")\n        runner.assert_not_called()\n\n    def test_services_pass_validated_names_as_single_arguments(self):\n        runner = Mock(return_value=SimpleNamespace(\n            returncode=0, stdout=\"LoadState=loaded\\nActiveState=active\\nSubState=running\\n\",\n            stderr=\"\",\n        ))\n        subject = load_functions(\n            \"services.py\", [\"_validate_name\", \"get_systemd_status\"],\n            _VALID_NAME_RE=re.compile(r\"^[a-zA-Z0-9._@/:-]+$\"),\n        )\n        with patch.object(subject.subprocess, \"run\", runner):\n            self.assertEqual(subject.get_systemd_status(\"nginx.service\"), \"running\")\n            self.assertEqual(runner.call_args.args[0][-2:], [\"--\", \"nginx.service\"])\n            self.assertNotIn(\"shell\", runner.call_args.kwargs)\n            runner.reset_mock()\n            with self.assertLogs(level=\"ERROR\"):\n                self.assertEqual(subject.get_systemd_status(\"nginx; touch marker\"), \"error\")\n            runner.assert_not_called()\n\n\nclass ModuleAsyncTests(unittest.IsolatedAsyncioTestCase):\n    async def test_journal_session_login_produces_alert(self):\n        class LoginStream:\n            def __aiter__(self):\n                return self\n\n            async def __anext__(self):\n                if getattr(self, \"sent\", False):\n                    raise StopAsyncIteration\n                self.sent = True\n                return b\"Accepted publickey for root from 192.0.2.1 port 1234 ssh2\\n\"\n\n        process = SimpleNamespace(\n            stdout=LoginStream(), stderr=SimpleNamespace(read=AsyncMock(return_value=b\"\")),\n            wait=AsyncMock(return_value=0),\n        )\n        alert = AsyncMock()\n        subject = load_functions(\n            \"notifications.py\", [\"reliable_journal_monitor\", \"parse_ssh_log_line\"],\n            get_ip_data=AsyncMock(return_value=(\"\", None)),\n            get_server_timezone_label=lambda: \"UTC\",\n            escape_html=lambda value: value,\n            RECENT_NOTIFIED_LOGINS={},\n            send_alert=alert,\n            _=lambda key, lang, **params: f\"{key}: {params}\",\n        )\n        with (\n            patch.object(subject.asyncio, \"create_subprocess_exec\", AsyncMock(return_value=process)),\n            patch.object(subject.asyncio, \"sleep\", AsyncMock(side_effect=asyncio.CancelledError)),\n        ):\n            with self.assertRaises(asyncio.CancelledError):\n                await subject.reliable_journal_monitor(None, \"logins\", subject.parse_ssh_log_line)\n        alert.assert_awaited_once()\n        self.assertEqual(alert.call_args.args[2], \"logins\")\n        self.assertIn(\"alert_ssh_login_detected\", alert.call_args.args[1](\"en\"))\n\n    async def test_ssh_report_reads_session_events_and_reports_read_errors(self):\n        for returncode in (0, 2):\n            with self.subTest(returncode=returncode):\n                process = SimpleNamespace(\n                    returncode=returncode,\n                    communicate=AsyncMock(return_value=(\n                        b\"2026-10-25T02:00:00+03:00 host sshd-session[123]: Accepted publickey for root from 192.0.2.1 port 1234 ssh2\\n\",\n                        b\"Permission denied\" if returncode else b\"\",\n                    )),\n                )\n                spawn = AsyncMock(return_value=process)\n                message = SimpleNamespace(\n                    from_user=SimpleNamespace(id=1), chat=SimpleNamespace(id=2),\n                    answer=AsyncMock(return_value=SimpleNamespace(message_id=3)),\n                    bot=SimpleNamespace(edit_message_text=AsyncMock()),\n                )\n                subject = load_functions(\n                    \"sshlog.py\", [\"sshlog_handler\"],\n                    get_user_lang=lambda uid: \"en\", is_allowed=lambda *args: True,\n                    delete_previous_message=AsyncMock(), LAST_MESSAGE_IDS={},\n                    get_host_path=lambda path: path,\n                    os=SimpleNamespace(path=SimpleNamespace(\n                        exists=lambda path: path.endswith(\"auth.log\"), basename=lambda path: \"auth.log\",\n                    )),\n                    get_country_flag=AsyncMock(return_value=\"\"),\n                    get_server_timezone_label=lambda: \"UTC\",\n                    escape_html=lambda value: value,\n                    _=lambda key, lang, **params: f\"{key}: {params}\",\n                )\n                with patch.object(subject.asyncio, \"create_subprocess_exec\", spawn):\n                    if returncode:\n                        with self.assertLogs(level=\"ERROR\"):\n                            await subject.sshlog_handler(message)\n                    else:\n                        await subject.sshlog_handler(message)\n                text = message.bot.edit_message_text.call_args.args[0]\n                self.assertIn(\"sshlog_read_error\" if returncode else \"sshlog_entry_success\", text)\n                self.assertEqual(spawn.call_args.args[0], \"grep\")\n\n    async def test_fail2ban_read_error_is_not_reported_as_no_bans(self):\n        process = SimpleNamespace(\n            returncode=2,\n            communicate=AsyncMock(return_value=(b\"\", b\"Permission denied\")),\n        )\n        message = SimpleNamespace(\n            from_user=SimpleNamespace(id=1), chat=SimpleNamespace(id=2),\n            answer=AsyncMock(), bot=object(),\n        )\n        subject = load_functions(\n            \"fail2ban.py\", [\"fail2ban_handler\"],\n            get_user_lang=lambda uid: \"en\", is_allowed=lambda *args: True,\n            delete_previous_message=AsyncMock(),\n            get_host_path=lambda path: path,\n            os=SimpleNamespace(path=SimpleNamespace(exists=lambda path: True)),\n            _=lambda key, lang, **params: f\"{key}: {params}\",\n        )\n        with (\n            patch.object(subject.asyncio, \"create_subprocess_exec\", AsyncMock(return_value=process)),\n            self.assertLogs(level=\"ERROR\"),\n        ):\n            await subject.fail2ban_handler(message)\n        self.assertIn(\"f2b_read_error_generic\", message.answer.call_args.args[0])\n\n    async def test_agent_handler_starts_selected_speedtest_without_node_installation(self):\n        for mode in (\"OOKLA\", \"IPERF3\"):\n            with self.subTest(mode=mode), patch.dict(\n                sys.modules, {\"node\": None, \"node.input_validation\": None},\n            ):\n                ookla = AsyncMock(return_value=\"Speedtest results\")\n                iperf = AsyncMock()\n                message = SimpleNamespace(\n                    from_user=SimpleNamespace(id=1),\n                    chat=SimpleNamespace(id=2),\n                    bot=SimpleNamespace(edit_message_text=AsyncMock()),\n                    answer=AsyncMock(return_value=SimpleNamespace(message_id=3)),\n                )\n                subject = load_functions(\n                    \"speedtest.py\", [\"speedtest_handler\"],\n                    get_user_lang=lambda user_id: \"en\",\n                    is_allowed=lambda *args: True,\n                    delete_previous_message=AsyncMock(),\n                    get_speedtest_mode=lambda: mode,\n                    run_ookla_speedtest=ookla,\n                    speedtest_iperf3_handler=iperf,\n                    LAST_MESSAGE_IDS={},\n                    _=lambda key, lang: key,\n                )\n                await subject.speedtest_handler(message)\n                if mode == \"OOKLA\":\n                    ookla.assert_awaited_once_with(message.bot, 2, 3, \"en\")\n                    iperf.assert_not_awaited()\n                    message.bot.edit_message_text.assert_awaited_once_with(\n                        \"Speedtest results\", chat_id=2, message_id=3,\n                        parse_mode=\"HTML\", disable_web_page_preview=True,\n                    )\n                else:\n                    iperf.assert_awaited_once_with(message)\n                    ookla.assert_not_awaited()\n\n    async def test_ping_uses_only_pinned_public_targets(self):\n        for resolved in (None, \"8.8.8.8\"):\n            with self.subTest(resolved=resolved):\n                proc = SimpleNamespace(communicate=AsyncMock(return_value=(\n                    b\"rtt min/avg/max/mdev = 1.0/2.0/3.0/0.0 ms\", b\"\",\n                )))\n                spawn = AsyncMock(return_value=proc)\n                resolver = Mock(return_value=resolved)\n                subject = load_functions(\n                    \"speedtest.py\", [\"get_ping_async\"],\n                    asyncio=SimpleNamespace(\n                        create_subprocess_exec=spawn, to_thread=asyncio.to_thread,\n                        subprocess=asyncio.subprocess,\n                    ),\n                    resolve_public_host=resolver,\n                    platform=SimpleNamespace(system=lambda: \"Linux\"),\n                    PING_COUNT=3, PING_TIMEOUT_SEC=2, re=re,\n                )\n                result = await subject.get_ping_async(\"-malicious-host\")\n                resolver.assert_called_once_with(\"-malicious-host\")\n                if resolved is None:\n                    self.assertIsNone(result)\n                    spawn.assert_not_awaited()\n                else:\n                    self.assertEqual(result, 2.0)\n                    self.assertEqual(spawn.call_args.args[-1], \"8.8.8.8\")\n\n    async def test_iperf_rejects_invalid_or_private_feed_targets(self):\n        for valid, resolved in ((False, None), (True, None)):\n            with self.subTest(valid=valid):\n                spawn = AsyncMock()\n                subject = load_functions(\n                    \"speedtest.py\", [\"run_iperf_test_async\"],\n                    Bot=object,\n                    asyncio=SimpleNamespace(\n                        create_subprocess_exec=spawn, to_thread=asyncio.to_thread,\n                    ),\n                    is_valid_iperf_server=lambda server: valid,\n                    resolve_public_host=lambda host: resolved,\n                )\n                result = await subject.run_iperf_test_async(\n                    None, 1, 1, {\"host\": \"127.0.0.1\", \"port\": 5201}, 1.0, \"en\",\n                )\n                self.assertIn(\"server\", result)\n                spawn.assert_not_awaited()\n\n    async def test_ssh_log_path_is_a_single_argument_and_invalid_offset_is_logged(self):\n        log_path = \"/host/log path/auth.log; touch marker\"\n        proc = SimpleNamespace(\n            communicate=AsyncMock(return_value=(b\"Accepted password for root from 192.0.2.1\\n\", b\"\")),\n        )\n        spawn = AsyncMock(return_value=proc)\n        subject = load_functions(\n            \"selftest.py\", [\"get_last_ssh_login\"],\n            asyncio=SimpleNamespace(\n                create_subprocess_exec=spawn, subprocess=asyncio.subprocess,\n            ),\n            os=SimpleNamespace(\n                path=SimpleNamespace(exists=lambda path: True, basename=lambda path: \"auth.log\"),\n            ),\n            get_host_path=lambda path: log_path,\n            get_ip_data_full=AsyncMock(return_value=(\"flag\", \"invalid\")),\n            escape_html=lambda value: value,\n            get_server_timezone_label=lambda: \"UTC\",\n            datetime=datetime, timedelta=timedelta, timezone=timezone, re=re,\n            _=lambda key, lang, **values: values,\n        )\n        with self.assertLogs(level=\"DEBUG\"):\n            result = await subject.get_last_ssh_login(\"en\")\n        self.assertEqual(result[\"user\"], \"root\")\n        self.assertEqual(spawn.call_args.args, (\"tail\", \"-n\", \"200\", \"--\", log_path))\n\n    async def test_notification_monitors_use_argv_without_a_shell(self):\n        class EmptyStream:\n            def __aiter__(self):\n                return self\n\n            async def __anext__(self):\n                raise StopAsyncIteration\n\n        for function_name, args, expected in (\n            (\n                \"reliable_journal_monitor\",\n                (),\n                (\"journalctl\", \"-n\", \"0\", \"-f\", \"-o\", \"cat\", \"_COMM=sshd\", \"+\", \"_COMM=sshd-session\"),\n            ),\n            (\n                \"reliable_tail_log_monitor\",\n                (\"/host/log path/auth.log; touch marker\",),\n                (\"tail\", \"-n\", \"0\", \"-F\", \"--\", \"/host/log path/auth.log; touch marker\"),\n            ),\n        ):\n            with self.subTest(monitor=function_name):\n                spawn = AsyncMock(return_value=SimpleNamespace(\n                    stdout=EmptyStream(), stderr=SimpleNamespace(read=AsyncMock(return_value=b\"\")),\n                    wait=AsyncMock(return_value=0),\n                ))\n                subject = load_functions(\n                    \"notifications.py\", [function_name],\n                    asyncio=SimpleNamespace(\n                        create_subprocess_exec=spawn,\n                        subprocess=asyncio.subprocess,\n                        sleep=AsyncMock(side_effect=asyncio.CancelledError),\n                        CancelledError=asyncio.CancelledError,\n                    ),\n                    os=SimpleNamespace(path=SimpleNamespace(exists=lambda path: True)),\n                )\n                with self.assertRaises(asyncio.CancelledError):\n                    await getattr(subject, function_name)(None, *args, \"logins\", AsyncMock())\n                self.assertEqual(spawn.call_args.args, expected)\n                self.assertTrue(spawn.call_args.kwargs[\"start_new_session\"])\n\n    async def test_invalid_cached_speedtest_port_does_not_hide_valid_servers(self):\n        response = SimpleNamespace(status=500)\n        request = AsyncMock()\n        request.__aenter__.return_value = response\n        session = SimpleNamespace(get=Mock(return_value=request))\n        session_context = AsyncMock()\n        session_context.__aenter__.return_value = session\n        subject = load_functions(\n            \"speedtest.py\", [\"fetch_servers_async\"],\n            Any=object,\n            aiohttp=SimpleNamespace(ClientSession=lambda: session_context),\n            os=SimpleNamespace(path=SimpleNamespace(exists=lambda path: True)),\n            json=json, SERVER_LIST_URL=\"https://example.test\",\n            LOCAL_CACHE_FILE=\"cache.json\",\n        )\n        servers = [\n            {\"IP/HOST\": \"invalid.example\", \"PORT\": \"not-a-port\"},\n            {\"IP/HOST\": \"valid.example\", \"PORT\": \"5201-5209\"},\n        ]\n        with patch(\"builtins.open\", mock_open(read_data=json.dumps(servers))), self.assertLogs(level=\"DEBUG\"):\n            result = await subject.fetch_servers_async(None)\n        self.assertEqual([(server[\"host\"], server[\"port\"]) for server in result], [\n            (\"valid.example\", 5201),\n        ])\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_dashboard_widgets.cjs": "const assert = require('node:assert/strict');\nconst { test } = require('node:test');\n\ntest('pushQuickStatHistory preserves consecutive steady load values and caps at max', () => {\n    const quickStatsHistory = { cpu: [], ram: [], disk: [] };\n    const QUICK_STATS_HISTORY_MAX = 30;\n\n    function pushQuickStatHistory(key, value) {\n        if (typeof value !== 'number' || Number.isNaN(value)) return;\n        const hist = quickStatsHistory[key];\n        hist.push(value);\n        if (hist.length > QUICK_STATS_HISTORY_MAX) hist.shift();\n    }\n\n    // Server at steady 100% CPU\n    for (let i = 0; i < 35; i++) {\n        pushQuickStatHistory('cpu', 100);\n    }\n    assert.equal(quickStatsHistory.cpu.length, 30);\n    assert.ok(quickStatsHistory.cpu.every(v => v === 100));\n\n    // Disk at constant 20%\n    for (let i = 0; i < 5; i++) {\n        pushQuickStatHistory('disk', 20);\n    }\n    assert.equal(quickStatsHistory.disk.length, 5);\n    assert.ok(quickStatsHistory.disk.every(v => v === 20));\n});\n\ntest('getQuickStatColor reflects peak and warn thresholds', () => {\n    const quickStatsHistory = { cpu: [100], ram: [82], disk: [20] };\n    const SYS_CONFIG = { cpu_threshold: 90, ram_threshold: 80, disk_threshold: 95 };\n\n    function getQuickStatColor(key, defaultRgb) {\n        const hist = quickStatsHistory[key];\n        const val = hist && hist.length ? hist[hist.length - 1] : 0;\n        if (typeof SYS_CONFIG !== 'undefined') {\n            const threshold = (key === 'cpu' ? SYS_CONFIG.cpu_threshold : key === 'ram' ? SYS_CONFIG.ram_threshold : SYS_CONFIG.disk_threshold) || 90;\n            const isPeak = val >= Math.max(threshold, 95) || val >= threshold + 5;\n            const isWarn = val >= threshold;\n            if (isPeak) return 'rgb(239, 68, 68)';\n            if (isWarn) return 'rgb(249, 115, 22)';\n        }\n        return defaultRgb;\n    }\n\n    assert.equal(getQuickStatColor('cpu', 'rgb(99, 102, 241)'), 'rgb(239, 68, 68)'); // 100 >= 95 -> Peak (red)\n    assert.equal(getQuickStatColor('ram', 'rgb(168, 85, 247)'), 'rgb(249, 115, 22)'); // 82 >= 80 -> Warn (orange)\n    assert.equal(getQuickStatColor('disk', 'rgb(34, 197, 94)'), 'rgb(34, 197, 94)');  // 20 < 95 -> Default (green)\n});\n\ntest('renderNodeModalTraffic calculates interface-specific vs total traffic', () => {\n    const sampleData = {\n        stats: {\n            net_rx: 869000000000,\n            net_tx: 857000000000,\n            interface_counters: {\n                eth0: [100000000, 200000000],\n                wg0: [5000000, 10000000]\n            }\n        }\n    };\n\n    function resolveTraffic(data, selectedInterface) {\n        const stats = data.stats;\n        let rx = stats.net_rx;\n        let tx = stats.net_tx;\n\n        if (selectedInterface) {\n            const counters = stats.interfaces?.[selectedInterface] || stats.interface_counters?.[selectedInterface];\n            if (Array.isArray(counters)) {\n                rx = counters[0];\n                tx = counters[1];\n            } else if (counters && typeof counters === 'object') {\n                rx = counters.bytes_recv ?? counters.rx;\n                tx = counters.bytes_sent ?? counters.tx;\n            } else {\n                rx = undefined;\n                tx = undefined;\n            }\n        }\n        return { rx, tx };\n    }\n\n    // All interfaces\n    assert.deepEqual(resolveTraffic(sampleData, ''), { rx: 869000000000, tx: 857000000000 });\n\n    // eth0 interface\n    assert.deepEqual(resolveTraffic(sampleData, 'eth0'), { rx: 100000000, tx: 200000000 });\n\n    // wg0 interface\n    assert.deepEqual(resolveTraffic(sampleData, 'wg0'), { rx: 5000000, tx: 10000000 });\n\n    // Unknown interface\n    assert.deepEqual(resolveTraffic(sampleData, 'unknown0'), { rx: undefined, tx: undefined });\n});\n",
  "test_deploy_backup_cleanup.py": "import os\nimport re\nimport shutil\nimport asyncio\nimport tempfile\nimport unittest\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\nBASH = shutil.which(\"bash\")\nif not BASH and os.name == \"nt\":\n    candidate = Path(r\"C:\\Program Files\\Git\\bin\\bash.exe\")\n    if candidate.is_file():\n        BASH = str(candidate)\n\n\n@unittest.skipUnless(BASH, \"Bash is required for installer checks\")\nclass InstallerCleanupTests(unittest.IsolatedAsyncioTestCase):\n    async def run_cleanup(self, root, program, saved):\n        process = await asyncio.create_subprocess_exec(\n            BASH, \"-c\", program, cwd=root,\n            env={**os.environ, \"BOT_INSTALL_PATH\": root.as_posix()},\n            stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE,\n        )\n        try:\n            stdout, stderr = await asyncio.wait_for(process.communicate(), timeout=15)\n        except asyncio.TimeoutError:\n            process.kill()\n            await process.communicate()\n            raise\n        self.assertEqual(process.returncode, 0, stdout.decode(errors=\"replace\") + stderr.decode(errors=\"replace\"))\n        for path in saved:\n            self.assertEqual(path.read_text(encoding=\"utf-8\"), \"preserve\")\n\n    async def test_node_cleanup_preserves_operation_journal_and_sqlite_sidecars(self):\n        for script in (\"deploy.sh\", \"deploy_en.sh\"):\n            with self.subTest(script=script), tempfile.TemporaryDirectory() as directory:\n                root = Path(directory).resolve()\n                (root / \".git\").mkdir()\n                config_dir = root / \"config\"\n                config_dir.mkdir()\n                saved = [config_dir / f\"operations-test.db{suffix}\" for suffix in (\"\", \"-wal\", \"-shm\", \"-journal\")]\n                for path in saved:\n                    path.write_text(\"preserve\", encoding=\"utf-8\")\n                trash = config_dir / \"unused.json\"\n                trash.write_text(\"remove\", encoding=\"utf-8\")\n                source = (ROOT / script).read_text(encoding=\"utf-8\")\n                function = re.search(r\"^cleanup_for_node\\(\\) \\{\\n.*?^\\}\", source, re.M | re.S)\n                self.assertIsNotNone(function)\n                program = 'set -e\\nsudo() { \"$@\"; }\\nmsg_info() { :; }\\n' + function.group() + '\\ncleanup_for_node test\\n'\n                # Only a repository-defined function executes in a disposable directory; no external input.\n                await self.run_cleanup(root, program, saved)\n                self.assertFalse(trash.exists())\n\n    async def test_both_installers_preserve_backup_contents_during_cleanup(self):\n        for script in (\"deploy.sh\", \"deploy_en.sh\"):\n            with self.subTest(script=script), tempfile.TemporaryDirectory() as directory:\n                root = Path(directory).resolve()\n                saved = []\n                for folder in (\".backups/pre_update_test\", \".backup\"):\n                    for name in (\"local.py\", \"__pycache__/local.pyc\"):\n                        path = root / folder / name\n                        path.parent.mkdir(parents=True, exist_ok=True)\n                        path.write_text(\"preserve\", encoding=\"utf-8\")\n                        saved.append(path)\n                (root / \"docs\").mkdir()\n                (root / \"__pycache__\").mkdir()\n                source = (ROOT / script).read_text(encoding=\"utf-8\")\n                function = re.search(r\"^cleanup_common_trash\\(\\) \\{\\n.*?^\\}\", source, re.M | re.S)\n                self.assertIsNotNone(function)\n                # Execute only the cleanup function against this disposable root.\n                # No installer entry point, sudo privilege or real installation.\n                program = 'set -e\\nsudo() { \"$@\"; }\\n' + function.group() + '\\ncleanup_common_trash\\n'\n                await self.run_cleanup(root, program, saved)\n                self.assertFalse((root / \"docs\").exists())\n                self.assertFalse((root / \"__pycache__\").exists())\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_endpoint_migration.py": "import unittest\n\nfrom node.endpoint_migration import validate_https_migration_url\n\n\nclass EndpointMigrationTests(unittest.TestCase):\n    def test_migration_preserves_ip_and_accepts_new_https_port(self):\n        self.assertEqual(\n            validate_https_migration_url(\"http://1.2.3.4:8080\", \"https://1.2.3.4:8443\"),\n            \"https://1.2.3.4:8443\",\n        )\n\n    def test_migration_preserves_dns_host(self):\n        self.assertEqual(\n            validate_https_migration_url(\"http://Panel.Example.com:8080\", \"https://panel.example.com\"),\n            \"https://panel.example.com\",\n        )\n\n    def test_migration_rejects_changed_host_and_non_https(self):\n        for advertised in (\"https://attacker.example\", \"http://1.2.3.4:8443\"):\n            with self.subTest(advertised=advertised), self.assertRaises(ValueError):\n                validate_https_migration_url(\"http://1.2.3.4:8080\", advertised)\n\n    def test_migration_rejects_path_and_credentials(self):\n        for advertised in (\"https://1.2.3.4/path\", \"https://user@1.2.3.4\"):\n            with self.subTest(advertised=advertised), self.assertRaises(ValueError):\n                validate_https_migration_url(\"http://1.2.3.4:8080\", advertised)\n\n\nif __name__ == \"__main__\":\n    unittest.main()",
  "test_log_maintenance.py": "import asyncio\nimport os\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom unittest.mock import AsyncMock, patch\n\nfrom core import log_maintenance as subject\n\n\nclass LogRetentionTests(unittest.TestCase):\n    def setUp(self):\n        self.temp = tempfile.TemporaryDirectory()\n        self.addCleanup(self.temp.cleanup)\n        self.root = Path(self.temp.name)\n        self.now = 2_000_000_000\n        self.cutoff = self.now - 7 * 86400\n\n    def file(self, name, mtime=None):\n        path = self.root / name\n        path.parent.mkdir(parents=True, exist_ok=True)\n        path.write_text(\"log\", encoding=\"utf-8\")\n        os.utime(path, (self.cutoff - 1 if mtime is None else mtime,) * 2)\n        return path\n\n    def test_only_known_expired_rotations_are_deleted(self):\n        expired = [self.file(name) for name in (\n            \"bot/bot.log.2026-01-01\", \"watchdog/watchdog.log.1\", \"node/node.log.2026-01-01.gz\",\n        )]\n        kept = [self.file(name) for name in (\n            \"bot/bot.log\", \"bot/notes.log.backup\", \"bot/bot.log.2026-01-01.bak\",\n            \"bot/other.log.1\", \"logs_backups/bot.log.1\", \"audit/audit.log.1\",\n            \"bot/nested/bot.log.1\", \"bot/bot.log_2026-01-01\",\n        )]\n        kept.extend([self.file(\"bot/bot.log.2\", self.cutoff), self.file(\"bot/bot.log.3\", self.now)])\n        result = subject.cleanup_old_logs(self.root, 7, now=self.now)\n        self.assertEqual((result.deleted, result.errors), (3, 0))\n        self.assertTrue(all(not path.exists() for path in expired))\n        self.assertTrue(all(path.exists() for path in kept))\n\n    def test_missing_directories_and_invalid_retention(self):\n        self.assertEqual(subject.cleanup_old_logs(self.root).deleted, 0)\n        for days in (0, -1):\n            with self.assertRaises(ValueError):\n                subject.cleanup_old_logs(self.root, days)\n\n    def test_delete_error_is_reported_and_other_files_are_processed(self):\n        blocked = self.file(\"bot/bot.log.1\")\n        removed = self.file(\"watchdog/watchdog.log.1\")\n        original = os.remove\n\n        def remove(path):\n            if Path(path) == blocked:\n                raise PermissionError(\"denied\")\n            original(path)\n\n        with patch.object(subject.os, \"remove\", side_effect=remove), self.assertLogs(level=\"WARNING\"):\n            result = subject.cleanup_old_logs(self.root, now=self.now)\n        self.assertEqual((result.deleted, result.errors), (1, 1))\n        self.assertTrue(blocked.exists())\n        self.assertFalse(removed.exists())\n\n    def test_symlink_to_log_is_not_removed(self):\n        target = self.file(\"external.txt\")\n        link = self.root / \"bot\" / \"bot.log.1\"\n        link.parent.mkdir()\n        try:\n            link.symlink_to(target)\n        except OSError:\n            self.skipTest(\"Symlink creation is not permitted\")\n        result = subject.cleanup_old_logs(self.root, now=self.now)\n        self.assertEqual(result.deleted, 0)\n        self.assertTrue(link.is_symlink())\n        self.assertTrue(target.exists())\n\n\nclass LogTaskTests(unittest.IsolatedAsyncioTestCase):\n    async def test_startup_periodic_retry_and_cancellation(self):\n        results = [subject.CleanupResult(), subject.CleanupResult(errors=1), OSError(\"disk error\")]\n        with patch.object(subject, \"cleanup_old_logs\", side_effect=results) as cleanup, \\\n                patch.object(subject.asyncio, \"sleep\", new_callable=AsyncMock) as sleep, \\\n                self.assertLogs(level=\"ERROR\"):\n            sleep.side_effect = [None, None, asyncio.CancelledError()]\n            with self.assertRaises(asyncio.CancelledError):\n                await subject.maintain_logs(\"logs\", 7)\n        self.assertEqual(cleanup.call_count, 3)\n        self.assertEqual([call.args[0] for call in sleep.await_args_list], [21600, 300, 300])\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_manage_cli_bootstrap.py": "\"\"\"Regression checks for tgcp-bot command dispatch and DB bootstrap timing.\n\nNo production databases, services, or node operations are touched by these tests.\n\"\"\"\nimport sys\nimport types\nimport unittest\nfrom unittest.mock import patch\n\nimport manage\n\n\nclass TrackingCore(types.ModuleType):\n    def __init__(self):\n        super().__init__(\"core\")\n        self.config_seen = False\n        self.config = object()\n\n    def __getattribute__(self, key):\n        if key == \"config\":\n            object.__setattr__(self, \"config_seen\", True)\n        return super().__getattribute__(key)\n\n\nclass CommandDispatchTests(unittest.TestCase):\n    DB_COMMANDS = [\n        [\"adduser\", \"--id\", \"12345\", \"--name\", \"Tester\"],\n        [\"webpass\"],\n        [\"stats\"],\n        [\"update-nodes\", \"--branch\", \"hotfix/1.28.1\"],\n        [\"tls\", \"status\"],\n        [\"tls\", \"check\"],\n        [\"tls\", \"finalize\"],\n    ]\n    NO_DB_COMMANDS = [[\"cleanlogs\"], [\"restart\"], [\"status\"]]\n\n    def run_mocked_command(self, argv, expects_config):\n        core = TrackingCore()\n        calls = []\n\n        async def fake_command(*args):\n            calls.append((\"command\", argv[0]))\n\n        def fake_run(coroutine):\n            try:\n                calls.append((\"run\", core.config_seen))\n                self.assertEqual(\n                    core.config_seen, expects_config,\n                    f\"{argv} imported DB config at the wrong stage\",\n                )\n            finally:\n                coroutine.close()\n\n        names = [\n            \"cmd_adduser\", \"cmd_webpass\", \"cmd_stats\", \"cmd_update_nodes\",\n            \"cmd_tls_status\", \"cmd_tls_check\", \"cmd_tls_finalize\",\n            \"cmd_cleanlogs\", \"cmd_restart\", \"cmd_status\",\n        ]\n        patches = [patch.object(manage, n, fake_command) for n in names]\n        patches += [\n            patch.object(manage.asyncio, \"run\", fake_run),\n            patch.dict(sys.modules, {\"core\": core}),\n        ]\n        for p in patches:\n            p.start()\n            self.addCleanup(p.stop)\n        result = manage.main(argv)\n        self.assertEqual(result, 0, f\"Command {argv} failed\")\n        self.assertEqual(len([c for c in calls if c[0] == \"run\"]), 1)\n        # Stop mocks before the next command in the same test.\n        for p in reversed(patches):\n            p.stop()\n\n    def test_db_commands_import_config_before_event_loop(self):\n        for command in self.DB_COMMANDS:\n            with self.subTest(command=command):\n                self.run_mocked_command(command, True)\n\n    def test_service_and_log_commands_do_not_require_config_bootstrap(self):\n        for command in self.NO_DB_COMMANDS:\n            with self.subTest(command=command):\n                self.run_mocked_command(command, False)\n\n    def test_integrity_runs_synchronously(self):\n        core = TrackingCore()\n        with patch.dict(sys.modules, {\"core\": core}), \\\n             patch.object(manage, \"cmd_integrity\", return_value=0) as action, \\\n             patch.object(manage.asyncio, \"run\", side_effect=AssertionError(\"Unexpected loop\")):\n            self.assertEqual(manage.main([\"integrity\", \"check\"]), 0)\n            action.assert_called_once()\n            self.assertFalse(core.config_seen)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_node_client_updates.py": "import asyncio\nimport importlib.util\nimport re\nimport runpy\nimport secrets\nimport shutil\nimport subprocess  # nosec B404\nimport sys\nimport tempfile\nimport time\nimport unittest\nfrom pathlib import Path\nfrom types import SimpleNamespace\nfrom unittest.mock import AsyncMock, MagicMock, Mock, patch\n\nfrom node import software_update\n\nROOT = Path(__file__).resolve().parents[1]\nOLD = \"a\" * 40\nNEW = \"b\" * 40\nTEST_GIT = shutil.which(\"git\")\n\n\ndef load_subject(name, path, dependencies):\n    spec = importlib.util.spec_from_file_location(name, ROOT / path)\n    subject = importlib.util.module_from_spec(spec)\n    with patch.dict(sys.modules, {name: subject, **dependencies}):\n        spec.loader.exec_module(subject)\n    return subject\n\n\nclass ConfirmationTests(unittest.IsolatedAsyncioTestCase):\n    def setUp(self):\n        self.subject = load_subject(\"core.test_node_updates\", \"core/node_updates.py\", {\n            \"core\": SimpleNamespace(config=SimpleNamespace(NODE_OFFLINE_TIMEOUT=20)),\n            \"core.models\": SimpleNamespace(Node=MagicMock(), NodeClientUpdate=MagicMock()),\n            \"tortoise.transactions\": SimpleNamespace(in_transaction=MagicMock()),\n        })\n        self.subject.eligible_nodes = AsyncMock(return_value=([{\"id\": 8, \"name\": \"One\"}], 2))\n\n    async def test_plan_is_bound_to_owner_branch_and_single_use(self):\n        token = (await self.subject.prepare(1, \"main\"))[\"token\"]\n        self.assertIsNone(self.subject.consume(token, 2, \"main\"))\n        self.assertIsNone(self.subject.consume(token, 1, \"develop\"))\n        self.assertEqual(self.subject.consume(token, 1, \"main\").nodes, (8,))\n        self.assertIsNone(self.subject.consume(token, 1, \"main\"))\n\n    async def test_plan_expires(self):\n        with patch.object(self.subject.time, \"monotonic\", return_value=1):\n            token = (await self.subject.prepare(1, \"main\"))[\"token\"]\n        with patch.object(self.subject.time, \"monotonic\", return_value=1 + self.subject.PLAN_TTL):\n            self.assertIsNone(self.subject.consume(token, 1, \"main\"))\n\n    async def test_no_token_is_issued_without_eligible_nodes(self):\n        self.subject.eligible_nodes.return_value = ([], 2)\n        plan = await self.subject.prepare(1, \"main\")\n        self.assertEqual(plan, {\"nodes\": [], \"skipped\": 2})\n\n    async def test_heartbeat_only_completes_update_on_running_target(self):\n        subject = self.subject\n        report = {\"commit\": OLD, \"supported\": True}\n        self.assertEqual(await subject.heartbeat_task(8, report), (None, None))\n        subject.NodeClientUpdate.filter.assert_not_called()\n\n        subject.running_commit = NEW\n        job = SimpleNamespace(id=20, branch=\"main\", commit=NEW, requested_by=1, expires_at=time.time() + 100)\n        query = subject.NodeClientUpdate.filter.return_value\n        query.order_by.return_value.first = AsyncMock(return_value=job)\n        query.update = AsyncMock(return_value=1)\n        task, outcome = await subject.heartbeat_task(8, report)\n        self.assertEqual(task, {\"id\": 20, \"branch\": \"main\", \"commit\": NEW, \"expires_at\": job.expires_at})\n        self.assertIsNone(outcome)\n        self.assertEqual(subject.NodeClientUpdate.filter.call_args.kwargs[\"commit\"], NEW)\n        query.update.assert_not_awaited()\n        self.assertEqual(await subject.heartbeat_task(8, {**report, \"commit\": NEW}), (None, (1, \"updated\")))\n        query.update.assert_awaited_once_with(status=\"updated\")\n\n\nclass AgentUpdateTests(unittest.IsolatedAsyncioTestCase):\n    def setUp(self):\n        self.directory = tempfile.TemporaryDirectory()\n        self.addCleanup(self.directory.cleanup)\n        self.confirmation = secrets.token_urlsafe(16)\n        self.node_updates = SimpleNamespace(\n            COMMIT=re.compile(r\"[0-9a-f]{40}\"), BRANCH=re.compile(r\"[A-Za-z0-9._/-]{1,255}\"),\n            agent_update_lock=asyncio.Lock(),\n            read_agent_commit=AsyncMock(return_value=OLD),\n            queue_updates=AsyncMock(return_value=1),\n            prepare=AsyncMock(return_value={\n                \"token\": self.confirmation, \"nodes\": [{\"id\": 8, \"name\": \"<Node>\"}], \"skipped\": 0,\n            }),\n            consume=Mock(),\n        )\n        self.config = SimpleNamespace(\n            ADMIN_USER_ID=1, DEPLOY_MODE=\"systemd\", BASE_DIR=self.directory.name,\n            RESTART_FLAG_FILE=str(Path(self.directory.name) / \"restart_flag.txt\"),\n        )\n        self.shared = SimpleNamespace(IS_RESTARTING=False, LAST_MESSAGE_IDS={})\n        self.integrity = SimpleNamespace(backup_modified_files=Mock(return_value=(True, \"\", [])))\n        self.subject = load_subject(\"agent_update_subject\", \"modules/update.py\", {\n            \"aiohttp\": MagicMock(), \"aiogram\": MagicMock(), \"aiogram.exceptions\": MagicMock(),\n            \"aiogram.types\": MagicMock(), \"core.auth\": MagicMock(), \"core.i18n\": MagicMock(),\n            \"core.messaging\": MagicMock(), \"core.utils\": MagicMock(),\n            \"core.integrity\": self.integrity, \"core.config\": self.config,\n            \"core.shared_state\": self.shared,\n            \"core\": SimpleNamespace(config=self.config, shared_state=self.shared, node_updates=self.node_updates, utils=MagicMock()),\n        })\n        self.subject._ = lambda key, lang, **params: key + str(params)\n        self.subject.is_allowed = lambda user_id, command: user_id == 1\n        self.subject.escape_html = lambda value: value.replace(\"<\", \"&lt;\").replace(\">\", \"&gt;\")\n        self.subject.InlineKeyboardButton = SimpleNamespace\n        self.subject.InlineKeyboardMarkup = SimpleNamespace\n        self.subject.self_terminate = AsyncMock()\n\n    def callback(self, data, user_id=1):\n        return SimpleNamespace(\n            data=data, from_user=SimpleNamespace(id=user_id), answer=AsyncMock(),\n            message=SimpleNamespace(\n                chat=SimpleNamespace(id=1), message_id=9, edit_text=AsyncMock(),\n            ),\n        )\n\n    async def test_telegram_previews_then_requires_valid_confirmation(self):\n        self.subject.execute_bot_update = AsyncMock(return_value=1)\n        preview = self.callback(\"do_bot_update:main\")\n        await self.subject.run_bot_update(preview)\n        self.subject.execute_bot_update.assert_not_awaited()\n        self.assertIn(\"&lt;Node&gt;\", preview.message.edit_text.call_args.args[0])\n\n        self.node_updates.consume.return_value = None\n        await self.subject.run_bot_update(self.callback(f\"do_bot_update_nodes:{self.confirmation}\"))\n        self.subject.execute_bot_update.assert_not_awaited()\n\n        self.node_updates.consume.return_value = SimpleNamespace(branch=\"main\", nodes=(8,))\n        await self.subject.run_bot_update(self.callback(f\"do_bot_update_nodes:{self.confirmation}\", user_id=2))\n        self.subject.execute_bot_update.assert_not_awaited()\n        await self.subject.run_bot_update(self.callback(f\"do_bot_update_agent:{self.confirmation}\"))\n        self.assertEqual(self.subject.execute_bot_update.call_args.kwargs[\"node_ids\"], ())\n        await self.subject.run_bot_update(self.callback(f\"do_bot_update_nodes:{self.confirmation}\"))\n        self.assertEqual(self.subject.execute_bot_update.call_args.kwargs[\"node_ids\"], (8,))\n\n    async def test_failed_agent_dependencies_do_not_queue_nodes(self):\n        self.subject.run_command = AsyncMock(side_effect=[\n            (0, \"\", \"\"), (0, NEW, \"\"), (0, \"\", \"\"), (1, \"\", \"pip failed\"), (0, \"\", \"\"),\n        ])\n        with patch.dict(sys.modules, {\"core.integrity\": self.integrity}):\n            with self.assertRaisesRegex(RuntimeError, \"Dependency installation failed\"):\n                await self.subject.execute_bot_update(\"main\", node_ids=(8,))\n        self.node_updates.queue_updates.assert_not_awaited()\n        self.subject.self_terminate.assert_not_called()\n        self.assertFalse(self.shared.IS_RESTARTING)\n\n    async def test_success_queues_the_exact_agent_revision(self):\n        self.subject.run_command = AsyncMock(side_effect=[\n            (0, \"\", \"\"), (0, NEW, \"\"), (0, \"\", \"\"), (0, \"\", \"\"), (0, \"\", \"\"),\n        ])\n        with patch.dict(sys.modules, {\"core.integrity\": self.integrity}):\n            self.assertEqual(await self.subject.execute_bot_update(\"main\", node_ids=(8,)), 1)\n        self.node_updates.queue_updates.assert_awaited_once_with((8,), \"main\", NEW, 1)\n        self.assertTrue(self.shared.IS_RESTARTING)\n        await asyncio.sleep(0)\n        self.subject.self_terminate.assert_awaited_once()\n\n    async def test_update_preserves_local_edit_backups_on_success_and_failure(self):\n        for fail_install in (False, True):\n            with self.subTest(fail_install=fail_install):\n                self.shared.IS_RESTARTING = False\n                paths = [Path(self.directory.name) / name / \"saved.txt\" for name in (\".backup\", \".backups/pre_update_test\")]\n                for path in paths:\n                    path.parent.mkdir(parents=True, exist_ok=True)\n                    path.write_text(\"local changes\", encoding=\"utf-8\")\n                self.subject.run_command = AsyncMock(side_effect=[\n                    (0, \"\", \"\"), (0, NEW, \"\"), (0, \"\", \"\"),\n                    (1, \"\", \"pip failed\") if fail_install else (0, \"\", \"\"),\n                    (0, \"\", \"\"),\n                ])\n                with patch.dict(sys.modules, {\"core.integrity\": self.integrity}):\n                    if fail_install:\n                        with self.assertRaisesRegex(RuntimeError, \"Dependency installation failed\"):\n                            await self.subject.execute_bot_update(\"main\")\n                    else:\n                        await self.subject.execute_bot_update(\"main\")\n                        await asyncio.sleep(0)\n                for path in paths:\n                    self.assertEqual(path.read_text(encoding=\"utf-8\"), \"local changes\")\n\n    async def test_backup_failure_prevents_git_reset_and_restart(self):\n        for failure in (False, OSError(\"disk full\")):\n            with self.subTest(failure=failure):\n                self.integrity.backup_modified_files.side_effect = failure if isinstance(failure, Exception) else None\n                self.integrity.backup_modified_files.return_value = (False, \"\", [])\n                self.subject.run_command = AsyncMock(return_value=(0, \"\", \"\"))\n                with patch.dict(sys.modules, {\"core.integrity\": self.integrity}):\n                    with self.assertRaisesRegex(RuntimeError, \"Pre-update backup failed\"):\n                        await self.subject.execute_bot_update(\"main\")\n                self.subject.run_command.assert_awaited_once_with(\"git\", \"fetch\", \"origin\")\n                self.subject.self_terminate.assert_not_called()\n                self.assertFalse(self.shared.IS_RESTARTING)\n\n    async def test_update_check_uses_checked_out_version_after_restart(self):\n        self.subject.utils.get_app_version.return_value = \"v1.0.0\"\n        self.subject.get_current_branch = AsyncMock(return_value=\"main\")\n        self.subject.get_remote_version_github = AsyncMock(return_value=\"v1.1.0\")\n        self.subject.run_command = AsyncMock(side_effect=[\n            (0, \"img.shields.io/badge/version-v1.1.0-blue\", \"\"), (0, \"\", \"\"),\n        ])\n        self.assertEqual(await self.subject.get_update_info(), (\"v1.1.0\", \"v1.1.0\", \"main\", False))\n\n    async def test_web_requires_a_confirmed_plan_for_nodes(self):\n        def response(payload, status=200):\n            return SimpleNamespace(payload=payload, status=status)\n\n        route = lambda _path: lambda handler: handler\n        web = SimpleNamespace(\n            RouteTableDef=lambda: SimpleNamespace(get=route, post=route),\n            json_response=response,\n        )\n        config = MagicMock(ADMIN_USER_ID=1)\n        payload = AsyncMock()\n        dependencies = {\n            \"aiohttp\": SimpleNamespace(web=web),\n            \"core\": SimpleNamespace(config=config, node_updates=self.node_updates, nodes_db=MagicMock(), shared_state=self.shared),\n            \"core.config\": config,\n            \"core.auth\": MagicMock(), \"core.i18n\": MagicMock(),\n            \"core.shared_state\": MagicMock(),\n            \"core.rbac\": SimpleNamespace(is_admin=lambda user: True),\n            \"core.utils\": MagicMock(decrypt_request_payload=payload, encrypted_json_response=response),\n            \"core.web.auth\": SimpleNamespace(get_current_user=lambda request: request.user),\n        }\n        api = load_subject(\"core.web.test_update_system\", \"core/web/api_system.py\", dependencies)\n        self.subject.execute_bot_update = AsyncMock(return_value=1)\n        owner, admin = (SimpleNamespace(user={\"id\": user_id}) for user_id in (1, 2))\n        with patch.dict(sys.modules, {\"modules\": SimpleNamespace(update=self.subject)}):\n            payload.return_value = {\"branch\": \"main\", \"node_ids\": [8]}\n            self.assertEqual((await api.api_run_update(owner)).status, 200)\n            self.assertEqual(self.subject.execute_bot_update.call_args.kwargs[\"node_ids\"], ())\n            self.subject.execute_bot_update.reset_mock()\n\n            payload.return_value[\"node_confirmation\"] = self.confirmation\n            self.assertEqual((await api.api_run_update(admin)).status, 403)\n            self.node_updates.consume.return_value = None\n            self.assertEqual((await api.api_run_update(owner)).status, 409)\n            self.subject.execute_bot_update.assert_not_awaited()\n\n            self.node_updates.consume.return_value = SimpleNamespace(nodes=(9,))\n            self.assertEqual((await api.api_run_update(owner)).payload[\"nodes_queued\"], 1)\n            self.assertEqual(self.subject.execute_bot_update.call_args.kwargs[\"node_ids\"], (9,))\n\n\nclass NodeUpdateCliTests(unittest.TestCase):\n    def test_cold_start_loads_config_before_the_event_loop(self):\n        with tempfile.TemporaryDirectory() as directory:\n            root = Path(directory)\n            shutil.copyfile(ROOT / \"manage.py\", root / \"manage.py\")\n            core = root / \"core\"\n            core.mkdir()\n            (core / \"__init__.py\").touch()\n            (core / \"config.py\").write_text(\n                \"import asyncio\\nasyncio.run(asyncio.sleep(0))\\n\"\n                \"DEFAULT_LANGUAGE = 'en'\\nADMIN_USER_ID = 1\\n\",\n                encoding=\"utf-8\",\n            )\n            (core / \"node_updates.py\").write_text(\n                \"from . import config\\n\"\n                \"async def read_agent_commit(): return 'a' * 40\\n\"\n                \"async def eligible_nodes(): return [{'id': 8, 'name': 'Node'}], 0\\n\"\n                \"async def queue_updates(*args): raise AssertionError('No confirmation given')\\n\",\n                encoding=\"utf-8\",\n            )\n            (core / \"nodes_db.py\").write_text(\"async def init_db(): pass\\n\", encoding=\"utf-8\")\n            (core / \"i18n.py\").write_text(\"def _(key, lang, **params): return key\\n\", encoding=\"utf-8\")\n            (root / \"tortoise.py\").write_text(\n                \"class Tortoise:\\n    @staticmethod\\n    async def close_connections(): pass\\n\",\n                encoding=\"utf-8\",\n            )\n\n            with patch.dict(sys.modules), patch.object(sys, \"path\", [str(root), *sys.path]):\n                for name in (\"core\", \"core.config\", \"core.node_updates\", \"core.nodes_db\", \"core.i18n\", \"tortoise\"):\n                    sys.modules.pop(name, None)\n                cli = runpy.run_path(str(root / \"manage.py\"))\n                with patch(\"builtins.input\", return_value=\"n\") as confirm, patch(\"builtins.print\"):\n                    self.assertEqual(cli[\"main\"]([\"update-nodes\"]), 0)\n\n        confirm.assert_called_once_with(\"node_client_update_cli_prompt\")\n\n\n@unittest.skipUnless(TEST_GIT, \"Git is required to exercise the node checkout\")\nclass NodeCheckoutTests(unittest.TestCase):\n    def setUp(self):\n        self.directory = tempfile.TemporaryDirectory()\n        self.addCleanup(self.directory.cleanup)\n        root = Path(self.directory.name)\n        self.origin = root / \"origin\"\n        self.origin.mkdir()\n        self.checkout = root / \"client\"\n        self.git(self.origin, \"init\", \"-b\", \"main\")\n        self.git(self.origin, \"config\", \"user.name\", \"Node update test\")\n        self.git(self.origin, \"config\", \"user.email\", \"node-update@example.invalid\")\n        (self.origin / \"node\").mkdir()\n        for name in (\"node/node.py\", \"node/endpoint_migration.py\", \"node/software_update.py\", \"network_validation.py\"):\n            (self.origin / name).write_text(\"value = 1\\n\")\n        (self.origin / \".gitignore\").write_text(\".env\\n/config/\\n\")\n        (self.origin / \"excluded.py\").write_text(\"value = 1\\n\")\n        self.commit(\"initial\")\n        self.git(root, \"clone\", \"--depth=1\", self.origin.as_uri(), str(self.checkout))\n        self.git(self.checkout, \"sparse-checkout\", \"set\", \"--no-cone\", \"/node/\", \"/network_validation.py\", \"/.gitignore\")\n        (self.checkout / \".env\").write_text(\"MODE=node\\n\")\n        (self.checkout / \"config\").mkdir()\n        (self.checkout / \"config\" / \"state\").write_text(\"state\")\n\n    @staticmethod\n    def git(path, *args):\n        # The executable is resolved on the test host. Arguments come from the temporary repo fixture.\n        return subprocess.check_output(  # nosec B603, B607\n            [\"git\", \"-C\", str(path), *args], executable=TEST_GIT, shell=False,\n            stderr=subprocess.PIPE, text=True,\n        ).strip()\n\n    def commit(self, message):\n        self.git(self.origin, \"add\", \".\")\n        self.git(self.origin, \"commit\", \"--no-gpg-sign\", \"-m\", message)\n        return self.git(self.origin, \"rev-parse\", \"HEAD\")\n\n    def updater(self, *, fail_restart=False):\n        real_run = subprocess.run\n        self.restarts = 0\n\n        def run(argv, *args, **kwargs):\n            if argv[0] == \"/usr/bin/systemctl\":\n                self.assertFalse(kwargs[\"shell\"])\n                self.assertEqual(argv[-1], software_update.SERVICE)\n                if argv[1] == \"show\":\n                    return SimpleNamespace(stdout=str(software_update.os.getpid()).encode())\n                self.assertEqual(argv[1:-1], [\"--no-block\", \"restart\"])\n                self.restarts += 1\n                if fail_restart:\n                    raise subprocess.CalledProcessError(1, argv)\n                return SimpleNamespace(stdout=b\"\")\n            if argv[0] == \"/usr/bin/git\":\n                self.assertFalse(kwargs[\"shell\"])\n                argv = [TEST_GIT, *argv[1:]]\n            return real_run(argv, *args, **kwargs)\n\n        patcher = patch.object(software_update.subprocess, \"run\", side_effect=run)\n        patcher.start()\n        self.addCleanup(patcher.stop)\n        with patch.object(software_update.os, \"geteuid\", return_value=0, create=True):\n            return software_update.ClientUpdater(str(self.checkout))\n\n    def update(self, updater, commit):\n        with patch.object(software_update, \"REPOSITORY\", self.origin.as_uri()):\n            updater.offer({\"id\": 1, \"branch\": \"main\", \"commit\": commit, \"expires_at\": time.time() + 100})\n            updater.worker.join(15)\n            self.assertFalse(updater.worker.is_alive())\n\n    def test_updates_to_pinned_commit_and_preserves_node_files(self):\n        (self.origin / \"node\" / \"node.py\").write_text(\"value = 2\\n\")\n        approved = self.commit(\"approved\")\n        (self.origin / \"node\" / \"node.py\").write_text(\"value = 3\\n\")\n        self.commit(\"unapproved newer tip\")\n        updater = self.updater()\n        self.update(updater, approved)\n        self.assertEqual(self.git(self.checkout, \"rev-parse\", \"HEAD\"), approved)\n        self.assertEqual((self.checkout / \".env\").read_text(), \"MODE=node\\n\")\n        self.assertEqual((self.checkout / \"config\" / \"state\").read_text(), \"state\")\n        self.assertFalse((self.checkout / \"excluded.py\").exists())\n        self.assertEqual(self.restarts, 1)\n        self.assertTrue(updater.report()[\"busy\"])\n\n    def test_failed_restart_restores_previous_commit(self):\n        updater = self.updater(fail_restart=True)\n        (self.origin / \"node\" / \"node.py\").write_text(\"value = 2\\n\")\n        approved = self.commit(\"approved\")\n        with self.assertLogs(level=\"ERROR\"):\n            self.update(updater, approved)\n        self.assertEqual(self.git(self.checkout, \"rev-parse\", \"HEAD\"), updater.commit)\n        self.assertEqual(updater.report()[\"failed\"], 1)\n        self.assertFalse(updater.report()[\"busy\"])\n\n    def test_rejects_revision_outside_approved_branch(self):\n        updater = self.updater()\n        self.git(self.origin, \"checkout\", \"-b\", \"other\")\n        (self.origin / \"node\" / \"node.py\").write_text(\"value = 2\\n\")\n        other = self.commit(\"another branch\")\n        with self.assertLogs(level=\"ERROR\"):\n            self.update(updater, other)\n        self.assertEqual(self.git(self.checkout, \"rev-parse\", \"HEAD\"), updater.commit)\n        self.assertEqual(self.restarts, 0)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_node_confirmations.py": "import importlib.util\nimport asyncio\nfrom pathlib import Path\nimport sys\nfrom types import SimpleNamespace\nimport unittest\nfrom unittest.mock import AsyncMock, MagicMock, Mock, patch\n\n\nROOT = Path(__file__).resolve().parents[1]\nTOKEN = \"a\" * 32\n\n\nclass NodeConfirmationTests(unittest.IsolatedAsyncioTestCase):\n    def setUp(self):\n        dependencies = {\n            name: MagicMock()\n            for name in (\n                \"aiohttp\", \"aiogram\", \"aiogram.filters\", \"aiogram.fsm\",\n                \"aiogram.fsm.context\", \"aiogram.fsm.state\", \"aiogram.types\",\n                \"core\", \"core.auth\", \"core.i18n\", \"core.keyboards\",\n                \"core.messaging\", \"core.shared_state\", \"core.utils\",\n            )\n        }\n        dependencies[\"aiogram.fsm.state\"].StatesGroup = object\n        spec = importlib.util.spec_from_file_location(\"node_confirmation_subject\", ROOT / \"modules\" / \"nodes.py\")\n        if spec is None or spec.loader is None:\n            self.fail(\"Unable to load node management module\")\n        subject = importlib.util.module_from_spec(spec)\n        with patch.dict(sys.modules, dependencies):\n            spec.loader.exec_module(subject)\n        self.node = {\"name\": \"<Test node>\", \"services\": [{\"name\": \"my_service\", \"type\": \"docker\"}]}\n        self.db = SimpleNamespace(\n            get_node_by_token=AsyncMock(return_value=self.node),\n            update_node_task=AsyncMock(),\n            update_node_extra=AsyncMock(),\n        )\n        replacements = {\n            \"config\": SimpleNamespace(ADMIN_USER_ID=1),\n            \"nodes_db\": self.db,\n            \"get_user_lang\": lambda user_id: \"en\",\n            \"is_allowed\": Mock(return_value=True),\n            \"_\": lambda key, lang, **values: key + str(values),\n            \"InlineKeyboardButton\": lambda **values: SimpleNamespace(**values),\n            \"InlineKeyboardMarkup\": lambda **values: SimpleNamespace(**values),\n            \"get_back_keyboard\": lambda lang, target: target,\n            \"asyncio\": SimpleNamespace(sleep=AsyncMock()),\n            \"cq_node_services\": AsyncMock(),\n        }\n        for name, value in replacements.items():\n            setattr(subject, name, value)\n        self.env = vars(subject)\n\n    def callback(self, data, user_id=1):\n        return SimpleNamespace(\n            data=data,\n            from_user=SimpleNamespace(id=user_id),\n            answer=AsyncMock(),\n            message=SimpleNamespace(edit_text=AsyncMock(), edit_reply_markup=AsyncMock()),\n        )\n\n    async def test_reboot_and_update_require_confirmation(self):\n        for command in (\"reboot\", \"update\"):\n            with self.subTest(command=command):\n                callback = self.callback(f\"node_cmd_{TOKEN}_{command}\")\n                await self.env[\"cq_node_command\"](callback)\n                self.db.update_node_task.assert_not_awaited()\n                self.db.update_node_extra.assert_not_awaited()\n                self.assertIn(\"&lt;Test node&gt;\", callback.message.edit_text.call_args.args[0])\n                rows = callback.message.edit_text.call_args.kwargs[\"reply_markup\"].inline_keyboard\n                self.assertEqual(rows[0][0].callback_data, f\"node_run_{TOKEN}_{command}\")\n                self.assertEqual(rows[1][0].callback_data, f\"node_select_{TOKEN}\")\n                self.assertEqual(rows[0][0].style, \"success\")\n                self.assertEqual(rows[1][0].style, \"danger\")\n                self.assertLessEqual(len(rows[0][0].callback_data.encode()), 64)\n\n    async def test_confirmed_commands_queue_correct_task(self):\n        for command in (\"reboot\", \"update\"):\n            with self.subTest(command=command):\n                self.db.update_node_task.reset_mock()\n                self.db.update_node_extra.reset_mock()\n                callback = self.callback(f\"node_run_{TOKEN}_{command}\")\n                await self.env[\"cq_node_command_confirm\"](callback)\n                callback.message.edit_reply_markup.assert_awaited_once_with(reply_markup=None)\n                self.db.update_node_task.assert_awaited_once_with(TOKEN, {\"command\": command, \"user_id\": 1})\n                if command == \"reboot\":\n                    self.db.update_node_extra.assert_awaited_once_with(TOKEN, \"is_restarting\", True)\n                else:\n                    self.db.update_node_extra.assert_not_awaited()\n\n    async def test_confirmed_commands_recheck_permissions_and_node(self):\n        for command in (\"reboot\", \"update\"):\n            with self.subTest(command=command):\n                callback = self.callback(f\"node_run_{TOKEN}_{command}\", user_id=2)\n                await self.env[\"cq_node_command_confirm\"](callback)\n                self.db.update_node_task.assert_not_awaited()\n                self.db.update_node_extra.assert_not_awaited()\n        self.db.get_node_by_token.return_value = None\n        await self.env[\"cq_node_command_confirm\"](self.callback(f\"node_run_{TOKEN}_reboot\"))\n        self.db.update_node_task.assert_not_awaited()\n\n    async def test_confirmation_route_rejects_other_commands(self):\n        await self.env[\"cq_node_command_confirm\"](self.callback(f\"node_run_{TOKEN}_resetuptime\"))\n        self.db.update_node_task.assert_not_awaited()\n\n    async def test_service_restart_requires_confirmation(self):\n        callback = self.callback(f\"nsa_{TOKEN}_my_service_d_restart\")\n        await self.env[\"cq_node_service_action\"](callback)\n        self.db.update_node_task.assert_not_awaited()\n        rows = callback.message.edit_text.call_args.kwargs[\"reply_markup\"].inline_keyboard\n        self.assertEqual(rows[0][0].callback_data, f\"nsc_{TOKEN}_my_service_d_restart\")\n        self.assertEqual(rows[1][0].callback_data, f\"node_services_{TOKEN}\")\n        self.assertLessEqual(len(rows[0][0].callback_data.encode()), 64)\n\n    async def test_confirmed_service_restart_preserves_target(self):\n        callback = self.callback(f\"nsc_{TOKEN}_my_service_d_restart\")\n        await self.env[\"cq_node_service_confirm\"](callback)\n        self.db.update_node_task.assert_awaited_once_with(TOKEN, {\n            \"command\": \"service_action\", \"service\": \"my_service\", \"action\": \"restart\",\n            \"type\": \"docker\", \"user_id\": 1,\n        })\n        self.env[\"cq_node_services\"].assert_awaited_once_with(callback, node_token=TOKEN)\n\n    async def test_service_confirmation_rechecks_target_and_permission(self):\n        for data, user_id in (\n            (f\"nsc_{TOKEN}_my_service_d_restart\", 2),\n            (f\"nsc_{TOKEN}_missing_d_restart\", 1),\n            (f\"nsc_{TOKEN}_my_service_d_stop\", 1),\n        ):\n            with self.subTest(data=data, user_id=user_id):\n                await self.env[\"cq_node_service_confirm\"](self.callback(data, user_id))\n                self.db.update_node_task.assert_not_awaited()\n\n    async def test_service_start_and_stop_are_unchanged(self):\n        for action in (\"start\", \"stop\"):\n            with self.subTest(action=action):\n                self.db.update_node_task.reset_mock()\n                callback = self.callback(f\"nsa_{TOKEN}_my_service_d_{action}\")\n                await self.env[\"cq_node_service_action\"](callback)\n                self.db.update_node_task.assert_awaited_once()\n                callback.message.edit_text.assert_not_awaited()\n\n    async def test_each_traffic_start_creates_its_own_session_and_card(self):\n        self.env[\"config\"].TRAFFIC_INTERVAL = 5\n        self.env[\"NODE_TRAFFIC_MONITORS\"] = {}\n        callback = self.callback(f\"node_cmd_{TOKEN}_traffic\")\n        callback.message.answer = AsyncMock(return_value=SimpleNamespace(message_id=10))\n        self.db.update_node_task.return_value = SimpleNamespace(id=8)\n        await self.env[\"cq_node_command\"](callback)\n        first = self.env[\"NODE_TRAFFIC_MONITORS\"][1].copy()\n        self.assertEqual(first[\"operation_id\"], 8)\n        self.db.update_node_task.assert_awaited_once_with(TOKEN, {\n            \"command\": \"traffic\", \"user_id\": 1, \"traffic_session\": first[\"session_id\"],\n        })\n        self.db.update_node_task.return_value = SimpleNamespace(id=9)\n        await self.env[\"cq_node_command\"](callback)\n        second = self.env[\"NODE_TRAFFIC_MONITORS\"][1]\n        self.assertEqual(second[\"operation_id\"], 9)\n        self.assertNotEqual(second[\"session_id\"], first[\"session_id\"])\n\n    async def test_scheduler_refreshes_existing_traffic_card(self):\n        self.env[\"config\"].TRAFFIC_INTERVAL = 5\n        self.env[\"NODE_TRAFFIC_MONITORS\"] = {1: {\n            \"token\": TOKEN, \"operation_id\": 8, \"session_id\": \"session\", \"message_id\": 10,\n        }}\n        self.env[\"asyncio\"].sleep.side_effect = [None, asyncio.CancelledError()]\n        with self.assertRaises(asyncio.CancelledError):\n            await self.env[\"node_traffic_scheduler\"](Mock())\n        self.db.update_node_task.assert_awaited_once_with(TOKEN, {\n            \"command\": \"traffic\", \"user_id\": 1, \"traffic_session\": \"session\",\n        }, traffic_operation_id=8)\n\n    async def test_old_stop_button_does_not_stop_a_new_traffic_session(self):\n        monitor = {\"token\": TOKEN, \"operation_id\": 8, \"session_id\": \"new\", \"message_id\": 11}\n        self.env[\"NODE_TRAFFIC_MONITORS\"] = {1: monitor}\n        callback = self.callback(f\"node_stop_traffic_{TOKEN}\")\n        callback.message.message_id = 10\n        callback.message.delete = AsyncMock()\n        await self.env[\"cq_node_stop_traffic\"](callback)\n        self.assertIs(self.env[\"NODE_TRAFFIC_MONITORS\"][1], monitor)\n        callback.message.delete.assert_not_awaited()\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_operations_integration.py": "\"\"\"Run real SQLite/ORM tests in a fresh Python process, apart from legacy mocks.\"\"\"\nimport multiprocessing\nimport runpy\nimport sys\nimport unittest\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n\n\ndef _run_operations_scenarios():\n    # A spawned interpreter uses the active Python environment without shell commands.\n    sys.argv = [\"operations_scenarios.py\", \"-v\"]\n    runpy.run_path(str(ROOT / \"tests\" / \"operations_scenarios.py\"), run_name=\"__main__\")\n\n\nclass OperationIntegrationTests(unittest.TestCase):\n    def test_operation_delivery_and_history(self):\n        process = multiprocessing.get_context(\"spawn\").Process(target=_run_operations_scenarios)\n        process.start()\n        process.join(timeout=90)\n        if process.is_alive():\n            process.terminate()\n            process.join(timeout=5)\n            self.fail(\"Operations integration scenarios timed out\")\n        self.assertEqual(process.exitcode, 0, f\"Operations scenarios exited with {process.exitcode}\")\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
    "test_operations_live.cjs": "const assert = require('node:assert/strict');\nconst fs = require('node:fs');\nconst vm = require('node:vm');\nconst { test } = require('node:test');\n\nconst source = fs.readFileSync('core/static/js/operations.js', 'utf8');\n\nfunction fixture({ empty = false } = {}) {\n    const connections = [];\n    const docEvents = new Map();\n    const windowEvents = new Map();\n    const fields = {\n        '[data-operation-status]': { textContent: 'Queued' },\n        '[data-operation-updated]': { textContent: 'old' },\n        '[data-operation-output]': { textContent: 'first sample' },\n        '[data-operation-result]': { hidden: false, open: true },\n    };\n    const card = { dataset: { operationId: '8' }, querySelector: name => fields[name] };\n    const indicator = { hidden: true, dataset: { connecting: 'connecting', live: 'live', reconnecting: 'retry', expired: 'expired' } };\n    const list = {\n        dataset: { statusStyles: JSON.stringify({ queued: 'gray', finished: 'green', failed: 'red' }) },\n        querySelectorAll: () => empty ? [] : [card],\n    };\n    class EventSource {\n        constructor(url) { this.url = url; this.events = new Map(); this.closed = false; connections.push(this); }\n        addEventListener(name, listener) { this.events.set(name, listener); }\n        close() { this.closed = true; }\n        emit(name, data) { this.events.get(name)?.({ data: typeof data === 'string' ? data : JSON.stringify(data) }); }\n    }\n    const document = { hidden: false, readyState: 'complete', querySelector: () => ({ querySelectorAll: () => [] }),\n        getElementById: id => id === 'operationsList' ? list : indicator,\n        addEventListener: (name, callback) => docEvents.set(name, callback) };\n    const window = { EventSource, addEventListener: (name, callback) => windowEvents.set(name, callback) };\n    runBrowserCode(source, {\n        window, document, AbortController, decryptData: value => value, decryptApiResponse: value => value.d ? JSON.parse(value.d) : value,\n    });\n    return { connections, fields, indicator, document, docEvents, windowEvents, window };\n}\n\nconst update = { id: 8, status: 'finished', status_label: 'Response received', updated_at: 'now', result: 'second sample' };\n\ntest('one connection updates the existing card and keeps expanded results open', () => {\n    const f = fixture();\n    assert.equal(f.connections.length, 1);\n    assert.equal(f.connections[0].url, '/api/operations/stream?ids=8');\n    f.connections[0].emit('operations', [update]);\n    f.connections[0].emit('operations', [{ ...update, result: 'third sample' }]);\n    assert.equal(f.connections.length, 1);\n    assert.equal(f.fields['[data-operation-output]'].textContent, 'third sample');\n    assert.equal(f.fields['[data-operation-result]'].open, true);\n    assert.equal(f.fields['[data-operation-status]'].textContent, 'Response received');\n    assert.match(f.fields['[data-operation-status]'].className, /green/);\n    assert.equal(f.fields['[data-operation-updated]'].textContent, 'now');\n});\n\ntest('server output is inserted as text and a first result becomes visible', () => {\n    const f = fixture();\n    f.fields['[data-operation-result]'].hidden = true;\n    const output = '<img src=x onerror=alert(1)>';\n    f.connections[0].emit('operations', [{ ...update, result: output }]);\n    assert.equal(f.fields['[data-operation-output]'].textContent, output);\n    assert.equal(f.fields['[data-operation-output]'].innerHTML, undefined);\n    assert.equal(f.fields['[data-operation-result]'].hidden, false);\n});\n\ntest('malformed events and updates for other cards are ignored', () => {\n    const f = fixture();\n    for (const data of ['not JSON', '{}', [null], [{ ...update, id: 9 }], [{ ...update, status: '__proto__' }]]) {\n        f.connections[0].emit('operations', data);\n    }\n    assert.equal(f.fields['[data-operation-output]'].textContent, 'first sample');\n});\n\ntest('hidden pages release the stream and restore only one connection when shown', () => {\n    const f = fixture();\n    f.document.hidden = true;\n    f.docEvents.get('visibilitychange')();\n    assert.equal(f.connections[0].closed, true);\n    f.document.hidden = false;\n    f.docEvents.get('visibilitychange')();\n    f.windowEvents.get('pageshow')();\n    assert.equal(f.connections.length, 2);\n    f.connections[0].emit('operations', [update]);\n    assert.equal(f.fields['[data-operation-output]'].textContent, 'first sample');\n    f.windowEvents.get('pagehide')();\n    assert.equal(f.connections[1].closed, true);\n});\n\ntest('network errors preserve the last result while EventSource reconnects', () => {\n    const f = fixture();\n    f.connections[0].emit('error');\n    assert.equal(f.indicator.textContent, 'retry');\n    assert.equal(f.fields['[data-operation-output]'].textContent, 'first sample');\n    assert.equal(f.connections.length, 1);\n    f.connections[0].emit('open');\n    assert.equal(f.indicator.textContent, 'live');\n});\n\ntest('expired permissions close the connection and prevent background reconnects', () => {\n    const f = fixture();\n    f.connections[0].emit('session_expired', {});\n    assert.equal(f.connections[0].closed, true);\n    f.windowEvents.get('pageshow')();\n    assert.equal(f.connections.length, 1);\n    assert.equal(f.indicator.textContent, 'expired');\n});\n\ntest('empty history does not open a stream', () => {\n    const f = fixture({ empty: true });\n    assert.equal(f.connections.length, 0);\n    assert.equal(f.indicator.hidden, true);\n});\n\ntest('encrypted envelopes are decoded and SPA teardown closes the stream', () => {\n    const f = fixture();\n    f.connections[0].emit('operations', { d: JSON.stringify([update]) });\n    assert.equal(f.fields['[data-operation-output]'].textContent, 'second sample');\n    f.window.destroyOperations();\n    assert.equal(f.connections[0].closed, true);\n});\n\nfunction createBrowserContext(globals) {\n    if (globals.window === globals) return vm.createContext(globals);\n    const browser = globals.window || {};\n    Object.assign(globals, browser);\n    for (const key of Object.keys(globals)) {\n        if (key === 'window') continue;\n        Object.defineProperty(browser, key, {\n            configurable: true,\n            get: () => globals[key],\n            set: value => { globals[key] = value; }\n        });\n    }\n    globals.window = new Proxy(browser, {\n        get: (target, key) => Reflect.has(target, key) ? Reflect.get(target, key) : Reflect.get(globals, key),\n        set: (target, key, value) => { globals[key] = value; Reflect.set(target, key, value); return true; }\n    });\n    return vm.createContext(globals);\n}\n\nfunction runBrowserCode(source, globals) { return vm.runInContext(source, createBrowserContext(globals)); }\n",
  "test_panel_bootstrap.cjs": "const assert = require('node:assert/strict');\nconst fs = require('node:fs');\nconst vm = require('node:vm');\nconst { test } = require('node:test');\n\nconst bootstrapSource = fs.readFileSync('core/static/js/panel_bootstrap.js', 'utf8');\n\ntest('applyPanelBootstrap parses JSON i18n from data attribute and populates window.I18N', () => {\n    const document = {\n        querySelector(sel) {\n            if (sel === 'main[data-panel-page]') {\n                return {\n                    dataset: {\n                        panelPage: 'nodes',\n                        panelKey: 'test-key',\n                        panelRole: 'owner',\n                        panelRoleLevel: '10',\n                        panelOwner: 'true',\n                        panelI18n: '{\"web_cpu\":\"ЦП\",\"web_ram\":\"ОЗУ\",\"web_disk\":\"Диск\",\"web_node_details\":\"Подробнее\"}',\n                        panelBilling: '{\"balance\": 100}',\n                        panelPingMode: 'http'\n                    },\n                    getAttribute(attr) {\n                        if (attr === 'data-panel-i18n') {\n                            return '{\"web_cpu\":\"ЦП\",\"web_ram\":\"ОЗУ\",\"web_disk\":\"Диск\",\"web_node_details\":\"Подробнее\"}';\n                        }\n                        if (attr === 'data-panel-billing') return '{\"balance\": 100}';\n                        return null;\n                    }\n                };\n            }\n            return null;\n        }\n    };\n\n    const ctx = vm.createContext({\n        document,\n        window: {},\n        Number,\n        JSON,\n        Object\n    });\n    ctx.window = ctx;\n\n    vm.runInContext(bootstrapSource, ctx);\n\n    assert.equal(ctx.window.I18N.web_cpu, 'ЦП');\n    assert.equal(ctx.window.I18N.web_ram, 'ОЗУ');\n    assert.equal(ctx.window.I18N.web_disk, 'Диск');\n    assert.equal(ctx.window.I18N.web_node_details, 'Подробнее');\n    assert.equal(ctx.window.WEB_KEY, 'test-key');\n    assert.equal(ctx.window.USER_ROLE, 'owner');\n    assert.equal(ctx.window.USER_ROLE_LEVEL, 10);\n    assert.equal(ctx.window.IS_MAIN_ADMIN, true);\n});\n\ntest('applyPanelBootstrap handles double-encoded JSON strings gracefully', () => {\n    const document = {\n        querySelector(sel) {\n            if (sel === 'main[data-panel-page]') {\n                return {\n                    dataset: {\n                        panelPage: 'nodes',\n                        panelI18n: JSON.stringify('{\"web_cpu\":\"ЦП\"}')\n                    },\n                    getAttribute(attr) {\n                        if (attr === 'data-panel-i18n') return JSON.stringify('{\"web_cpu\":\"ЦП\"}');\n                        return null;\n                    }\n                };\n            }\n            return null;\n        }\n    };\n\n    const ctx = vm.createContext({\n        document,\n        window: {},\n        Number,\n        JSON,\n        Object\n    });\n    ctx.window = ctx;\n\n    vm.runInContext(bootstrapSource, ctx);\n\n    assert.equal(ctx.window.I18N.web_cpu, 'ЦП');\n});\n",
    "test_panel_navigation.cjs": "const assert = require('node:assert/strict');\nconst fs = require('node:fs');\nconst vm = require('node:vm');\nconst { test } = require('node:test');\n\nconst source = fs.readFileSync('core/static/js/panel_navigation.js', 'utf8');\n\nfunction getPageKey(path) {\n    const clean = path.replace(/\\/+$/, '') || '/';\n    if (clean === '/') return 'dashboard';\n    if (clean === '/nodes') return 'nodes';\n    if (clean === '/operations') return 'operations';\n    if (clean === '/settings') return 'settings';\n    return 'unknown';\n}\n\nfunction createFixture({ initialPath = '/nodes', enableViewTransitions = false, navigationDelay = 0 } = {}) {\n    let assignedUrl = null;\n    let pushedUrl = null;\n    let fetchedUrl = null;\n    const docListeners = new Map();\n    const winListeners = new Map();\n    const actions = [];\n    const initKey = getPageKey(initialPath);\n\n    const document = {\n        readyState: 'complete',\n        title: initKey.charAt(0).toUpperCase() + initKey.slice(1),\n        documentElement: { lang: 'ru', dataset: {} },\n        body: {\n            className: initKey + '-page',\n            style: { overflow: '' },\n            appendChild(el) { actions.push('append:' + el.id); }\n        },\n        addEventListener(event, fn) {\n            docListeners.set(event, fn);\n        },\n        getElementById(id) {\n            if (['dashboardPageModals', 'nodesPageModals', 'settingsPageModals'].includes(id)) {\n                return { remove() { actions.push('remove:' + id); } };\n            }\n            return null;\n        },\n        querySelector(selector) {\n            if (selector === 'main') {\n                return {\n                    setAttribute(name, val) { actions.push(`main.set:${name}=${val}`); },\n                    removeAttribute(name) { actions.push(`main.remove:${name}`); },\n                    classList: {\n                        add(c) { actions.push('main.class.add:' + c); },\n                        remove(c) { actions.push('main.class.remove:' + c); }\n                    },\n                    replaceWith(newNode) { actions.push('main.replaceWith'); },\n                    style: {},\n                    offsetWidth: 100\n                };\n            }\n            if (selector === 'nav') {\n                return { replaceWith() { actions.push('nav.replaceWith'); } };\n            }\n            if (selector === 'main[data-panel-page]') {\n                return { dataset: { panelPage: initKey } };\n            }\n            return null;\n        },\n        importNode(node) { return node; }\n    };\n\n    if (enableViewTransitions) {\n        document.startViewTransition = fn => {\n            actions.push('startViewTransition:navigating=' + document.documentElement.dataset.panelNavigating);\n            fn();\n            return { finished: Promise.resolve() };\n        };\n    }\n\n    const window = {\n        location: {\n            href: 'http://localhost:8080' + initialPath,\n            pathname: initialPath,\n            origin: 'http://localhost:8080',\n            search: '',\n            assign(url) {\n                assignedUrl = url;\n            }\n        },\n        history: {\n            state: null,\n            pushState(state, title, url) {\n                pushedUrl = url;\n            },\n            replaceState(state, title, url) {}\n        },\n        addEventListener(event, fn) {\n            winListeners.set(event, fn);\n        },\n        scrollTo() {},\n        applyPanelBootstrap() { actions.push('applyPanelBootstrap'); },\n        initDashboard() { actions.push('initDashboard'); },\n        initNodesMonitor() { actions.push('initNodesMonitor'); },\n        initOperations() { actions.push('initOperations'); },\n        initSettings() { actions.push('initSettings'); },\n        destroyDashboard() { actions.push('destroyDashboard'); },\n        destroyNodesMonitor() { actions.push('destroyNodesMonitor'); },\n        destroyOperations() { actions.push('destroyOperations'); },\n        destroySettings() { actions.push('destroySettings'); },\n        fetch: async (url, options) => {\n            fetchedUrl = url;\n            const path = url.split('?')[0];\n            const targetPage = getPageKey(path);\n            const modalId = targetPage === 'dashboard' ? 'dashboardPageModals'\n                : (targetPage === 'nodes' ? 'nodesPageModals'\n                : (targetPage === 'settings' ? 'settingsPageModals' : null));\n            return {\n                ok: true,\n                url: 'http://localhost:8080' + url,\n                text: async () => `<!DOCTYPE html><html><head><title>${targetPage}</title></head><body>\n                    <nav></nav>\n                    <main data-panel-page=\"${targetPage}\"></main>\n                    ${modalId ? `<div id=\"${modalId}\"></div>` : ''}\n                </body></html>`\n            };\n        },\n        secureFetch: async (url, options) => {\n            fetchedUrl = url;\n            const path = url.split('?')[0];\n            const targetPage = getPageKey(path);\n            const modalId = targetPage === 'dashboard' ? 'dashboardPageModals'\n                : (targetPage === 'nodes' ? 'nodesPageModals'\n                : (targetPage === 'settings' ? 'settingsPageModals' : null));\n            return {\n                ok: true,\n                url: 'http://localhost:8080' + url,\n                text: async () => `<!DOCTYPE html><html><head><title>${targetPage}</title></head><body>\n                    <nav></nav>\n                    <main data-panel-page=\"${targetPage}\"></main>\n                    ${modalId ? `<div id=\"${modalId}\"></div>` : ''}\n                </body></html>`\n            };\n        },\n        DOMParser: class {\n            parseFromString(html) {\n                const match = html.match(/data-panel-page=\"([^\"]+)\"/);\n                const targetPage = match ? match[1] : 'unknown';\n                const modalId = targetPage === 'dashboard' ? 'dashboardPageModals'\n                    : (targetPage === 'nodes' ? 'nodesPageModals'\n                    : (targetPage === 'settings' ? 'settingsPageModals' : null));\n                return {\n                    title: targetPage.charAt(0).toUpperCase() + targetPage.slice(1),\n                    documentElement: { lang: 'ru', dataset: {} },\n                    body: { className: targetPage + '-page' },\n                    getElementById(id) {\n                        if (id === modalId) return { id: modalId, querySelectorAll: () => [] };\n                        return null;\n                    },\n                    querySelector(sel) {\n                        if (sel === 'main[data-panel-page]') {\n                            return {\n                                dataset: { panelPage: targetPage },\n                                querySelectorAll: () => []\n                            };\n                        }\n                        if (sel === 'nav') {\n                            return { querySelectorAll: () => [] };\n                        }\n                        return null;\n                    }\n                };\n            }\n        }\n    };\n\n    const context = {\n        console,\n        window,\n        document,\n        initNotifications: () => actions.push('initNotifications'),\n        renderHeaderBilling: () => actions.push('renderHeaderBilling'),\n        location: window.location,\n        fetch: window.fetch,\n        secureFetch: window.secureFetch,\n        DOMParser: window.DOMParser,\n        AbortController,\n        URL,\n        URLSearchParams,\n        setTimeout: (fn, delay, ...args) => setTimeout(fn, delay === 120 ? navigationDelay : delay, ...args),\n        clearTimeout\n    };\n\n    runBrowserCode(source, context);\n\n    return {\n        window,\n        document,\n        docListeners,\n        winListeners,\n        actions,\n        getAssignedUrl: () => assignedUrl,\n        getPushedUrl: () => pushedUrl,\n        getFetchedUrl: () => fetchedUrl\n    };\n}\n\ntest('navigation from /nodes to /operations runs SPA transition without page reload', async () => {\n    const f = createFixture({ initialPath: '/nodes' });\n    assert.equal(typeof f.window.operationNavigationHandles, 'function');\n    assert.equal(f.window.operationNavigationHandles('/operations'), true);\n\n    const clickListener = f.docListeners.get('click');\n    let defaultPrevented = false;\n    let propagationStopped = false;\n    clickListener({\n        target: { closest: sel => sel === 'a' ? { href: 'http://localhost:8080/operations', target: '_self', hasAttribute: () => false } : null },\n        button: 0,\n        preventDefault: () => { defaultPrevented = true; },\n        stopImmediatePropagation: () => { propagationStopped = true; }\n    });\n\n    await new Promise(r => setTimeout(r, 20));\n\n    assert.equal(defaultPrevented, true);\n    assert.equal(propagationStopped, true);\n    assert.equal(f.getAssignedUrl(), null, 'Should not trigger window.location.assign');\n    assert.equal(f.getFetchedUrl(), '/operations');\n    assert.equal(f.getPushedUrl(), '/operations');\n    assert.ok(f.actions.includes('destroyNodesMonitor'));\n    assert.ok(f.actions.includes('main.replaceWith'));\n    assert.ok(f.actions.includes('initOperations'));\n    assert.ok(f.actions.includes('main.class.add:panel-page-enter'));\n});\n\ntest('pagination and filters on /operations stay within SPA without full reload', async () => {\n    const f = createFixture({ initialPath: '/operations' });\n    assert.equal(f.window.operationNavigationHandles('/operations?page=2'), true);\n\n    const clickListener = f.docListeners.get('click');\n    clickListener({\n        target: { closest: sel => sel === 'a' ? { href: 'http://localhost:8080/operations?page=2&status=finished&junk=malicious', target: '_self', hasAttribute: () => false } : null },\n        button: 0,\n        preventDefault: () => {},\n        stopImmediatePropagation: () => {}\n    });\n\n    await new Promise(r => setTimeout(r, 20));\n\n    assert.equal(f.getAssignedUrl(), null, 'Pagination must not trigger full page reload');\n    assert.equal(f.getFetchedUrl(), '/operations?page=2&status=finished');\n    assert.equal(f.getPushedUrl(), '/operations?page=2&status=finished');\n    assert.ok(f.actions.includes('main.class.add:panel-page-enter'));\n});\n\ntest('navigation from /operations back to /nodes restores modals and monitor state', async () => {\n    const f = createFixture({ initialPath: '/operations' });\n    assert.equal(f.window.operationNavigationHandles('/nodes'), true);\n\n    const clickListener = f.docListeners.get('click');\n    clickListener({\n        target: { closest: sel => sel === 'a' ? { href: 'http://localhost:8080/nodes', target: '_self', hasAttribute: () => false } : null },\n        button: 0,\n        preventDefault: () => {},\n        stopImmediatePropagation: () => {}\n    });\n\n    await new Promise(r => setTimeout(r, 20));\n\n    assert.equal(f.getAssignedUrl(), null, 'Back to /nodes must not trigger reload');\n    assert.equal(f.getFetchedUrl(), '/nodes');\n    assert.equal(f.getPushedUrl(), '/nodes');\n    assert.ok(f.actions.includes('destroyOperations'));\n    assert.ok(f.actions.includes('append:nodesPageModals'));\n    assert.ok(f.actions.includes('initNodesMonitor'));\n});\n\ntest('navigation from /nodes to dashboard (/) and /settings works seamlessly across entire panel', async () => {\n    const f = createFixture({ initialPath: '/nodes' });\n    assert.equal(f.window.panelNavigationHandles('/'), true);\n    assert.equal(f.window.panelNavigationHandles('/settings'), true);\n\n    const clickListener = f.docListeners.get('click');\n    // Navigate to / (dashboard)\n    clickListener({\n        target: { closest: sel => sel === 'a' ? { href: 'http://localhost:8080/', target: '_self', hasAttribute: () => false } : null },\n        button: 0,\n        preventDefault: () => {},\n        stopImmediatePropagation: () => {}\n    });\n    await new Promise(r => setTimeout(r, 20));\n\n    assert.equal(f.getAssignedUrl(), null);\n    assert.equal(f.getFetchedUrl(), '/');\n    assert.equal(f.getPushedUrl(), '/');\n    assert.ok(f.actions.includes('destroyNodesMonitor'));\n    assert.ok(f.actions.includes('append:dashboardPageModals'));\n    assert.ok(f.actions.includes('initDashboard'));\n\n    // Now update location and navigate to /settings\n    f.window.location.pathname = '/';\n    f.window.location.href = 'http://localhost:8080/';\n\n    clickListener({\n        target: { closest: sel => sel === 'a' ? { href: 'http://localhost:8080/settings', target: '_self', hasAttribute: () => false } : null },\n        button: 0,\n        preventDefault: () => {},\n        stopImmediatePropagation: () => {}\n    });\n    await new Promise(r => setTimeout(r, 20));\n\n    assert.equal(f.getAssignedUrl(), null);\n    assert.equal(f.getFetchedUrl(), '/settings');\n    assert.equal(f.getPushedUrl(), '/settings');\n    assert.ok(f.actions.includes('destroyDashboard'));\n    assert.ok(f.actions.includes('append:settingsPageModals'));\n    assert.ok(f.actions.includes('initSettings'));\n});\n\ntest('view transitions API when available executes without double CSS animation jerk', async () => {\n    const f = createFixture({ initialPath: '/', enableViewTransitions: true });\n    const clickListener = f.docListeners.get('click');\n\n    clickListener({\n        target: { closest: sel => sel === 'a' ? { href: 'http://localhost:8080/settings', target: '_self', hasAttribute: () => false } : null },\n        button: 0,\n        preventDefault: () => {},\n        stopImmediatePropagation: () => {}\n    });\n    await new Promise(r => setTimeout(r, 20));\n\n    assert.ok(f.actions.includes('startViewTransition:navigating=true'), 'Should flag documentElement with data-panel-navigating during transition');\n    assert.equal(f.document.documentElement.dataset.panelNavigating, undefined, 'Should cleanup data-panel-navigating after transition');\n    assert.ok(f.actions.includes('initSettings'));\n    assert.equal(f.actions.includes('main.class.add:panel-page-enter'), false, 'Should not add panel-page-enter when View Transitions API handled transition');\n});\n\ntest('popstate history navigation preserves smooth SPA transitions', async () => {\n    const f = createFixture({ initialPath: '/operations' });\n    f.window.location.pathname = '/nodes';\n    f.window.location.href = 'http://localhost:8080/nodes';\n\n    const popListener = f.winListeners.get('popstate');\n    assert.equal(typeof popListener, 'function');\n    popListener({\n        state: { panelRoute: true },\n        stopImmediatePropagation: () => {}\n    });\n\n    await new Promise(r => setTimeout(r, 20));\n\n    assert.equal(f.getAssignedUrl(), null, 'Popstate must not reload the browser');\n    assert.equal(f.getFetchedUrl(), '/nodes');\n    assert.ok(f.actions.includes('initNodesMonitor'));\n});\n\ntest('perf-mode bypasses view transitions and suppresses animation classes', async () => {\n    const f = createFixture({ initialPath: '/nodes', enableViewTransitions: true });\n    f.document.documentElement.classList = {\n        contains(c) { return c === 'perf-mode'; }\n    };\n\n    const clickListener = f.docListeners.get('click');\n    assert.equal(typeof clickListener, 'function');\n\n    clickListener({\n        target: { closest: sel => sel === 'a' ? { href: 'http://localhost:8080/settings', target: '_self', hasAttribute: () => false } : null },\n        button: 0,\n        preventDefault: () => {},\n        stopImmediatePropagation: () => {}\n    });\n    await new Promise(r => setTimeout(r, 20));\n\n    assert.equal(f.actions.some(a => a.startsWith('startViewTransition')), false, 'Should skip startViewTransition in perf-mode');\n    assert.equal(f.actions.includes('main.class.add:panel-page-enter'), false, 'Should not add enter animation in perf-mode');\n    assert.ok(f.actions.includes('initSettings'));\n});\n\ntest('cancelNodeRename and node rename functions handle token and modal calls safely', () => {\n    const settingsCode = fs.readFileSync('core/static/js/settings.js', 'utf8');\n    const dashboardCode = fs.readFileSync('core/static/js/dashboard.js', 'utf8');\n\n    const sandbox = {\n        window: {},\n        document: {\n            getElementById(id) {\n                if (id === 'edit_name_token123') return { classList: { add() {}, remove() {} } };\n                if (id === 'nodeNameContainer' || id === 'nodeNameInputContainer') {\n                    return { classList: { add() {}, remove() {} } };\n                }\n                return null;\n            },\n            addEventListener() {}\n        },\n        localStorage: { getItem() { return null; }, setItem() {} },\n        location: { href: 'http://localhost/' },\n        addEventListener() {}\n    };\n    sandbox.window = sandbox;\n\n    // Run settings first then dashboard\n    runBrowserCode(settingsCode + '\\n' + dashboardCode, sandbox);\n\n    // Call without token (dashboard modal style)\n    assert.doesNotThrow(() => {\n        sandbox.cancelNodeRename();\n    });\n\n    // Call with token (settings style)\n    assert.doesNotThrow(() => {\n        sandbox.cancelNodeRename('token123');\n    });\n\n    // Call with undefined or null token when element does not exist\n    assert.doesNotThrow(() => {\n        sandbox.cancelNodeRename('non_existent_token');\n    });\n});\n\ntest('view transitions are skipped cleanly when document is hidden', async () => {\n    let startTransitionCalled = false;\n    const f = createFixture({ initialPath: '/settings' });\n    f.document.hidden = true;\n    f.document.startViewTransition = fn => {\n        startTransitionCalled = true;\n        fn();\n        return { finished: Promise.resolve() };\n    };\n\n    const clickListener = f.docListeners.get('click');\n    clickListener({\n        target: { closest: sel => sel === 'a' ? { href: 'http://localhost:8080/', target: '_self', hasAttribute: () => false } : null },\n        button: 0,\n        preventDefault: () => {},\n        stopImmediatePropagation: () => {}\n    });\n\n    await new Promise(r => setTimeout(r, 20));\n\n    assert.equal(startTransitionCalled, false, 'startViewTransition should not be called when document is hidden');\n    assert.ok(f.actions.includes('main.replaceWith'), 'DOM was still updated directly');\n});\n\ntest('settings navigation preserves only the allowed monitoring return route', async () => {\n    for (const [value, expected] of [\n        ['/nodes', '/settings?return_to=%2Fnodes'],\n        ['https://example.com', '/settings'],\n        ['//example.com', '/settings'],\n    ]) {\n        const f = createFixture({ initialPath: '/nodes' });\n        f.docListeners.get('click')({\n            target: { closest: () => ({\n                href: 'http://localhost:8080/settings?return_to=' + encodeURIComponent(value),\n                target: '_self', hasAttribute: () => false\n            }) },\n            button: 0,\n            preventDefault() {},\n            stopImmediatePropagation() {}\n        });\n        await new Promise(r => setTimeout(r, 20));\n        assert.equal(f.getFetchedUrl(), expected);\n        assert.equal(f.getPushedUrl(), expected);\n        assert.equal(f.getAssignedUrl(), null);\n        assert.ok(f.actions.includes('initSettings'));\n    }\n});\n\ntest('old content stays intact during a slow request and initialization runs inside the transition', async () => {\n    const f = createFixture();\n    const request = f.window.secureFetch;\n    let releaseRequest;\n    f.window.secureFetch = async (...args) => {\n        await new Promise(resolve => { releaseRequest = resolve; });\n        return request(...args);\n    };\n    let updateFrame, finish;\n    f.document.startViewTransition = callback => {\n        f.actions.push('capture-old-frame');\n        const updateCallbackDone = new Promise(resolve => {\n            updateFrame = () => { callback(); resolve(); };\n        });\n        return { updateCallbackDone, finished: new Promise(resolve => { finish = resolve; }) };\n    };\n    f.docListeners.get('click')({\n        target: { closest: () => ({ href: 'http://localhost:8080/settings', hasAttribute: () => false }) },\n        button: 0, preventDefault() {}, stopImmediatePropagation() {}\n    });\n    assert.equal(f.actions.includes('destroyNodesMonitor'), false);\n    assert.equal(f.actions.includes('main.replaceWith'), false);\n    await new Promise(resolve => setTimeout(resolve, 0));\n    releaseRequest();\n    await new Promise(resolve => setTimeout(resolve, 0));\n    assert.ok(f.actions.includes('capture-old-frame'));\n    assert.equal(f.actions.includes('destroyNodesMonitor'), false, 'Capture the populated charts before destroying them');\n    updateFrame();\n    assert.ok(f.actions.includes('initSettings'), 'Initialize before the browser captures the new frame');\n    await new Promise(resolve => setTimeout(resolve, 0));\n    assert.equal(f.document.documentElement.dataset.panelNavigating, 'true', 'Styles persist beyond DOM replacement');\n    finish();\n    await new Promise(resolve => setTimeout(resolve, 0));\n    assert.equal(f.document.documentElement.dataset.panelNavigating, undefined);\n    assert.equal(f.getAssignedUrl(), null);\n});\n\ntest('a superseded response cannot replace the newer page even if transport ignores abort', async () => {\n    const f = createFixture();\n    const request = f.window.secureFetch;\n    let releaseOld;\n    f.window.secureFetch = async (...args) => {\n        if (args[0] === '/settings') await new Promise(resolve => { releaseOld = resolve; });\n        return request(...args);\n    };\n    const click = href => f.docListeners.get('click')({\n        target: { closest: () => ({ href, hasAttribute: () => false }) },\n        button: 0, preventDefault() {}, stopImmediatePropagation() {}\n    });\n    click('http://localhost:8080/settings');\n    await new Promise(resolve => setTimeout(resolve, 0));\n    click('http://localhost:8080/operations');\n    await new Promise(resolve => setTimeout(resolve, 0));\n    releaseOld();\n    await new Promise(resolve => setTimeout(resolve, 0));\n    assert.equal(f.getPushedUrl(), '/operations');\n    assert.ok(f.actions.includes('initOperations'));\n    assert.equal(f.actions.includes('initSettings'), false);\n    assert.equal(f.getAssignedUrl(), null);\n});\n\ntest('reduced motion skips native and fallback page animations', async () => {\n    const f = createFixture({ enableViewTransitions: true });\n    f.window.matchMedia = () => ({ matches: true });\n    f.docListeners.get('click')({\n        target: { closest: () => ({ href: 'http://localhost:8080/settings', hasAttribute: () => false }) },\n        button: 0, preventDefault() {}, stopImmediatePropagation() {}\n    });\n    await new Promise(resolve => setTimeout(resolve, 0));\n    assert.equal(f.actions.some(action => action.startsWith('startViewTransition')), false);\n    assert.equal(f.actions.includes('main.class.add:panel-page-enter'), false);\n    assert.ok(f.actions.includes('initSettings'));\n});\n\ntest('a failed native transition still initializes the page and uses the CSS fallback', async () => {\n    const f = createFixture();\n    f.document.startViewTransition = () => { throw new Error('Snapshot unavailable'); };\n    f.docListeners.get('click')({\n        target: { closest: () => ({ href: 'http://localhost:8080/settings', hasAttribute: () => false }) },\n        button: 0, preventDefault() {}, stopImmediatePropagation() {}\n    });\n    await new Promise(resolve => setTimeout(resolve, 0));\n    assert.ok(f.actions.includes('initSettings'));\n    assert.ok(f.actions.includes('main.class.add:panel-page-enter'));\n    assert.equal(f.document.documentElement.dataset.panelNavigating, undefined);\n    assert.equal(f.getAssignedUrl(), null);\n});\n\ntest('gateway failures keep every current page visible and never trigger a document reload', async () => {\n    for (const path of ['/nodes', '/settings', '/operations', '/']) {\n        const f = createFixture({ initialPath: path });\n        const messages = [];\n        let attempts = 0;\n        f.window.showToast = message => messages.push(message);\n        f.window.secureFetch = async (url, options) => {\n            attempts++;\n            assert.equal(options.cache, 'no-store');\n            return { ok: false, status: 503 };\n        };\n        const target = path === '/settings' ? '/nodes' : '/settings';\n        f.docListeners.get('click')({\n            target: { closest: () => ({ href: 'http://localhost:8080' + target, hasAttribute: () => false }) },\n            button: 0, preventDefault() {}, stopImmediatePropagation() {}\n        });\n        await new Promise(resolve => setTimeout(resolve, 0));\n        assert.equal(attempts, 2);\n        assert.equal(messages.length, 1);\n        assert.equal(f.getAssignedUrl(), null);\n        assert.equal(f.getPushedUrl(), null);\n        assert.equal(f.actions.includes('main.replaceWith'), false);\n        assert.equal(f.actions.includes('destroyNodesMonitor'), false);\n        assert.ok(f.actions.includes('main.remove:aria-busy'));\n    }\n});\n\ntest('a transient 503 retries once and then completes normal navigation', async () => {\n    const f = createFixture();\n    const request = f.window.secureFetch;\n    let attempts = 0;\n    f.window.secureFetch = (...args) => ++attempts === 1\n        ? Promise.resolve({ status: 503, ok: false }) : request(...args);\n    f.docListeners.get('click')({\n        target: { closest: () => ({ href: 'http://localhost:8080/settings', hasAttribute: () => false }) },\n        button: 0, preventDefault() {}, stopImmediatePropagation() {}\n    });\n    await new Promise(resolve => setTimeout(resolve, 0));\n    assert.equal(attempts, 2);\n    assert.ok(f.actions.includes('initSettings'));\n    assert.equal(f.getAssignedUrl(), null);\n});\n\ntest('Retry-After prevents an immediate retry against an unavailable server', async () => {\n    const f = createFixture();\n    let attempts = 0;\n    f.window.secureFetch = async () => {\n        attempts++;\n        return { status: 503, ok: false, headers: { get: () => '30' } };\n    };\n    f.docListeners.get('click')({\n        target: { closest: () => ({ href: 'http://localhost:8080/settings', hasAttribute: () => false }) },\n        button: 0, preventDefault() {}, stopImmediatePropagation() {}\n    });\n    await new Promise(resolve => setTimeout(resolve, 0));\n    assert.equal(attempts, 1);\n    assert.equal(f.getAssignedUrl(), null);\n});\n\ntest('click bursts request only the final page and reuse an in-flight navigation', async () => {\n    const f = createFixture({ navigationDelay: 30 });\n    const request = f.window.secureFetch;\n    let calls = 0, release;\n    f.window.secureFetch = async (...args) => {\n        calls++;\n        await new Promise(resolve => { release = resolve; });\n        return request(...args);\n    };\n    const click = path => f.docListeners.get('click')({\n        target: { closest: () => ({ href: 'http://localhost:8080' + path, hasAttribute: () => false }) },\n        button: 0, preventDefault() {}, stopImmediatePropagation() {}\n    });\n    for (let i = 0; i < 50; i++) click(i % 2 ? '/settings' : '/operations');\n    assert.equal(calls, 0);\n    await new Promise(resolve => setTimeout(resolve, 45));\n    assert.equal(calls, 1);\n    for (let i = 0; i < 50; i++) click('/settings');\n    await new Promise(resolve => setTimeout(resolve, 45));\n    assert.equal(calls, 1, 'Do not abort or duplicate an identical pending navigation');\n    release();\n    await new Promise(resolve => setTimeout(resolve, 0));\n    assert.equal(f.getPushedUrl(), '/settings');\n    assert.equal(f.actions.filter(action => action === 'initSettings').length, 1);\n});\n\ntest('SPA dashboard to settings reinitializes header before settings-specific code', async () => {\n    const f = createFixture({initialPath: '/'});\n    const click = f.docListeners.get('click');\n    click({\n        target: {closest: sel => sel === 'a' ? {\n            href: 'http://localhost:8080/settings', target: '_self',\n            hasAttribute: () => false,\n        } : null},\n        button: 0,\n        preventDefault() {},\n        stopImmediatePropagation() {},\n    });\n    await new Promise(resolve => setTimeout(resolve, 30));\n    const {actions} = f;\n    assert.ok(actions.includes('nav.replaceWith'), 'SPA must replace navigation DOM');\n    assert.ok(actions.includes('initNotifications'), 'bell must be wired after header replacement');\n    assert.ok(actions.includes('renderHeaderBilling'), 'billing must be re-rendered on new header');\n    assert.ok(actions.indexOf('nav.replaceWith') < actions.indexOf('initNotifications'));\n    assert.ok(actions.indexOf('initNotifications') < actions.indexOf('initSettings'),\n        'route errors must not prevent the new bell from working');\n    assert.ok(actions.indexOf('renderHeaderBilling') < actions.indexOf('initSettings'),\n        'billing must not depend on settings page initialization');\n    assert.equal(f.getAssignedUrl(), null, 'no forced full-page reload');\n});\n\nfunction createBrowserContext(globals) {\n    if (globals.window === globals) return vm.createContext(globals);\n    const browser = globals.window || {};\n    Object.assign(globals, browser);\n    for (const key of Object.keys(globals)) {\n        if (key === 'window') continue;\n        Object.defineProperty(browser, key, {\n            configurable: true,\n            get: () => globals[key],\n            set: value => { globals[key] = value; }\n        });\n    }\n    globals.window = new Proxy(browser, {\n        get: (target, key) => Reflect.has(target, key) ? Reflect.get(target, key) : Reflect.get(globals, key),\n        set: (target, key, value) => { globals[key] = value; Reflect.set(target, key, value); return true; }\n    });\n    return vm.createContext(globals);\n}\n\nfunction runBrowserCode(source, globals) { return vm.runInContext(source, createBrowserContext(globals)); }\n",
    "test_ping_notifications_ui.cjs": "// Browser-independent smoke regressions for SPA notifications and ping target modal.\nconst test = require('node:test');\nconst assert = require('node:assert/strict');\nconst fs = require('node:fs');\nconst path = require('node:path');\nconst vm = require('node:vm');\n\nfunction source(name) {\n    return fs.readFileSync(path.join(__dirname, '..', 'core', 'static', 'js', name), 'utf8');\n}\nfunction section(text, start, end) {\n    const a = text.indexOf(start), b = text.indexOf(end, a + start.length);\n    assert.ok(a >= 0 && b > a, `Missing ${start}`);\n    return text.slice(a, b);\n}\n\ntest('target modal saves the selected target as system config without switching ping modes', async () => {\n    const code = section(source('settings.js'),\n        'window.savePingTargetModal = async function() {', '\\nwindow.destroySettings');\n    const calls = [];\n    const target = { value: 'google' };\n    const label = { textContent: '', title: '' };\n    const context = {\n        window: {\n            closePingTargetModal() { calls.push('close'); },\n            async saveSystemConfig(group) { calls.push(['save', group, target.value]); },\n        },\n        document: {\n            querySelector() { return { value: 'cloudflare' }; },\n            getElementById(id) { return id === 'conf_ping_target' ? target : label; },\n        },\n        checkForChanges(group) { calls.push(['changed', group]); },\n        I18N: {},\n    };\n    runBrowserCode(code, context);\n    await context.window.savePingTargetModal();\n    assert.equal(target.value, 'cloudflare');\n    assert.deepEqual(calls.map(String), ['close', 'changed,intervals', 'save,intervals,cloudflare']);\n    calls.length = 0;\n    await context.window.savePingTargetModal();\n    assert.deepEqual(calls, ['close'], 'unchanged target should not trigger another save');\n    assert.match(source('settings.js'), /ids: \\[[^\\]]*'conf_ping_target'/);\n});\n\ntest('SPA navigation restores notifications and delegated bell/clear clicks survive nav replacement', () => {\n    const text = source('common.js');\n    const init = section(text, 'function initNotifications() {', '\\nfunction handleSessionExpired');\n    let outsideListeners = 0;\n    let handler = null;\n    let draws = 0;\n    let bellClicks = 0;\n    let clearClicks = 0;\n    let closeClicks = 0;\n    const buttons = {notifBtn: {}, notifClearBtn: {}};\n    const context = {\n        window: {location: {pathname: '/'}},\n        document: {\n            getElementById(id) { return buttons[id] || null; },\n            addEventListener(event, fn) {\n                if (event === 'click') {\n                    outsideListeners++;\n                    handler = fn;\n                }\n            },\n        },\n        toggleNotifications() { bellClicks++; },\n        clearNotifications() { clearClicks++; },\n        closeNotifications() { closeClicks++; },\n        closeMobileSettings() {},\n        updateNotifUI(list, count) {\n            draws++;\n            assert.equal(list[0].text, 'Saved notification');\n            assert.equal(count, 1);\n        },\n        lastNotificationsJson: 'cached',\n        lastNotificationsList: [{text: 'Saved notification'}],\n        lastUnreadCount: 1,\n        notificationOutsideClickBound: false,\n    };\n    runBrowserCode(init, context);\n    context.initNotifications();\n\n    // The entire header (including the buttons) is replaced by SPA navigation.\n    buttons.notifBtn = {};\n    buttons.notifClearBtn = {};\n    context.window.location.pathname = '/settings';\n    context.initNotifications();\n    assert.equal(draws, 2);\n    assert.equal(outsideListeners, 1, 'only one delegated click handler for all headers');\n    assert.equal(context.lastNotificationsJson, '');\n\n    const click = (id) => handler({\n        target: { closest: selector => selector === '#' + id ? {} : null },\n        preventDefault() {}, stopPropagation() {},\n    });\n    click('notifBtn');\n    click('notifClearBtn');\n    click('outside');\n    assert.equal(bellClicks, 1, 'new SPA bell must open through delegation');\n    assert.equal(clearClicks, 1, 'new SPA clear button must run the handler');\n    assert.equal(closeClicks, 1, 'outside click must still close the dropdown');\n});\n\ntest('confirming Clear all sends POST, empties the list and shows a success toast', async () => {\n    const code = section(source('common.js'),\n        'let notificationClearInProgress = false;', '\\nwindow.clearNotifications = clearNotifications;');\n    const calls = [];\n    let resolveConfirm;\n    const button = {disabled: false, isConnected: true};\n    const context = {\n        document: {getElementById: id => id === 'notifClearBtn' ? button : null},\n        window: {\n            showModalConfirm: () => new Promise(resolve => { resolveConfirm = resolve; }),\n            showToast: message => calls.push(['toast', message]),\n        },\n        I18N: {web_clear_notif_confirm: 'Clear all?', web_notifications_cleared: 'Cleared', web_error_short: 'Error'},\n        fetch: async (url, opts) => {\n            calls.push(['fetch', url, opts.method]);\n            return {ok: true, json: async () => ({status: 'ok'})};\n        },\n        updateNotifUI: (notifications, count) => calls.push(['render', notifications.length, count]),\n        console,\n    };\n    runBrowserCode(code, context);\n    const event = {preventDefault() {}, stopPropagation() {}};\n    const pending = context.clearNotifications(event);\n    await Promise.resolve();\n    assert.equal(button.disabled, true);\n    assert.equal(calls.length, 0, 'no API call before confirmation');\n    resolveConfirm(true);\n    await pending;\n    assert.equal(button.disabled, false);\n    assert.deepEqual(JSON.parse(JSON.stringify(calls)), [\n        ['fetch', '/api/notifications/clear', 'POST'], ['render', 0, 0], ['toast', 'Cleared'],\n    ]);\n});\n\ntest('Clear all reports rejected requests and preserves the visible list', async () => {\n    const code = section(source('common.js'),\n        'let notificationClearInProgress = false;', '\\nwindow.clearNotifications = clearNotifications;');\n    const calls = [];\n    const button = {disabled: false, isConnected: true};\n    const context = {\n        document: {getElementById: () => button},\n        window: {\n            showModalConfirm: async () => true,\n            showToast: message => calls.push(['toast', message]),\n        },\n        I18N: {web_error_short: 'Error'},\n        fetch: async () => ({ok: false, status: 403, json: async () => ({error: 'Invalid CSRF token'})}),\n        updateNotifUI: () => calls.push(['render']),\n        console: {error() {}},\n    };\n    runBrowserCode(code, context);\n    await context.clearNotifications();\n    assert.deepEqual(JSON.parse(JSON.stringify(calls)), [['toast', 'Error: Invalid CSRF token']]);\n    assert.equal(button.disabled, false);\n});\n\ntest('cancelling notification clear does not call API or show a toast', async () => {\n    const code = section(source('common.js'),\n        'let notificationClearInProgress = false;', '\\nwindow.clearNotifications = clearNotifications;');\n    let calls = 0;\n    const button = {disabled: false, isConnected: true};\n    const context = {\n        document: {getElementById: () => button},\n        window: {showModalConfirm: async () => false, showToast: () => calls++},\n        I18N: {},\n        fetch: () => { calls++; },\n        updateNotifUI: () => { calls++; },\n        console,\n    };\n    runBrowserCode(code, context);\n    await context.clearNotifications();\n    assert.equal(calls, 0);\n    assert.equal(button.disabled, false);\n});\n\ntest('expired CSRF refreshes session token and retries notification clear once', async () => {\n    const code = section(source('common.js'),\n        'let notificationClearInProgress = false;', '\\nwindow.clearNotifications = clearNotifications;');\n    const calls = [];\n    const button = {disabled: false, isConnected: true};\n    let attempts = 0;\n    const context = {\n        document: {getElementById: () => button},\n        window: {showModalConfirm: async () => true, showToast: message => calls.push(['toast', message])},\n        I18N: {web_notifications_cleared: 'Cleared'},\n        fetch: async (url, options) => {\n            calls.push(['fetch', url]);\n            if (url === '/api/auth/status') return {ok: true};\n            attempts++;\n            if (attempts === 1) {\n                return {ok: false, status: 403, json: async () => ({error: 'Invalid CSRF token'})};\n            }\n            return {ok: true, json: async () => ({status: 'ok'})};\n        },\n        updateNotifUI: (list, count) => calls.push(['render', list.length, count]),\n        console,\n    };\n    runBrowserCode(code, context);\n    await context.clearNotifications();\n    assert.equal(attempts, 2);\n    assert.deepEqual(JSON.parse(JSON.stringify(calls)), [\n        ['fetch', '/api/notifications/clear'],\n        ['fetch', '/api/auth/status'],\n        ['fetch', '/api/notifications/clear'],\n        ['render', 0, 0], ['toast', 'Cleared'],\n    ]);\n});\n\ntest('permission errors are never retried as CSRF refreshes', async () => {\n    const code = section(source('common.js'),\n        'let notificationClearInProgress = false;', '\\nwindow.clearNotifications = clearNotifications;');\n    const calls = [];\n    const context = {\n        document: {getElementById: () => ({disabled: false, isConnected: true})},\n        window: {showModalConfirm: async () => true, showToast: message => calls.push(message)},\n        I18N: {web_error_short: 'Error'},\n        fetch: async (url) => {\n            calls.push(url);\n            return {ok: false, status: 403, json: async () => ({error: 'Forbidden'})};\n        },\n        updateNotifUI: () => { throw new Error('Must not render success'); },\n        console: {error() {}},\n    };\n    runBrowserCode(code, context);\n    await context.clearNotifications();\n    assert.deepEqual(calls, ['/api/notifications/clear', 'Error: Forbidden']);\n});\n\ntest('modal OK releases pending notification clear even if closing animation throws', async () => {\n    const common = source('common.js');\n    const modalCode = section(common, 'let sysModalResolve = null;', '\\nfunction _showSystemModalBase(');\n    const clearCode = section(common, 'let notificationClearInProgress = false;', '\\nwindow.clearNotifications = clearNotifications;');\n    const calls = [];\n    const button = {disabled: false, isConnected: true};\n    const modal = {classList: {add() {}, remove() {}}};\n    const context = {\n        document: {getElementById: id => id === 'systemModal' ? modal : button},\n        window: {showToast: msg => calls.push(['toast', msg])},\n        I18N: {web_notifications_cleared: 'Cleared'},\n        fetch: async url => {\n            calls.push(['fetch', url]);\n            return {ok: true, json: async () => ({status: 'ok'})};\n        },\n        updateNotifUI: (list, count) => calls.push(['render', list.length, count]),\n        animateModalClose: () => { throw new Error('Animation failed'); },\n        console: {error() {}},\n    };\n    runBrowserCode(modalCode + '\\n' + clearCode + `\n        window.showModalConfirm = () => new Promise(resolve => { sysModalResolve = resolve; });\n    `, context);\n    const pending = context.clearNotifications();\n    assert.equal(button.disabled, true);\n    assert.equal(calls.length, 0);\n    context.closeSystemModal(true);\n    await pending;\n    assert.deepEqual(JSON.parse(JSON.stringify(calls)), [\n        ['fetch', '/api/notifications/clear'], ['render', 0, 0], ['toast', 'Cleared'],\n    ]);\n    assert.equal(button.disabled, false);\n});\n\ntest('node-monitor bundle must not hijack shared confirmation before notification POST', async () => {\n    const common = source('common.js');\n    const nodes = source('nodes_monitor.js');\n    const modalCode = section(common, 'let sysModalResolve = null;', '\\nwindow.animateModalOpen = animateModalOpen;');\n    const clearCode = section(common, 'let notificationClearInProgress = false;', '\\nwindow.clearNotifications = clearNotifications;');\n    const nodeModalCode = section(nodes, '// Modal functions', '// Theme toggle (if not defined in common.js)');\n    const nodeExports = section(nodes, 'window.showAlert = showAlert;', '\\n})();');\n\n    assert.doesNotMatch(nodes, /window\\.closeSystemModal\\s*=/,\n        'nodes_monitor.js must not replace the global promise-resolving closeSystemModal');\n\n    const classList = {add() {}, remove() {}, toggle() {}};\n    const elements = new Map([\n        ['systemModal', {classList}],\n        ['sysModalTitle', {innerText: ''}],\n        ['sysModalMessage', {replaceChildren() {}}],\n        ['sysModalInput', {classList}],\n        ['sysModalCancel', {classList}],\n        ['sysModalOk', {innerText: ''}],\n        ['notifClearBtn', {disabled: false, isConnected: true}],\n    ]);\n    const calls = [];\n    const context = {\n        window: {showToast: message => calls.push(['toast', message])},\n        document: {\n            getElementById: id => elements.get(id) || null,\n            createTextNode: text => text,\n            createElement: tag => ({tag}),\n        },\n        I18N: {web_notifications_cleared: 'Cleared'},\n        animateModalOpen() {},\n        animateModalClose() {},\n        updateNotifUI: (list, count) => calls.push(['render', list.length, count]),\n        fetch: async (url, options) => {\n            calls.push(['fetch', url, options.method]);\n            return {ok: true, json: async () => ({status: 'ok'})};\n        },\n        console,\n    };\n    runBrowserCode(modalCode + '\\n' + clearCode, context);\n    const sharedClose = context.window.closeSystemModal;\n\n    // Execute the node module's actual private modal functions and its actual exports\n    // as if its bundle loaded after common.js on any SPA-enabled page.\n    runBrowserCode('(() => {\\nfunction resolveLocalizedMessage(m) { return m; }\\n'\n        + nodeModalCode + '\\n' + nodeExports + '\\n})();', context);\n    assert.equal(context.window.closeSystemModal, sharedClose);\n\n    const pending = context.clearNotifications();\n    await Promise.resolve();\n    assert.equal(calls.length, 0);\n    elements.get('sysModalOk').onclick();\n    await pending;\n    assert.deepEqual(JSON.parse(JSON.stringify(calls)), [\n        ['fetch', '/api/notifications/clear', 'POST'],\n        ['render', 0, 0],\n        ['toast', 'Cleared'],\n    ]);\n});\n\ntest('SPA settings bootstrap restores inline-only globals and renders billing on the replaced nav', () => {\n    const tpl = fs.readFileSync(path.join(__dirname, '..', 'core', 'templates', 'settings.html'), 'utf8');\n    const dash = fs.readFileSync(path.join(__dirname, '..', 'core', 'templates', 'dashboard.html'), 'utf8');\n    for (const key of ['billing', 'users', 'nodes', 'keyboard', 'user-alerts', 'has-active-nodes']) {\n        assert.match(tpl, new RegExp('data-panel-' + key + '='));\n    }\n    assert.match(dash, /data-panel-config=/);\n    assert.match(tpl, /window\\.USERS_DATA =/);\n    assert.match(tpl, /window\\.KEYBOARD_CONFIG =/);\n\n    let attrs = {\n        'data-panel-i18n': JSON.stringify({web_billing_modal_title: 'Billing'}),\n        'data-panel-billing': JSON.stringify({amount: 42, currency: 'EUR'}),\n        'data-panel-users': JSON.stringify([{id: 1}]),\n        'data-panel-nodes': JSON.stringify([{id: 7}]),\n        'data-panel-keyboard': JSON.stringify({btn_start: true}),\n        'data-panel-user-alerts': JSON.stringify({downtime: true}),\n    };\n    const page = {\n        dataset: {panelPage: 'settings', panelRole: 'admins', panelRoleLevel: '9',\n            panelOwner: 'true', panelHasActiveNodes: 'true'},\n        getAttribute: key => Object.hasOwn(attrs, key) ? attrs[key] : null,\n    };\n    let rendered = null;\n    const button = {};\n    const container = {\n        textContent: '',\n        appendChild(fragment) { rendered = fragment.html; },\n        querySelector: () => button,\n    };\n    const ctx = {\n        document: {\n            querySelector: () => page,\n            getElementById: id => id === 'headerBillingContainer' ? container : null,\n        },\n        DOMPurify: {sanitize: html => ({html})},\n        getBillingStatusColor: () => 'normal',\n        getBillingBadgeHtml: () => '42 EUR',\n        calculateDaysLeft: () => null,\n        showBillingModal() {},\n    };\n    ctx.window = ctx;\n    runBrowserCode(source('panel_bootstrap.js'), ctx);\n    assert.equal(ctx.USERS_DATA[0].id, 1);\n    assert.equal(ctx.NODES_DATA[0].id, 7);\n    assert.equal(ctx.KEYBOARD_CONFIG.btn_start, true);\n    assert.equal(ctx.USER_ALERTS.downtime, true);\n    assert.equal(ctx.HAS_ACTIVE_NODES, true);\n    assert.equal(runBrowserCode('USERS_DATA[0].id + NODES_DATA[0].id', ctx), 8,\n        'settings functions must resolve restored globals without executing inline scripts');\n\n    const billingCode = section(source('common.js'),\n        'window.renderHeaderBilling = function() {', \"\\ndocument.addEventListener('DOMContentLoaded', () => {\");\n    runBrowserCode(billingCode, ctx);\n    ctx.renderHeaderBilling();\n    assert.match(rendered, /header-billing-btn/);\n    assert.equal(typeof button.onclick, 'function');\n\n    // Navigation back to the dashboard refreshes its own config, too.\n    page.dataset.panelPage = 'dashboard';\n    attrs = {\n        'data-panel-i18n': '{}',\n        'data-panel-billing': JSON.stringify({amount: 11}),\n        'data-panel-config': JSON.stringify({cpu_threshold: 90}),\n    };\n    ctx.applyPanelBootstrap();\n    assert.equal(ctx.SYS_CONFIG.cpu_threshold, 90);\n    assert.equal(ctx.master_billing_json.amount, 11);\n});\n\nfunction createBrowserContext(globals) {\n    if (globals.window === globals) return vm.createContext(globals);\n    const browser = globals.window || {};\n    Object.assign(globals, browser);\n    for (const key of Object.keys(globals)) {\n        if (key === 'window') continue;\n        Object.defineProperty(browser, key, {\n            configurable: true,\n            get: () => globals[key],\n            set: value => { globals[key] = value; }\n        });\n    }\n    globals.window = new Proxy(browser, {\n        get: (target, key) => Reflect.has(target, key) ? Reflect.get(target, key) : Reflect.get(globals, key),\n        set: (target, key, value) => { globals[key] = value; Reflect.set(target, key, value); return true; }\n    });\n    return vm.createContext(globals);\n}\n\nfunction runBrowserCode(source, globals) { return vm.runInContext(source, createBrowserContext(globals)); }\n",
  "test_service_worker.cjs": "const assert = require('node:assert/strict');\nconst fs = require('node:fs');\nconst vm = require('node:vm');\nconst { test } = require('node:test');\n\nconst source = fs.readFileSync('core/static/js/sw.js', 'utf8');\nconst origin = 'https://panel.example';\n\nfunction fixture({ network, cached, cacheError = false } = {}) {\n    const handlers = new Map();\n    const calls = { fetch: 0, cache: 0 };\n    vm.runInNewContext(source, {\n        self: {\n            location: { origin },\n            addEventListener: (name, handler) => handlers.set(name, handler),\n        },\n        URL, Response,\n        console: { debug() {} },\n        fetch: async (request) => {\n            calls.fetch++;\n            if (network) return network(request);\n            throw new TypeError('Network unavailable');\n        },\n        caches: {\n            open: async (name) => {\n                calls.cache++;\n                assert.equal(name, 'tgbotvpscp-v1');\n                if (cacheError) throw new Error('Cache unavailable');\n                return { match: async () => cached };\n            },\n        },\n    });\n    return {\n        calls,\n        fetch(url, method = 'GET') {\n            let response;\n            handlers.get('fetch')({\n                request: { url: new URL(url, origin).href, method },\n                respondWith(value) { response = value; },\n            });\n            return response;\n        },\n    };\n}\n\ntest('authenticated pages and API requests bypass the service worker, including operation filters', () => {\n    const worker = fixture();\n    for (const url of ['/', '/operations', '/operations?node_id=0&status=', '/operations?node_id=3&status=failed',\n        '/nodes', '/settings', '/login', '/logout', '/terminal', '/api/operations', '/stream/events']) {\n        assert.equal(worker.fetch(url), undefined, url);\n    }\n    assert.deepEqual(worker.calls, { fetch: 0, cache: 0 });\n});\n\ntest('external assets and non-GET requests are not intercepted', () => {\n    const worker = fixture();\n    assert.equal(worker.fetch('https://external.example/static/script.js'), undefined);\n    assert.equal(worker.fetch('/static/test.js', 'POST'), undefined);\n    assert.deepEqual(worker.calls, { fetch: 0, cache: 0 });\n});\n\ntest('successful asset and manifest responses pass through without touching the cache', async () => {\n    const response = new Response('asset');\n    const worker = fixture({ network: () => response });\n    for (const url of ['/static/css/main.css?v=123', '/site.webmanifest']) {\n        assert.equal(await worker.fetch(url), response);\n    }\n    assert.deepEqual(worker.calls, { fetch: 2, cache: 0 });\n});\n\ntest('network failure falls back to an existing public asset response', async () => {\n    const cached = new Response('cached styles');\n    const worker = fixture({ cached });\n    assert.equal(await worker.fetch('/static/css/main.css'), cached);\n});\n\ntest('network failure with no cache returns a Response instead of undefined', async () => {\n    const worker = fixture();\n    const response = await worker.fetch('/static/js/missing.js');\n    assert.ok(response instanceof Response);\n    assert.equal(response.type, 'error');\n});\n\ntest('unavailable cache also returns a Response instead of rejecting respondWith', async () => {\n    const worker = fixture({ cacheError: true });\n    const response = await worker.fetch('/static/css/main.css');\n    assert.ok(response instanceof Response);\n    assert.equal(response.type, 'error');\n});\n\ntest('HTTP errors remain visible and are not replaced by stale cached assets', async () => {\n    const response = new Response('Server error', { status: 503 });\n    const worker = fixture({ network: () => response, cached: new Response('old asset') });\n    assert.equal(await worker.fetch('/static/test.js'), response);\n    assert.equal(worker.calls.cache, 0);\n});\n",
  "test_telegram_auth.py": "import base64\nimport json\nimport os\nimport time\nimport unittest\nfrom unittest.mock import MagicMock, patch\n\nfrom cryptography.fernet import Fernet\nfrom cryptography.hazmat.primitives import hashes\nfrom cryptography.hazmat.primitives.asymmetric import ec, padding, rsa, utils as crypto_utils\n\nfrom tests.support import CORE_DEPENDENCIES, mock_optional_modules\n\nos.environ.setdefault(\"DATA_ENCRYPTION_KEY\", Fernet.generate_key().decode())\nos.environ.setdefault(\"TG_BOT_TOKEN\", \"123456789:TEST_BOT_TOKEN\")\nos.environ.setdefault(\"TG_ADMIN_ID\", \"12345\")\n\nmock_optional_modules((*CORE_DEPENDENCIES, \"psutil\", \"aiogram\", \"aiogram.types\", \"aiogram.exceptions\"))\n\nfrom core.web.auth import verify_telegram_id_token\n\n\ndef _b64url_encode(data: bytes) -> str:\n    return base64.urlsafe_b64encode(data).decode(\"ascii\").rstrip(\"=\")\n\n\ndef _int_to_b64(val: int) -> str:\n    length = (val.bit_length() + 7) // 8\n    return _b64url_encode(val.to_bytes(length, \"big\"))\n\n\nclass TelegramAuthTests(unittest.IsolatedAsyncioTestCase):\n    def test_magic_link_session_uses_fallback_name_and_avatar(self):\n        from core.web import auth\n        request = MagicMock()\n        request.cookies = {auth.COOKIE_NAME: \"magic-session\"}\n        with patch.dict(auth.SERVER_SESSIONS, {\"magic-session\": {\"id\": 12345, \"expires\": time.time() + 60, \"photo_url\": None}}, clear=True), patch.dict(auth.ALLOWED_USERS, {12345: \"admins\"}, clear=True), patch.dict(auth.USER_NAMES, {\"12345\": None}, clear=True):\n            user = auth.get_current_user(request)\n        self.assertEqual(user[\"first_name\"], \"ID: 12345\")\n        self.assertEqual(user[\"photo_url\"], auth.AGENT_FLAG)\n\n    def test_public_login_urls_omit_only_the_default_https_port(self):\n        from core.web import auth\n        for configured, expected in (\n            (\"https://panel.example:443/\", \"https://panel.example\"),\n            (\"https://panel.example/\", \"https://panel.example\"),\n            (\"https://panel.example:8443/\", \"https://panel.example:8443\"),\n            (\"https://[::1]:443/\", \"https://[::1]\"),\n            (\"https://[::1]:8443/\", \"https://[::1]:8443\"),\n            (\"https://user:password@panel.example:443\", None),\n            (\"https://panel.example:invalid\", None),\n        ):\n            with self.subTest(configured=configured), patch.object(auth, \"WEB_PUBLIC_URL\", configured):\n                self.assertEqual(auth._get_public_base_url(), expected)\n\n    def test_missing_avatar_never_renders_none_as_text(self):\n        from core.web.avatar import get_avatar_html\n        for user in ({}, {\"photo_url\": None}, {\"photo_url\": \"\"}):\n            avatar = get_avatar_html(user)\n            self.assertNotIn(\"None\", avatar)\n            self.assertIn(\"🏳️\", avatar)\n\n    @classmethod\n    def setUpClass(cls):\n        # Generate RSA test key pair\n        cls.rsa_private_key = rsa.generate_private_key(\n            public_exponent=65537,\n            key_size=2048,\n        )\n        cls.rsa_pub_numbers = cls.rsa_private_key.public_key().public_numbers()\n        cls.rsa_jwk = {\n            \"kid\": \"test-rsa-1\",\n            \"kty\": \"RSA\",\n            \"alg\": \"RS256\",\n            \"n\": _int_to_b64(cls.rsa_pub_numbers.n),\n            \"e\": _int_to_b64(cls.rsa_pub_numbers.e),\n        }\n\n        # Generate EC test key pair (P-256)\n        cls.ec_private_key = ec.generate_private_key(ec.SECP256R1())\n        cls.ec_pub_numbers = cls.ec_private_key.public_key().public_numbers()\n        cls.ec_jwk = {\n            \"kid\": \"test-es-1\",\n            \"kty\": \"EC\",\n            \"alg\": \"ES256\",\n            \"crv\": \"P-256\",\n            \"x\": _int_to_b64(cls.ec_pub_numbers.x),\n            \"y\": _int_to_b64(cls.ec_pub_numbers.y),\n        }\n\n        cls.mock_jwks = {\n            \"test-rsa-1\": cls.rsa_jwk,\n            \"test-es-1\": cls.ec_jwk,\n        }\n\n    def _create_rsa_token(self, claims: dict, kid: str = \"test-rsa-1\") -> str:\n        header = {\"alg\": \"RS256\", \"kid\": kid}\n        hdr_b64 = _b64url_encode(json.dumps(header).encode(\"utf-8\"))\n        pay_b64 = _b64url_encode(json.dumps(claims).encode(\"utf-8\"))\n        signing_input = f\"{hdr_b64}.{pay_b64}\".encode(\"ascii\")\n        sig = self.rsa_private_key.sign(\n            signing_input,\n            padding.PKCS1v15(),\n            hashes.SHA256(),\n        )\n        return f\"{hdr_b64}.{pay_b64}.{_b64url_encode(sig)}\"\n\n    def _create_ec_token(self, claims: dict, kid: str = \"test-es-1\") -> str:\n        header = {\"alg\": \"ES256\", \"kid\": kid}\n        hdr_b64 = _b64url_encode(json.dumps(header).encode(\"utf-8\"))\n        pay_b64 = _b64url_encode(json.dumps(claims).encode(\"utf-8\"))\n        signing_input = f\"{hdr_b64}.{pay_b64}\".encode(\"ascii\")\n        der_sig = self.ec_private_key.sign(\n            signing_input,\n            ec.ECDSA(hashes.SHA256()),\n        )\n        r, s = crypto_utils.decode_dss_signature(der_sig)\n        raw_sig = r.to_bytes(32, \"big\") + s.to_bytes(32, \"big\")\n        return f\"{hdr_b64}.{pay_b64}.{_b64url_encode(raw_sig)}\"\n\n    async def test_valid_rsa_token(self):\n        claims = {\n            \"iss\": \"https://oauth.telegram.org\",\n            \"aud\": \"123456789\",\n            \"id\": 987654321,\n            \"name\": \"Test User\",\n            \"preferred_username\": \"testuser\",\n            \"exp\": int(time.time()) + 3600,\n            \"iat\": int(time.time()),\n        }\n        token = self._create_rsa_token(claims)\n        with patch(\"core.web.auth.fetch_telegram_jwks\", return_value=self.mock_jwks):\n            result = await verify_telegram_id_token(token, expected_client_id=\"123456789\")\n            self.assertIsNotNone(result)\n            self.assertEqual(result[\"id\"], 987654321)\n            self.assertEqual(result[\"preferred_username\"], \"testuser\")\n\n    async def test_valid_es256_token(self):\n        claims = {\n            \"iss\": \"https://oauth.telegram.org\",\n            \"aud\": \"123456789\",\n            \"id\": 987654321,\n            \"name\": \"Test User\",\n            \"exp\": int(time.time()) + 3600,\n            \"iat\": int(time.time()),\n        }\n        token = self._create_ec_token(claims)\n        with patch(\"core.web.auth.fetch_telegram_jwks\", return_value=self.mock_jwks):\n            result = await verify_telegram_id_token(token, expected_client_id=\"123456789\")\n            self.assertIsNotNone(result)\n            self.assertEqual(result[\"id\"], 987654321)\n\n    async def test_expired_token_rejected(self):\n        claims = {\n            \"iss\": \"https://oauth.telegram.org\",\n            \"aud\": \"123456789\",\n            \"id\": 987654321,\n            \"exp\": int(time.time()) - 300,\n            \"iat\": int(time.time()) - 600,\n        }\n        token = self._create_rsa_token(claims)\n        with patch(\"core.web.auth.fetch_telegram_jwks\", return_value=self.mock_jwks):\n            result = await verify_telegram_id_token(token, expected_client_id=\"123456789\")\n            self.assertIsNone(result)\n\n    async def test_wrong_issuer_rejected(self):\n        claims = {\n            \"iss\": \"https://evil.oauth.example.com\",\n            \"aud\": \"123456789\",\n            \"id\": 987654321,\n            \"exp\": int(time.time()) + 3600,\n            \"iat\": int(time.time()),\n        }\n        token = self._create_rsa_token(claims)\n        with patch(\"core.web.auth.fetch_telegram_jwks\", return_value=self.mock_jwks):\n            result = await verify_telegram_id_token(token, expected_client_id=\"123456789\")\n            self.assertIsNone(result)\n\n    async def test_wrong_audience_rejected(self):\n        claims = {\n            \"iss\": \"https://oauth.telegram.org\",\n            \"aud\": \"999999999\",\n            \"id\": 987654321,\n            \"exp\": int(time.time()) + 3600,\n            \"iat\": int(time.time()),\n        }\n        token = self._create_rsa_token(claims)\n        with patch(\"core.web.auth.fetch_telegram_jwks\", return_value=self.mock_jwks):\n            result = await verify_telegram_id_token(token, expected_client_id=\"123456789\")\n            self.assertIsNone(result)\n\n    async def test_tampered_payload_rejected(self):\n        claims = {\n            \"iss\": \"https://oauth.telegram.org\",\n            \"aud\": \"123456789\",\n            \"id\": 987654321,\n            \"exp\": int(time.time()) + 3600,\n            \"iat\": int(time.time()),\n        }\n        token = self._create_rsa_token(claims)\n        parts = token.split(\".\")\n        # Tamper payload\n        tampered_claims = dict(claims, id=111111111)\n        tampered_payload = _b64url_encode(json.dumps(tampered_claims).encode(\"utf-8\"))\n        tampered_token = f\"{parts[0]}.{tampered_payload}.{parts[2]}\"\n\n        with patch(\"core.web.auth.fetch_telegram_jwks\", return_value=self.mock_jwks):\n            result = await verify_telegram_id_token(tampered_token, expected_client_id=\"123456789\")\n            self.assertIsNone(result)\n\n    def test_login_template_hides_id_link_in_telegram_only_mode(self):\n        try:\n            from jinja2 import Environment, FileSystemLoader, select_autoescape\n        except ImportError:\n            with open(\"core/templates/login.html\", \"r\", encoding=\"utf-8\") as f:\n                content = f.read()\n            self.assertIn(\"{% if telegram_only_mode %}hidden{% endif %}\", content)\n            self.assertIn(\"TELEGRAM_ONLY_MODE = {{ 'true' if telegram_only_mode else 'false' }};\", content)\n            return\n\n        env = Environment(\n            loader=FileSystemLoader(\"core/templates\"),\n            autoescape=select_autoescape([\"html\", \"xml\"]),\n        )\n        template = env.get_template(\"login.html\")\n\n        # When telegram_only_mode is True:\n        rendered_true = template.render(\n            current_lang=\"ru\",\n            web_title=\"Title\",\n            cache_ver=\"1\",\n            pwa_version=\"1\",\n            asset_ver=\"1\",\n            i18n_json=\"{}\",\n            bot_username=\"testbot\",\n            tg_client_id=\"123456789\",\n            telegram_only_mode=True,\n            web_key_js=\"\",\n            web_toggle_perf_mode=\"\",\n            web_toggle_a11y_mode=\"\",\n            login_via_telegram_btn=\"Telegram\",\n            login_or_id_link=\"Или войти по ID (Magic Link)\",\n            login_telegram_id_label=\"ID\",\n            login_or_tg_button=\"\",\n            web_brand_name=\"Brand\",\n            is_default_pass=False,\n            web_default_pass_alert=\"\",\n        )\n        self.assertIn('id=\"switch-to-id-btn\" onclick=\"toggleTelegramLoginMode(\\'id\\')\" class=\"hidden', rendered_true)\n        self.assertIn('const TELEGRAM_ONLY_MODE = true;', rendered_true)\n\n        # When telegram_only_mode is False:\n        rendered_false = template.render(\n            current_lang=\"ru\",\n            web_title=\"Title\",\n            cache_ver=\"1\",\n            pwa_version=\"1\",\n            asset_ver=\"1\",\n            i18n_json=\"{}\",\n            bot_username=\"testbot\",\n            tg_client_id=\"123456789\",\n            telegram_only_mode=False,\n            web_key_js=\"\",\n            web_toggle_perf_mode=\"\",\n            web_toggle_a11y_mode=\"\",\n            login_via_telegram_btn=\"Telegram\",\n            login_or_id_link=\"Или войти по ID (Magic Link)\",\n            login_telegram_id_label=\"ID\",\n            login_or_tg_button=\"\",\n            web_brand_name=\"Brand\",\n            is_default_pass=False,\n            web_default_pass_alert=\"\",\n        )\n        self.assertNotIn('id=\"switch-to-id-btn\" onclick=\"toggleTelegramLoginMode(\\'id\\')\" class=\"hidden', rendered_false)\n        self.assertIn('const TELEGRAM_ONLY_MODE = false;', rendered_false)\n\n    def test_cookie_path_and_samesite(self):\n        from core.web.auth import _set_session_cookie, _set_csrf_cookie, COOKIE_NAME, CSRF_TOKEN_COOKIE\n\n        mock_resp = MagicMock()\n        mock_req = MagicMock()\n        mock_req.scheme = \"https\"\n        mock_req.headers = {}\n\n        _set_session_cookie(mock_resp, request=mock_req, session_token=\"test_tok\", max_age=3600)\n        mock_resp.set_cookie.assert_called_with(\n            COOKIE_NAME,\n            \"test_tok\",\n            max_age=3600,\n            path=\"/\",\n            httponly=True,\n            secure=True,\n            samesite=\"Lax\",\n        )\n\n        _set_csrf_cookie(mock_resp, mock_req, token=\"test_csrf\")\n        mock_resp.set_cookie.assert_called_with(\n            CSRF_TOKEN_COOKIE,\n            \"test_csrf\",\n            max_age=3600,\n            path=\"/\",\n            secure=True,\n            httponly=False,\n            samesite=\"Lax\",\n        )\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_telegram_runtime.py": "import asyncio\nimport importlib.util\nimport sys\nimport unittest\nfrom pathlib import Path\nfrom types import SimpleNamespace\nfrom unittest.mock import AsyncMock, Mock, patch\n\nROOT = Path(__file__).resolve().parents[1]\n\n\nclass NetworkError(Exception):\n    pass\n\n\nclass RetryAfter(Exception):\n    def __init__(self, seconds):\n        self.retry_after = seconds\n\n\ndef load_runtime():\n    # Other legacy tests replace aiogram globally. Keep these tests isolated.\n    spec = importlib.util.spec_from_file_location(\"telegram_runtime_subject\", ROOT / \"core/telegram_runtime.py\")\n    module = importlib.util.module_from_spec(spec)\n    with patch.dict(sys.modules, {\n        \"aiogram\": SimpleNamespace(Bot=object, Dispatcher=object),\n        \"aiogram.exceptions\": SimpleNamespace(\n            TelegramNetworkError=NetworkError, TelegramRetryAfter=RetryAfter, TelegramServerError=NetworkError,\n        ),\n        \"aiogram.utils.backoff\": SimpleNamespace(BackoffConfig=lambda **kwargs: SimpleNamespace(**kwargs)),\n    }):\n        spec.loader.exec_module(module)\n    return module\n\n\nclass TelegramStartupTests(unittest.IsolatedAsyncioTestCase):\n    def setUp(self):\n        self.subject = load_runtime()\n        self.bot = SimpleNamespace(id=12345, delete_webhook=AsyncMock(return_value=True), me=AsyncMock())\n\n    async def test_retries_each_startup_operation_independently(self):\n        self.bot.delete_webhook.side_effect = [NetworkError(), True]\n        self.bot.me.side_effect = [asyncio.TimeoutError(), object()]\n        with patch.object(self.subject.asyncio, \"sleep\", new_callable=AsyncMock) as sleep:\n            await self.subject.prepare_bot(self.bot)\n        self.assertEqual(self.bot.delete_webhook.await_count, 2)\n        self.assertEqual(self.bot.me.await_count, 2)\n        self.assertEqual([call.args[0] for call in sleep.await_args_list], [2, 2])\n\n    async def test_exhaustion_does_not_sleep_or_start_polling(self):\n        self.bot.delete_webhook.side_effect = NetworkError(\"offline\")\n        dispatcher = SimpleNamespace(start_polling=AsyncMock())\n        with patch.object(self.subject.asyncio, \"sleep\", new_callable=AsyncMock) as sleep:\n            with self.assertRaises(NetworkError):\n                await self.subject.run_polling(self.bot, dispatcher, allowed_updates=[])\n        self.assertEqual(self.bot.delete_webhook.await_count, 5)\n        self.assertEqual(sleep.await_count, 4)\n        self.bot.me.assert_not_awaited()\n        dispatcher.start_polling.assert_not_awaited()\n\n    async def test_retry_after_is_respected_except_after_last_attempt(self):\n        self.bot.delete_webhook.side_effect = RetryAfter(17)\n        with patch.object(self.subject.asyncio, \"sleep\", new_callable=AsyncMock) as sleep:\n            with self.assertRaises(RetryAfter):\n                await self.subject.prepare_bot(self.bot, max_attempts=2)\n        sleep.assert_awaited_once_with(17)\n\n    async def test_permanent_errors_and_false_response_do_not_retry(self):\n        self.bot.delete_webhook.side_effect = ValueError(\"invalid configuration\")\n        with self.assertRaises(ValueError):\n            await self.subject.prepare_bot(self.bot)\n        self.bot.delete_webhook.assert_awaited_once()\n        self.bot.delete_webhook.side_effect = None\n        self.bot.delete_webhook.return_value = False\n        with self.assertRaisesRegex(RuntimeError, \"did not confirm\"):\n            await self.subject.prepare_bot(self.bot)\n        self.bot.me.assert_not_awaited()\n\n    async def test_request_timeout_cancels_inflight_request(self):\n        cancelled = asyncio.Event()\n\n        async def blocked(**kwargs):\n            try:\n                await asyncio.Event().wait()\n            finally:\n                cancelled.set()\n\n        self.bot.delete_webhook.side_effect = blocked\n        with self.assertRaises(asyncio.TimeoutError):\n            await self.subject.prepare_bot(self.bot, max_attempts=1, request_timeout=0.01)\n        self.assertTrue(cancelled.is_set())\n\n    async def test_cancellation_interrupts_backoff_without_starting_dispatcher(self):\n        self.bot.delete_webhook.side_effect = RetryAfter(3600)\n        sleeping = asyncio.Event()\n\n        async def sleep(_delay):\n            sleeping.set()\n            await asyncio.Event().wait()\n\n        dispatcher = SimpleNamespace(start_polling=AsyncMock())\n        with patch.object(self.subject.asyncio, \"sleep\", side_effect=sleep):\n            task = asyncio.create_task(self.subject.run_polling(self.bot, dispatcher, allowed_updates=[]))\n            await sleeping.wait()\n            task.cancel()\n            with self.assertRaises(asyncio.CancelledError):\n                await task\n        self.bot.delete_webhook.assert_awaited_once()\n        dispatcher.start_polling.assert_not_awaited()\n\n    async def test_cancellation_drains_dispatcher_and_preserves_session_ownership(self):\n        started, stopped, finalized = asyncio.Event(), asyncio.Event(), asyncio.Event()\n\n        async def poll(*args, **kwargs):\n            started.set()\n            try:\n                await stopped.wait()\n            finally:\n                finalized.set()\n\n        async def stop():\n            stopped.set()\n            await finalized.wait()\n\n        dispatcher = SimpleNamespace(\n            start_polling=AsyncMock(side_effect=poll), stop_polling=AsyncMock(side_effect=stop),\n        )\n        task = asyncio.create_task(self.subject.run_polling(self.bot, dispatcher, allowed_updates=[\"message\"]))\n        await started.wait()\n        task.cancel()\n        with self.assertRaises(asyncio.CancelledError):\n            await task\n        self.assertTrue(finalized.is_set())\n        dispatcher.start_polling.assert_awaited_once_with(\n            self.bot, allowed_updates=[\"message\"], handle_signals=False, close_bot_session=False,\n            polling_timeout=self.subject.POLLING_TIMEOUT, backoff_config=self.subject.POLLING_BACKOFF,\n        )\n        dispatcher.stop_polling.assert_awaited_once()\n\n    async def test_dispatcher_error_propagates_without_restart(self):\n        dispatcher = SimpleNamespace(start_polling=AsyncMock(side_effect=NetworkError(\"startup callback\")))\n        with self.assertRaises(NetworkError):\n            await self.subject.run_polling(self.bot, dispatcher, allowed_updates=[])\n        dispatcher.start_polling.assert_awaited_once()\n\n    async def test_task_creation_failure_removes_filter_and_context(self):\n        import logging\n        logger = logging.getLogger(\"aiogram.dispatcher\")\n        original_filters = list(logger.filters)\n        dispatcher = SimpleNamespace(start_polling=Mock(side_effect=ValueError(\"invalid startup\")))\n        with self.assertRaises(ValueError):\n            await self.subject.run_polling(self.bot, dispatcher, allowed_updates=[])\n        self.assertEqual(logger.filters, original_filters)\n        self.assertIsNone(self.subject._polling_log_context.get())\n\n    def test_signal_cancels_startup_once_even_before_polling(self):\n        # Exercise the production function directly without evaluating AST or importing bot.py.\n        loop, main_task = Mock(), Mock()\n        self.subject._install_shutdown_signal_handlers(loop, main_task)\n        for call in loop.add_signal_handler.call_args_list:\n            sig, callback, arg = call.args\n            self.assertIn(sig, (self.subject.signal.SIGINT, self.subject.signal.SIGTERM))\n            callback(arg)\n        main_task.cancel.assert_called_once()\n\n\n\nclass TelegramPollingLogTests(unittest.TestCase):\n    def setUp(self):\n        import logging\n        self.logging = logging\n        self.subject = load_runtime()\n        self.subject_logger = logging.getLogger('aiogram.dispatcher')\n        self.old_level = self.subject_logger.level\n        self.subject_logger.setLevel(logging.INFO)\n        self.addCleanup(self.subject_logger.setLevel, self.old_level)\n        self.policy = self.subject.PollingLogFilter(12345)\n        token = self.subject._polling_log_context.set(self.policy)\n        self.addCleanup(self.subject._polling_log_context.reset, token)\n\n    def record(self, message, *args):\n        return self.logging.LogRecord('aiogram.dispatcher', self.logging.ERROR, '', 1, message, args, None)\n\n    def failure(self, now, kind='TelegramNetworkError'):\n        record = self.record('Failed to fetch updates - %s: %s', kind, 'offline')\n        with patch.object(self.subject.time, 'monotonic', return_value=now):\n            accepted = self.policy.filter(record)\n        return accepted, record\n\n    def test_brief_failure_is_info_and_repeated_attempts_are_suppressed(self):\n        accepted, record = self.failure(0)\n        self.assertTrue(accepted)\n        self.assertEqual(record.levelno, self.logging.INFO)\n        self.assertFalse(self.failure(2)[0])\n        sleep = self.record('Sleep for %f seconds and try again... (tryings = %d, bot id = %d)', 2, 1, 12345)\n        self.assertFalse(self.policy.filter(sleep))\n\n    def test_persistent_outage_reports_once_per_minute_and_escalates(self):\n        self.failure(0)\n        accepted, record = self.failure(60)\n        self.assertTrue(accepted)\n        self.assertEqual(record.levelno, self.logging.WARNING)\n        self.assertFalse(self.failure(61)[0])\n        accepted, record = self.failure(300, 'TelegramServerError')\n        self.assertTrue(accepted)\n        self.assertEqual(record.levelno, self.logging.ERROR)\n\n    def test_recovery_summarizes_duration_and_resets_the_outage(self):\n        self.failure(10)\n        self.failure(12)\n        record = self.record('Connection established (tryings = %d, bot id = %d)', 2, 12345)\n        with patch.object(self.subject.time, 'monotonic', return_value=20):\n            self.assertTrue(self.policy.filter(record))\n        self.assertEqual(record.args, (12345, 2, 10))\n        self.assertIsNone(self.policy.started)\n        self.assertEqual(self.failure(21)[1].levelno, self.logging.INFO)\n\n    def test_conflict_access_and_other_bot_errors_keep_their_original_severity(self):\n        for kind in ('TelegramConflictError', 'TelegramUnauthorizedError', 'TelegramForbiddenError', 'ValueError'):\n            accepted, record = self.failure(0, kind)\n            self.assertTrue(accepted)\n            self.assertEqual(record.levelno, self.logging.ERROR)\n        other = self.subject.PollingLogFilter(99999)\n        record = self.record('Failed to fetch updates - %s: %s', 'TelegramNetworkError', 'offline')\n        self.assertTrue(other.filter(record))\n        self.assertEqual(record.levelno, self.logging.ERROR)\n        self.assertIsNone(other.started)\n\n    def test_debug_logging_keeps_retry_diagnostics(self):\n        self.subject_logger.setLevel(self.logging.DEBUG)\n        self.failure(0)\n        accepted, record = self.failure(2)\n        self.assertTrue(accepted)\n        self.assertEqual(record.levelno, self.logging.DEBUG)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_telegram_runtime_integration.py": "\"\"\"Exercise real aiogram in a subprocess, isolated from legacy sys.modules mocks.\"\"\"\n\nimport asyncio\nimport multiprocessing\nimport unittest\n\n\ndef _run_telegram_scenario():\n    # Keep aiogram and its module imports isolated from legacy global mocks.\n    asyncio.run(scenario())\n\n\nclass AiogramLifecycleTests(unittest.TestCase):\n    def test_real_dispatcher_retries_identity_and_drains_on_cancellation(self):\n        process = multiprocessing.get_context(\"spawn\").Process(target=_run_telegram_scenario)\n        process.start()\n        process.join(timeout=20)\n        if process.is_alive():\n            process.terminate()\n            process.join(timeout=5)\n            self.fail(\"Telegram integration scenario timed out\")\n        self.assertEqual(process.exitcode, 0, f\"Telegram scenario exited with {process.exitcode}\")\n\nasync def scenario():\n    from collections import Counter\n    import logging\n    from unittest.mock import AsyncMock, patch\n\n    from aiogram import Bot, Dispatcher\n    from aiogram.client.session.base import BaseSession\n    from aiogram.exceptions import TelegramNetworkError, TelegramServerError\n    from aiogram.methods import DeleteWebhook, GetMe, GetUpdates\n    from aiogram.types import User\n    from aiogram.utils.backoff import Backoff\n\n    from core import telegram_runtime\n\n    class Session(BaseSession):\n        def __init__(self):\n            super().__init__()\n            self.calls = Counter()\n            self.started = asyncio.Event()\n            self.closed = 0\n\n        async def close(self):\n            self.closed += 1\n\n        async def make_request(self, bot, method, timeout=None):\n            self.calls[type(method)] += 1\n            if isinstance(method, DeleteWebhook):\n                if self.calls[DeleteWebhook] == 1:\n                    raise TelegramNetworkError(method=method, message=\"offline\")\n                return True\n            if isinstance(method, GetMe):\n                if self.calls[GetMe] == 1:\n                    raise TelegramServerError(method=method, message=\"temporary outage\")\n                return User(id=123456, is_bot=True, first_name=\"Test\", username=\"test_bot\")\n            if isinstance(method, GetUpdates):\n                assert method.timeout == telegram_runtime.POLLING_TIMEOUT\n                if self.calls[GetUpdates] == 1:\n                    raise TelegramNetworkError(method=method, message=\"connection reset\")\n                if self.calls[GetUpdates] == 2:\n                    raise TelegramServerError(method=method, message=\"Bad Gateway\")\n                if self.calls[GetUpdates] == 3:\n                    return []\n                self.started.set()\n                await asyncio.Event().wait()\n            raise AssertionError(type(method))\n\n        async def stream_content(self, *args, **kwargs):\n            yield b\"\"\n\n    # Check normal shutdown and a failing shutdown callback: neither may leak\n    # a polling task or leave stop_polling waiting forever.\n    for fail_shutdown in (False, True):\n        session = Session()\n        bot = Bot(\"123456:TEST_TOKEN\", session=session)\n        dispatcher = Dispatcher()\n        lifecycle = []\n\n        async def startup():\n            lifecycle.append(\"startup\")\n\n        async def shutdown():\n            lifecycle.append(\"shutdown\")\n            if fail_shutdown:\n                raise RuntimeError(\"shutdown callback failed\")\n\n        dispatcher.startup.register(startup)\n        dispatcher.shutdown.register(shutdown)\n        prepare = telegram_runtime.prepare_bot\n        logger = logging.getLogger(\"aiogram.dispatcher\")\n        original_filters = list(logger.filters)\n        with patch.object(telegram_runtime, \"prepare_bot\", lambda bot: prepare(bot, initial_delay=0)), patch.object(Backoff, \"asleep\", new_callable=AsyncMock) as backoff_sleep, unittest.TestCase().assertLogs(\"aiogram.dispatcher\", level=\"INFO\") as logs:\n            task = asyncio.create_task(telegram_runtime.run_polling(bot, dispatcher, allowed_updates=[\"message\"]))\n            await asyncio.wait_for(session.started.wait(), timeout=5)\n            task.cancel()\n            try:\n                await asyncio.wait_for(task, timeout=5)\n            except asyncio.CancelledError:\n                pass\n            else:\n                raise AssertionError(\"Cancellation was swallowed\")\n            assert backoff_sleep.await_count == 2\n        assert logger.filters == original_filters\n        assert session.calls[GetUpdates] == 4\n        assert any(\"polling reconnecting\" in record.getMessage() for record in logs.records)\n        assert any(\"polling restored\" in record.getMessage() for record in logs.records)\n        assert not [record for record in logs.records if record.levelno >= logging.WARNING]\n        assert lifecycle == [\"startup\", \"shutdown\"], lifecycle\n        assert session.calls[DeleteWebhook] == 2, session.calls\n        assert session.calls[GetMe] == 2, session.calls  # Dispatcher uses the warmed cache.\n        assert session.closed == 0  # The caller closes the session after other services.\n        await bot.session.close()\n        assert session.closed == 1\n        assert not [t for t in asyncio.all_tasks() if t is not asyncio.current_task() and not t.done()]\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_tls_config.py": "import unittest\n\nfrom core.tls_config import (\n    build_certbot_args,\n    find_nginx_certificates,\n    normalize_identifier,\n    parse_public_https_url,\n    public_https_url,\n    upgrade_legacy_http_url,\n)\n\n\nclass TLSConfigTests(unittest.TestCase):\n    def test_public_ipv4_uses_short_lived_ip_certificate_profile(self):\n        args = build_certbot_args(\"1.2.3.4\", certbot_binary=\"/opt/certbot/bin/certbot\")\n\n        self.assertIn(\"--ip-address\", args)\n        self.assertIn(\"shortlived\", args)\n        self.assertIn(\"tgbot-ip-1-2-3-4\", args)\n        self.assertNotIn(\"--domain\", args)\n\n    def test_dns_name_uses_dns_identifier_without_ip_profile(self):\n        args = build_certbot_args(\"Panel.Example.com\", \"ops@example.com\")\n\n        self.assertIn(\"--domain\", args)\n        self.assertIn(\"panel.example.com\", args)\n        self.assertNotIn(\"--ip-address\", args)\n        self.assertNotIn(\"shortlived\", args)\n\n    def test_https_url_round_trip_with_non_default_port(self):\n        url = public_https_url(\"1.2.3.4\", 8443)\n\n        self.assertEqual(url, \"https://1.2.3.4:8443\")\n        self.assertEqual(parse_public_https_url(url), (\"ip\", \"1.2.3.4\", 8443, \"tgbot-ip-1-2-3-4\"))\n\n    def test_http_port_is_reserved_for_acme_challenge(self):\n        with self.assertRaises(ValueError):\n            public_https_url(\"1.2.3.4\", 80)\n\n    def test_http_or_path_urls_are_rejected(self):\n        for value in (\"http://1.2.3.4\", \"https://panel.example.com/path\"):\n            with self.subTest(value=value), self.assertRaises(ValueError):\n                parse_public_https_url(value)\n\n    def test_legacy_agent_url_upgrades_without_changing_host(self):\n        self.assertEqual(\n            upgrade_legacy_http_url(\"http://1.2.3.4:8080\", 8443),\n            \"https://1.2.3.4:8443\",\n        )\n        self.assertEqual(\n            upgrade_legacy_http_url(\"http://panel.example.com:8080\"),\n            \"https://panel.example.com\",\n        )\n\n    def test_legacy_agent_url_rejects_path_and_credentials(self):\n        for value in (\"http://1.2.3.4/path\", \"http://user@1.2.3.4:8080\"):\n            with self.subTest(value=value), self.assertRaises(ValueError):\n                upgrade_legacy_http_url(value)\n\n    def test_private_and_invalid_hosts_are_rejected(self):\n        for value in (\n            \"127.0.0.1\",\n            \"192.168.1.10\",\n            \"bad host\",\n            \"-bad.example\",\n            \"localhost\",\n            \"panel.local\",\n            \"999.999.999.999\",\n        ):\n            with self.subTest(value=value), self.assertRaises(ValueError):\n                normalize_identifier(value)\n\n    def test_nginx_certificates_are_taken_from_matching_server_block(self):\n        dump = \"\"\"\n        # configuration file /etc/nginx/sites-enabled/panel:\n        server {\n            listen 443 ssl;\n            server_name Panel.Example.com www.example.com;\n            ssl_certificate /etc/ssl/cf/origin.pem;\n            ssl_certificate_key \"/etc/ssl/cf/origin.key\";\n            location / { proxy_pass http://127.0.0.1:8080; }\n        }\n        server {\n            listen 443 ssl;\n            server_name other.example.com;\n            ssl_certificate /etc/ssl/other.pem;\n            ssl_certificate_key /etc/ssl/other.key;\n        }\n        server {\n            listen 443 ssl;\n            server_name *.example.com;\n            ssl_certificate certs/wildcard.pem;\n            ssl_certificate_key $ssl_key;\n        }\n        \"\"\"\n\n        self.assertEqual(\n            find_nginx_certificates(dump, \"panel.example.com\"),\n            [(\"/etc/ssl/cf/origin.pem\", \"/etc/ssl/cf/origin.key\")],\n        )\n\n\nif __name__ == \"__main__\":\n    unittest.main()",
  "test_tls_finalize.py": "import tempfile\nimport unittest\nfrom pathlib import Path\n\nfrom scripts.tls_finalize import read_env, update_env\n\n\nclass TLSFinalizeTests(unittest.TestCase):\n    def test_update_env_preserves_unrelated_settings_and_removes_duplicates(self):\n        with tempfile.TemporaryDirectory() as temp_dir:\n            env_file = Path(temp_dir) / \".env\"\n            env_file.write_text(\n                'TG_BOT_TOKEN=\"keep-me\"\\nLEGACY_NODE_BRIDGE=\"true\"\\nLEGACY_NODE_BRIDGE=\"true\"\\n',\n                encoding=\"utf-8\",\n            )\n\n            update_env(env_file, {\"LEGACY_NODE_BRIDGE\": \"false\", \"WEB_SERVER_HOST\": \"127.0.0.1\"})\n\n            lines = env_file.read_text(encoding=\"utf-8\").splitlines()\n            self.assertEqual(lines.count('LEGACY_NODE_BRIDGE=\"false\"'), 1)\n            self.assertEqual(lines.count('WEB_SERVER_HOST=\"127.0.0.1\"'), 1)\n            self.assertIn('TG_BOT_TOKEN=\"keep-me\"', lines)\n            self.assertEqual(read_env(env_file)[1][\"LEGACY_NODE_BRIDGE\"], \"false\")\n\n\nif __name__ == \"__main__\":\n    unittest.main()",
  "test_traffic.py": "import os\nimport shutil\nimport tempfile\nimport unittest\nfrom base64 import b64encode\nfrom unittest.mock import MagicMock, patch\n\nfrom tests.support import AIOGRAM_DEPENDENCIES, CORE_DEPENDENCIES, mock_optional_modules\n\n\nclass TrafficModuleTests(unittest.TestCase):\n    @classmethod\n    def setUpClass(cls):\n        os.environ.setdefault(\"DATA_ENCRYPTION_KEY\", b64encode(b\"0\" * 32).decode())\n        os.environ.setdefault(\"TG_BOT_TOKEN\", \"123456789:TEST_BOT_TOKEN\")\n        os.environ.setdefault(\"TG_ADMIN_ID\", \"12345\")\n\n        mock_optional_modules((*CORE_DEPENDENCIES, *AIOGRAM_DEPENDENCIES))\n\n        from core import config, shared_state\n        from modules import traffic\n\n        cls.config = config\n        cls.shared_state = shared_state\n        cls.traffic = traffic\n\n        cls.test_dir = tempfile.mkdtemp(prefix=\"traffic_test_\")\n        cls.orig_backup_dir = cls.config.TRAFFIC_BACKUP_DIR\n        cls.orig_monitors_file = cls.traffic.TRAFFIC_MONITORS_FILE\n        cls.config.TRAFFIC_BACKUP_DIR = os.path.join(cls.test_dir, \"backups\")\n        cls.traffic.TRAFFIC_MONITORS_FILE = os.path.join(cls.test_dir, \"active_monitors.json\")\n        os.makedirs(cls.config.TRAFFIC_BACKUP_DIR, exist_ok=True)\n\n    @classmethod\n    def tearDownClass(cls):\n        cls.config.TRAFFIC_BACKUP_DIR = cls.orig_backup_dir\n        cls.traffic.TRAFFIC_MONITORS_FILE = cls.orig_monitors_file\n        shutil.rmtree(cls.test_dir, ignore_errors=True)\n\n    def setUp(self):\n        self.shared_state.TRAFFIC_MESSAGE_IDS.clear()\n        self.traffic.TRAFFIC_OFFSET[\"rx\"] = 0\n        self.traffic.TRAFFIC_OFFSET[\"tx\"] = 0\n        self.traffic._state_loaded = False\n        if os.path.exists(self.traffic.TRAFFIC_MONITORS_FILE):\n            os.remove(self.traffic.TRAFFIC_MONITORS_FILE)\n\n    def test_active_monitors_save_and_load(self):\n        monitors = {12345: 9988, 67890: 1122}\n        self.traffic._save_active_monitors(monitors)\n\n        loaded = self.traffic._load_active_monitors()\n        self.assertEqual(loaded, monitors)\n\n    def test_save_current_traffic_backup(self):\n        mock_counters = MagicMock(bytes_recv=5000, bytes_sent=8000)\n        with patch(\"psutil.net_io_counters\", return_value=mock_counters), patch(\"psutil.boot_time\", return_value=1700000000.0):\n            self.traffic.TRAFFIC_OFFSET[\"rx\"] = 1000\n            self.traffic.TRAFFIC_OFFSET[\"tx\"] = 2000\n            self.traffic.save_current_traffic_backup()\n\n        backups = os.listdir(self.config.TRAFFIC_BACKUP_DIR)\n        self.assertTrue(len(backups) >= 1)\n\n    def test_get_current_traffic_total_auto_loads_state(self):\n        mock_counters = MagicMock(bytes_recv=10000, bytes_sent=20000)\n        with patch(\"psutil.net_io_counters\", return_value=mock_counters):\n            self.traffic._state_loaded = False\n            rx, tx = self.traffic.get_current_traffic_total()\n            self.assertTrue(self.traffic._state_loaded)\n            self.assertGreaterEqual(rx, 10000)\n            self.assertGreaterEqual(tx, 20000)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_update_backups.py": "import tempfile\nimport unittest\nfrom pathlib import Path\nfrom types import SimpleNamespace\nfrom unittest.mock import AsyncMock, patch\n\nfrom core import integrity\nfrom core.restart_notification import notify_and_clear_restart_flag\n\nROOT = Path(__file__).resolve().parents[1]\n\n\nclass UpdateBackupTests(unittest.TestCase):\n    def test_integrity_error_does_not_masquerade_as_no_local_changes(self):\n        with tempfile.TemporaryDirectory() as directory:\n            report = SimpleNamespace(status=\"ERROR\", error_message=\"missing target revision\", modified_files=[])\n            with patch.object(integrity, \"check_project_integrity\", return_value=report):\n                with self.assertRaisesRegex(RuntimeError, \"missing target revision\"):\n                    integrity.backup_modified_files(directory)\n            self.assertFalse((Path(directory) / \".backups\").exists())\n\n    def test_backup_cli_reports_failure_to_installer(self):\n        with patch.object(integrity, \"backup_modified_files\", return_value=(False, \"\", [])):\n            self.assertEqual(integrity.main([\"backup\"]), 1)\n\n\nclass RestartBackupTests(unittest.IsolatedAsyncioTestCase):\n    async def test_restart_notification_preserves_backups_even_when_notification_fails(self):\n        with tempfile.TemporaryDirectory() as directory:\n            root = Path(directory)\n            flag = root / \"restart_flag.txt\"\n            saved = []\n            for folder in (\".backups/pre_update_test\", \".backup\"):\n                path = root / folder / \"local.py\"\n                path.parent.mkdir(parents=True)\n                path.write_text(\"local changes\", encoding=\"utf-8\")\n                saved.append(path)\n            for failure in (None, OSError(\"offline\")):\n                flag.write_text(\"123:456\", encoding=\"utf-8\")\n                bot = SimpleNamespace(edit_message_text=AsyncMock(side_effect=failure))\n                await notify_and_clear_restart_flag(\n                    bot, str(flag), lambda _: \"en\", lambda *_: \"restarted\", lambda **kwargs: kwargs,\n                )\n                bot.edit_message_text.assert_awaited_once()\n                self.assertFalse(flag.exists())\n                for path in saved:\n                    self.assertEqual(path.read_text(encoding=\"utf-8\"), \"local changes\")\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_watchdog.py": "import os\nimport sys\nimport tempfile\nimport shutil\nimport unittest\nfrom base64 import b64encode\nfrom unittest.mock import patch, MagicMock\n\nfrom tests.support import AIOGRAM_DEPENDENCIES, CORE_DEPENDENCIES, mock_optional_modules\n\nos.environ.setdefault(\"DATA_ENCRYPTION_KEY\", b64encode(b\"0\" * 32).decode())\nos.environ.setdefault(\"TG_BOT_TOKEN\", \"123456789:TEST_BOT_TOKEN\")\nos.environ.setdefault(\"TG_ADMIN_ID\", \"12345\")\n\nmock_optional_modules((*CORE_DEPENDENCIES, *AIOGRAM_DEPENDENCIES, \"docker.client\", \"docker.errors\"))\n\n# Add project root to sys.path\nsys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), \"..\")))\n\nimport watchdog\n\n\nclass TestWatchdogCrashAlert(unittest.TestCase):\n    def setUp(self):\n        self.test_dir = tempfile.mkdtemp()\n        self.env_file = os.path.join(self.test_dir, \".env\")\n        with open(self.env_file, \"w\") as f:\n            f.write(\"TG_BOT_TOKEN=123456:FAKE_TOKEN\\nTG_ADMIN_ID=1234567\\nDEFAULT_LANGUAGE=ru\\n\")\n\n        self.config_dir = os.path.join(self.test_dir, \"config\")\n        os.makedirs(self.config_dir, exist_ok=True)\n\n        self.logs_dir = os.path.join(self.test_dir, \"logs\", \"bot\")\n        os.makedirs(self.logs_dir, exist_ok=True)\n        self.bot_log = os.path.join(self.logs_dir, \"bot.log\")\n        with open(self.bot_log, \"w\") as f:\n            f.write(\"ERROR:root:Traceback (most recent call last):\\n  File 'test.py', line 10\\nZeroDivisionError: division by zero\\n\")\n\n    def tearDown(self):\n        shutil.rmtree(self.test_dir, ignore_errors=True)\n\n    def test_planned_restart_flag_ignores_crash_alert(self):\n        \"\"\"If restart_flag.txt exists, run_crash_alert_oneshot exits without sending crash alert.\"\"\"\n        restart_flag = os.path.join(self.config_dir, \"restart_flag.txt\")\n        with open(restart_flag, \"w\") as f:\n            f.write(\"123:456\")\n\n        with patch(\"os.path.dirname\", return_value=self.test_dir), \\\n             patch(\"http.client.HTTPSConnection\") as mock_conn_cls:\n            with self.assertRaises(SystemExit) as cm:\n                watchdog.run_crash_alert_oneshot()\n            self.assertEqual(cm.exception.code, 0)\n            mock_conn_cls.assert_not_called()\n\n    def test_unplanned_crash_sends_telegram_alert(self):\n        \"\"\"If no flag exists, run_crash_alert_oneshot extracts log error and sends Telegram alert.\"\"\"\n        with patch(\"os.path.dirname\", return_value=self.test_dir), \\\n             patch(\"http.client.HTTPSConnection\") as mock_conn_cls:\n            mock_conn = MagicMock()\n            mock_conn_cls.return_value = mock_conn\n\n            with self.assertRaises(SystemExit) as cm:\n                watchdog.run_crash_alert_oneshot()\n\n            self.assertEqual(cm.exception.code, 0)\n            mock_conn_cls.assert_called_once_with(\"api.telegram.org\", timeout=10)\n            mock_conn.request.assert_called_once()\n            args, kwargs = mock_conn.request.call_args\n            method, path = args[0], args[1]\n            body = kwargs.get(\"body\") if \"body\" in kwargs else args[2]\n            self.assertEqual(method, \"POST\")\n            self.assertIn(\"123456:FAKE_TOKEN\", path)\n            body_str = body.decode(\"utf-8\") if isinstance(body, bytes) else body\n            self.assertIn(\"ZeroDivisionError\", body_str)\n            self.assertIn(\"Аварийная остановка\", body_str)\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_web_cache_policy.py": "\"\"\"Run cache policy tests apart from legacy tests that replace aiohttp globally.\"\"\"\nimport multiprocessing\nfrom pathlib import Path\nimport runpy\nimport sys\nimport unittest\nfrom unittest.mock import MagicMock, patch\n\nROOT = Path(__file__).resolve().parents[1]\n\n\ndef _run_cache_scenarios():\n    sys.argv = [\"web_cache_scenarios.py\", \"-v\"]\n    runpy.run_path(str(ROOT / \"tests\" / \"web_cache_scenarios.py\"), run_name=\"__main__\")\n\n\nclass CachePolicyIsolationTests(unittest.TestCase):\n    def test_cache_policy_with_legacy_aiohttp_mocks(self):\n        # Reproduce discovery pollution: only the child may import real aiohttp.\n        with patch.dict(sys.modules, {\"aiohttp\": MagicMock(), \"aiohttp.web\": MagicMock()}):\n            process = multiprocessing.get_context(\"spawn\").Process(target=_run_cache_scenarios)\n            process.start()\n            process.join(timeout=30)\n            if process.is_alive():\n                process.terminate()\n                process.join(timeout=5)\n                self.fail(\"Cache policy scenarios timed out\")\n            self.assertEqual(process.exitcode, 0, f\"Cache policy scenarios exited with {process.exitcode}\")\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_web_notifications.py": "\"\"\"Regression tests for the shared WebUI notification state used by API and SSE.\"\"\"\nimport unittest\nfrom collections import deque\n\nfrom core import shared_state\nfrom core.web.notification_state import clear_user_notifications, get_user_notifications\n\n\nclass NotificationClearTests(unittest.TestCase):\n    def setUp(self):\n        self.original_notifications = shared_state.WEB_NOTIFICATIONS\n        self.original_read = shared_state.WEB_USER_LAST_READ\n        self.original_cleared = shared_state.WEB_USER_CLEARED_AT\n        self.original_alerts = shared_state.ALERTS_CONFIG\n        shared_state.WEB_NOTIFICATIONS = deque([\n            {\"time\": 100.0, \"type\": \"cpu\", \"text\": \"Older\"},\n            {\"time\": 200.0, \"type\": \"cpu\", \"text\": \"Newer\"},\n        ], maxlen=50)\n        shared_state.WEB_USER_LAST_READ = {}\n        shared_state.WEB_USER_CLEARED_AT = {}\n        shared_state.ALERTS_CONFIG = {1: {\"cpu\": True}, 2: {\"cpu\": True}}\n        self.addCleanup(self.restore)\n\n    def restore(self):\n        shared_state.WEB_NOTIFICATIONS = self.original_notifications\n        shared_state.WEB_USER_LAST_READ = self.original_read\n        shared_state.WEB_USER_CLEARED_AT = self.original_cleared\n        shared_state.ALERTS_CONFIG = self.original_alerts\n\n    def visible(self, user_id):\n        return get_user_notifications(user_id, \"en\", \"en\")\n\n    def test_clear_is_user_scoped(self):\n        clear_user_notifications(1, now=150.0)\n        self.assertEqual(len(shared_state.WEB_NOTIFICATIONS), 2)\n        self.assertEqual(shared_state.WEB_USER_CLEARED_AT, {1: 150.0})\n        self.assertEqual(shared_state.WEB_USER_LAST_READ[1], 150.0)\n        self.assertEqual([n[\"text\"] for n in self.visible(1)[\"notifications\"]], [\"Newer\"])\n        self.assertEqual([n[\"text\"] for n in self.visible(2)[\"notifications\"]], [\"Older\", \"Newer\"])\n        self.assertEqual(self.visible(1)[\"unread_count\"], 1)\n        self.assertEqual(self.visible(2)[\"unread_count\"], 2)\n\n    def test_clear_idempotent_and_new_notifications_visible(self):\n        clear_user_notifications(1, now=250.0)\n        clear_user_notifications(1, now=250.0)\n        self.assertEqual(self.visible(1)[\"notifications\"], [])\n        shared_state.WEB_NOTIFICATIONS.append({\"time\": 251.0, \"type\": \"cpu\", \"text\": \"Fresh\"})\n        self.assertEqual([n[\"text\"] for n in self.visible(1)[\"notifications\"]], [\"Fresh\"])\n\n    def test_language_fallback_and_type_filter(self):\n        shared_state.WEB_NOTIFICATIONS.append({\n            \"time\": 210.0, \"type\": \"cpu\", \"text\": \"Original\",\n            \"text_map\": {\"ru\": \"Перевод\", \"en\": \"Translation\"},\n        })\n        visible = get_user_notifications(1, \"de\", \"en\")[\"notifications\"]\n        self.assertEqual(visible[-1][\"text\"], \"Translation\")\n        self.assertNotIn(\"text_map\", visible[-1])\n        self.assertIn(\"text_map\", shared_state.WEB_NOTIFICATIONS[-1])\n        shared_state.ALERTS_CONFIG[1][\"cpu\"] = False\n        self.assertEqual(self.visible(1)[\"notifications\"], [])\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "web_cache_scenarios.py": "\"\"\"Cache policy scenarios run in a clean interpreter, apart from legacy mocks.\"\"\"\nimport importlib.util\nfrom pathlib import Path\nimport sys\nfrom types import SimpleNamespace\nimport unittest\nfrom unittest.mock import AsyncMock, patch\n\nfrom aiohttp import web\n\n\ndef load_middleware():\n    source = Path(__file__).resolve().parents[1] / \"core/web/middlewares.py\"\n    spec = importlib.util.spec_from_file_location(\"core.web._cache_policy_tests\", source)\n    module = importlib.util.module_from_spec(spec)\n    # Import the real middleware with isolated configuration and authentication.\n    # Do not initialize the bot, database, or environment-specific configuration.\n    with patch.dict(sys.modules, {\n        \"core.config\": SimpleNamespace(LEGACY_NODE_BRIDGE=False, WEB_PUBLIC_URL=\"https://panel.example\"),\n        \"core.web.auth\": SimpleNamespace(verify_csrf_token=AsyncMock()),\n    }):\n        spec.loader.exec_module(module)\n    return module.security_headers_middleware\n\n\nclass CachePolicyTests(unittest.IsolatedAsyncioTestCase):\n    async def apply_policy(self, path, response, request_headers=None, raised=False):\n        request = SimpleNamespace(path=path, scheme=\"https\", headers=request_headers or {})\n        handler = AsyncMock(side_effect=response) if raised else AsyncMock(return_value=response)\n        if raised:\n            with self.assertRaises(web.HTTPException) as caught:\n                await load_middleware()(request, handler)\n            result = caught.exception\n        else:\n            result = await load_middleware()(request, handler)\n        self.assertIs(result, response)\n        return response.headers\n\n    async def test_all_pages_discard_speculation_cache_without_clearing_sessions(self):\n        for path in (\"/\", \"/nodes\", \"/settings\", \"/operations\", \"/terminal\", \"/login\", \"/reset_password\"):\n            with self.subTest(path=path):\n                response = SimpleNamespace(status=200, content_type=\"text/html\", headers={\"Cache-Control\": \"public, max-age=3600\", \"Set-Cookie\": \"session=kept\"})\n                headers = await self.apply_policy(path, response)\n                self.assertEqual(headers[\"Cache-Control\"], \"no-store\")\n                self.assertEqual(headers[\"Clear-Site-Data\"], '\"prefetchCache\", \"prerenderCache\"')\n                self.assertEqual(headers[\"Set-Cookie\"], \"session=kept\")\n                self.assertEqual(headers[\"Vary\"], \"Sec-Purpose, Purpose\")\n\n    async def test_returned_and_raised_503_are_not_cached(self):\n        for raised in (False, True):\n            response = web.HTTPServiceUnavailable(content_type=\"text/plain\", headers={\"Cache-Control\": \"public, max-age=60\", \"Retry-After\": \"30\"})\n            headers = await self.apply_policy(\"/nodes\", response, {\"Sec-Fetch-Dest\": \"document\"}, raised=raised)\n            self.assertEqual(headers[\"Cache-Control\"], \"no-store\")\n            self.assertIn(\"prefetchCache\", headers[\"Clear-Site-Data\"])\n            self.assertEqual(headers[\"Retry-After\"], \"30\")\n\n    async def test_redirects_keep_location_and_receive_page_cache_policy(self):\n        response = web.HTTPFound(location=\"/login\")\n        headers = await self.apply_policy(\"/settings\", response, {\"Sec-Fetch-Dest\": \"document\"}, raised=True)\n        self.assertEqual(headers[\"Location\"], \"/login\")\n        self.assertEqual(headers[\"Cache-Control\"], \"no-store\")\n\n    async def test_existing_vary_is_preserved_without_duplicates(self):\n        for existing, expected in ((\"Accept-Encoding, sec-purpose\", \"Accept-Encoding, sec-purpose, Purpose\"), (\"*\", \"*\")):\n            response = web.Response(content_type=\"text/html\", headers={\"Vary\": existing})\n            headers = await self.apply_policy(\"/\", response)\n            self.assertEqual(headers[\"Vary\"], expected)\n\n    async def test_public_asset_and_stream_policies_are_preserved(self):\n        for path, content_type, policy in ((\"/static/main.css\", \"text/css\", \"public, max-age=3600\"), (\"/api/events\", \"text/event-stream\", \"no-cache\")):\n            response = web.Response(content_type=content_type, headers={\"Cache-Control\": policy})\n            headers = await self.apply_policy(path, response)\n            self.assertEqual(headers[\"Cache-Control\"], policy)\n            self.assertNotIn(\"Clear-Site-Data\", headers)\n\n    async def test_non_document_errors_are_not_cached(self):\n        response = web.Response(status=503, content_type=\"text/plain\")\n        headers = await self.apply_policy(\"/api/status\", response)\n        self.assertEqual(headers[\"Cache-Control\"], \"no-store\")\n\n\n\nclass AgentAddressApiTests(unittest.IsolatedAsyncioTestCase):\n    async def asyncSetUp(self):\n        import json\n        from cryptography.fernet import Fernet\n        from aiohttp.test_utils import TestClient, TestServer\n        from unittest.mock import Mock\n        self.cipher = Fernet(Fernet.generate_key())\n        self.collectors = {4: Mock(return_value=[\"198.51.100.10\"]), 6: Mock(return_value=[\"2001:4860::8888\"])}\n        path = Path(__file__).resolve().parents[1] / \"core/web/agent_addresses.py\"\n        spec = importlib.util.spec_from_file_location(\"core.web._agent_address_cases\", path)\n        self.subject = importlib.util.module_from_spec(spec)\n        def encrypted_response(data):\n            return web.json_response({\"d\": \"fw1:\" + self.cipher.encrypt(json.dumps(data).encode()).decode()})\n        with patch.dict(sys.modules, {\n            \"core.utils\": SimpleNamespace(encrypted_json_response=encrypted_response),\n            \"core.web.auth\": SimpleNamespace(get_current_user=lambda request: {\"id\": 1} if request.headers.get(\"X-Test-User\") else None),\n        }):\n            spec.loader.exec_module(self.subject)\n        async def addresses(request):\n            version = int(request.match_info[\"version\"])\n            return await self.subject.agent_address_response(request, version, self.collectors[version])\n        app = web.Application()\n        app.router.add_get(\"/api/agent/ipv{version:[46]}\", addresses)\n        self.client = TestClient(TestServer(app))\n        await self.client.start_server()\n\n    async def asyncTearDown(self):\n        await self.client.close()\n\n    async def test_both_address_routes_require_authentication_before_collection(self):\n        for version in (4, 6):\n            response = await self.client.get(f\"/api/agent/ipv{version}\")\n            self.assertEqual(response.status, 401)\n            self.collectors[version].assert_not_called()\n\n    async def test_address_payload_is_an_encrypted_envelope_for_both_families(self):\n        import json\n        for version, expected in ((4, \"198.51.100.10\"), (6, \"2001:4860::8888\")):\n            response = await self.client.get(f\"/api/agent/ipv{version}\", headers={\"X-Test-User\": \"1\"})\n            body = await response.text()\n            self.assertNotIn(expected, body)\n            envelope = json.loads(body)\n            self.assertEqual(set(envelope), {\"d\"})\n            data = json.loads(self.cipher.decrypt(envelope[\"d\"][4:].encode()))\n            self.assertEqual(data[\"primary\"], expected)\n            self.assertEqual(data[\"ips\"], [expected])\n            self.assertEqual(data[\"count\"], 1)\n\n    async def test_ipv6_absence_returns_an_empty_encrypted_snapshot(self):\n        import json\n        self.collectors[6].return_value = []\n        response = await self.client.get(\"/api/agent/ipv6\", headers={\"X-Test-User\": \"1\"})\n        envelope = await response.json()\n        data = json.loads(self.cipher.decrypt(envelope[\"d\"][4:].encode()))\n        self.assertEqual(data[\"count\"], 0)\n        self.assertEqual(data[\"primary\"], \"\")\n        self.assertEqual(data[\"ips\"], [])\n\n\nclass NetworkAddressTests(unittest.TestCase):\n    def test_ipv6_collection_ignores_loopback_link_local_and_private_addresses(self):\n        import socket\n        from core.network_addresses import collect_ipv6_addresses\n        values = [\"::1\", \"fe80::1%eth0\", \"fd00::1\", \"2001:4860::8888\", \"2001:4860::8888\"]\n        records = [SimpleNamespace(family=socket.AF_INET6, address=value) for value in values]\n        with patch(\"psutil.net_if_addrs\", return_value={\"eth0\": records}):\n            self.assertEqual(collect_ipv6_addresses(), [\"2001:4860::8888\"])\n\n    def test_node_address_selection_supports_old_and_dual_stack_clients(self):\n        from core.network_addresses import node_ip_addresses\n        self.assertEqual(node_ip_addresses({\"ip\": \"198.51.100.10\"}), {\"ipv4\": \"198.51.100.10\", \"ipv6\": \"\"})\n        node = {\"ip\": \"198.51.100.10\", \"stats\": {\"ipv6\": \"2001:4860::8888\"}}\n        self.assertEqual(node_ip_addresses(node)[\"ipv6\"], \"2001:4860::8888\")\n\n    def test_invalid_or_wrong_family_addresses_are_never_displayed(self):\n        from core.network_addresses import normalize_address\n        for value in (\"not-an-ip\", \"fe80::1\", \"::\", \"::1\", \"ff02::1\", \"198.51.100.10\"):\n            self.assertEqual(normalize_address(value, 6), \"\")\n\n\nclass ReversePtrTests(unittest.IsolatedAsyncioTestCase):\n    async def asyncSetUp(self):\n        from core import network_addresses\n        self.subject = network_addresses\n        self.subject._PTR_CACHE.clear()\n        self.addCleanup(self.subject._PTR_CACHE.clear)\n\n    async def test_preferred_ipv4_and_cached_success(self):\n        with patch.object(self.subject.socket, \"gethostbyaddr\", return_value=(\"node.example.\", [], [])) as lookup:\n            self.assertEqual(await self.subject.get_preferred_reverse_ptr(\"8.8.8.8\", \"2001:4860::8888\"), \"node.example\")\n            self.assertEqual(await self.subject.get_reverse_ptr(\"8.8.8.8\"), \"node.example\")\n            lookup.assert_called_once_with(\"8.8.8.8\")\n\n    async def test_ipv6_fallback_and_invalid_addresses(self):\n        with patch.object(self.subject.socket, \"gethostbyaddr\", return_value=(\"node6.example\", [], [])) as lookup:\n            self.assertEqual(await self.subject.get_preferred_reverse_ptr(\"N/A\", \"2001:4860::8888\"), \"node6.example\")\n            self.assertEqual(await self.subject.get_preferred_reverse_ptr(\"127.0.0.1\", \"::1\"), \"\")\n            lookup.assert_called_once_with(\"2001:4860::8888\")\n\n    async def test_missing_ptr_is_cached_without_ipv6_retry(self):\n        with patch.object(self.subject.socket, \"gethostbyaddr\", side_effect=OSError(\"no PTR\")) as lookup:\n            self.assertEqual(await self.subject.get_preferred_reverse_ptr(\"8.8.8.8\", \"2001:4860::8888\"), \"\")\n            self.assertEqual(await self.subject.get_reverse_ptr(\"8.8.8.8\"), \"\")\n            lookup.assert_called_once_with(\"8.8.8.8\")\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "test_twemoji.cjs": "const assert = require('node:assert/strict');\nconst fs = require('node:fs');\nconst vm = require('node:vm');\nconst { test } = require('node:test');\nconst twemoji = fs.readFileSync('core/static/vendor/twemoji.min.js', 'utf8');\nconst common = fs.readFileSync('core/static/js/common.js', 'utf8');\nconst start = common.indexOf('function styleGradientClouds(');\nconst parser = common.slice(start, common.indexOf('function replaceEmojisWithFlagsHTML(', start));\n\ntest('only country flags become images while ordinary emoji stay native', () => {\n    const context = vm.createContext({ document: { body: {} } });\n    context.window = context;\n    vm.runInContext(twemoji + '\\n' + parser, context);\n    const parse = context.twemoji.parse;\n    let html;\n    context.twemoji.parse = (input, options) => { html = parse(input, options); };\n    context.parsePageEmojis('☁️ 🚀 🇷🇺 🇺🇸');\n    assert.ok(html.includes('☁️ 🚀'));\n    assert.ok(html.includes('https://flagcdn.com/ru.svg'));\n    assert.ok(html.includes('https://flagcdn.com/us.svg'));\n    assert.ok(html.includes('class=\"emoji flagcdn\"'));\n    assert.equal((html.match(/<img /g) || []).length, 2);\n    assert.equal(html.includes('twemoji@'), false);\n});\n\nfunction textNode(text) {\n    return {\n        nodeType: 3, textContent: text,\n        replaceWith(fragment) {\n            const parent = this.parentElement;\n            const index = parent.childNodes.indexOf(this);\n            parent.childNodes.splice(index, 1, ...fragment.childNodes);\n            fragment.childNodes.forEach(child => { child.parentElement = parent; });\n        }\n    };\n}\nfunction element(className = '') {\n    const node = {\n        nodeType: 1, className, childNodes: [],\n        classList: { contains: name => node.className.split(' ').includes(name) },\n        matches: selector => node.classList.contains(selector.slice(1)),\n        querySelectorAll(selector) {\n            return this.childNodes.filter(child => child.nodeType === 1).flatMap(child => [\n                ...(child.matches(selector) ? [child] : []), ...child.querySelectorAll(selector)\n            ]);\n        },\n        appendChild(child) { this.childNodes.push(child); child.parentElement = this; }\n    };\n    Object.defineProperty(node, 'textContent', {\n        get: () => node.childNodes.map(child => child.textContent).join(''),\n        set: text => { node.childNodes = []; node.appendChild(textNode(text)); }\n    });\n    return node;\n}\n\ntest('gradient clouds use native text presentation and survive repeated SPA processing', () => {\n    const title = element('bg-clip-text');\n    title.textContent = '☁️ Jatix 🚀';\n    const body = element();\n    body.appendChild(title);\n    const document = {\n        body, createTextNode: textNode, createElement: () => element(),\n        createDocumentFragment: () => element()\n    };\n    const context = vm.createContext({ document });\n    context.window = context;\n    vm.runInContext(parser, context);\n    context.parsePageEmojis(title);\n    assert.equal(title.childNodes.length, 2);\n    const cloud = title.childNodes[0];\n    assert.equal(cloud.className, 'gradient-cloud');\n    assert.equal(cloud.textContent, '\\u2601\\uFE0E');\n    assert.equal(title.textContent, '\\u2601\\uFE0E Jatix 🚀');\n    context.parsePageEmojis(body);\n    assert.equal(title.childNodes.length, 2);\n    assert.equal(title.childNodes[0], cloud);\n});\n",
    "test_ip_badges.cjs": "const assert = require('node:assert/strict');\nconst fs = require('node:fs');\nconst vm = require('node:vm');\nconst { test } = require('node:test');\nconst source = fs.readFileSync('core/static/js/common.js', 'utf8');\nconst start = source.indexOf('const ipFamilySelections =');\nconst end = source.indexOf('// Global Capture delegation for Copying IP', start);\nconst captureStart = source.indexOf(\"document.addEventListener('click', e => {\", end);\nconst captureEnd = source.indexOf('}, true);', captureStart) + '}, true);'.length;\nfunction fixture(saved = new Map()) {\n    const listeners = new Map(), badges = [], copies = [];\n    const context = createBrowserContext({\n        sessionStorage: { getItem: key => saved.get(key) || null, setItem: (key, value) => saved.set(key, value) },\n        document: { addEventListener: (name, fn) => listeners.set(name, fn), querySelectorAll: () => badges },\n        decryptData: value => value, escapeHtml: value => String(value), clearInterval() {},\n        copyIpWithFeedback: ip => copies.push(ip), isTouchDeviceOrEvent: () => false\n    });\n    context.window = context;\n    vm.runInContext(source.slice(start, end) + source.slice(captureStart, captureEnd), context);\n    function badge() {\n        const text = { dataset: {}, classList: { remove() {} }, textContent: '' };\n        const label = {}, attributes = {}, copyAttrs = {};\n        const copy = { setAttribute: (k,v) => { copyAttrs[k]=v; }, getAttribute: k => copyAttrs[k], closest: () => box };\n        const box = { dataset: {}, classList: { add() {} },\n            querySelector: selector => selector === '.ip-copy-text' ? text : selector === '.ip-family-label' ? label : copy,\n            setAttribute: (k,v) => { attributes[k]=v; }, removeAttribute: k => { delete attributes[k]; }, getAttribute: k => attributes[k],\n            closest: () => box,\n        };\n        badges.push(box);\n        return { box, text, label, copy, attributes };\n    }\n    return { context, badge, listeners, copies, saved };\n}\nconst ipv4 = '198.51.100.10', ipv6 = '2001:4860::8888';\n\ntest('IPv4 is the default and a toggle synchronizes card, dialog, and copy value', () => {\n    const f = fixture(), card = f.badge(), modal = f.badge();\n    for (const item of [card, modal]) f.context.updateIpBadge(item.box, f.context.ipBadgeState(ipv4, ipv6, 'node:1'));\n    assert.equal(card.text.textContent, ipv4);\n    f.context.toggleIpBadge(card.box);\n    assert.equal(card.text.textContent, ipv6);\n    assert.equal(modal.text.textContent, ipv6);\n    assert.equal(modal.copy.getAttribute('data-ip'), ipv6);\n    assert.equal(modal.label.textContent, 'IPv6');\n    f.context.updateIpBadge(card.box, f.context.ipBadgeState(ipv4, ipv6, 'node:1'));\n    assert.equal(card.text.textContent, ipv6, 'Live refresh must preserve the selected family');\n});\n\ntest('family preference survives reload within a session and resets in a fresh session', () => {\n    const f = fixture(), item = f.badge();\n    f.context.updateIpBadge(item.box, f.context.ipBadgeState(ipv4, ipv6, 'agent'));\n    f.context.toggleIpBadge(item.box);\n    assert.equal(fixture(f.saved).context.ipBadgeState(ipv4, ipv6, 'agent').family, '6');\n    assert.equal(fixture().context.ipBadgeState(ipv4, ipv6, 'agent').family, '4');\n    assert.equal(f.context.ipBadgeState(ipv4, ipv6, 'node:2').family, '4');\n});\n\ntest('single-stack hosts never switch to a missing IP and preserve the prior preference', () => {\n    const f = fixture(new Map([['ip-family:agent', '6']])), item = f.badge();\n    f.context.updateIpBadge(item.box, f.context.ipBadgeState(ipv4, '', 'agent'));\n    f.context.toggleIpBadge(item.box);\n    assert.equal(item.text.textContent, ipv4);\n    assert.equal(item.attributes.role, undefined);\n    assert.equal(f.context.ipBadgeState('', '', 'empty').family, '4');\n    assert.equal(f.context.ipBadgeState(ipv4, ipv6, 'agent').family, '6');\n});\n\ntest('copying the selected IPv6 does not toggle and Enter toggles without copying', () => {\n    const f = fixture(), item = f.badge();\n    f.context.updateIpBadge(item.box, f.context.ipBadgeState(ipv4, ipv6, 'agent'));\n    f.context.toggleIpBadge(item.box);\n    f.listeners.get('click')({ target: { closest: () => item.copy }, preventDefault() {}, stopImmediatePropagation() {}, stopPropagation() {} });\n    assert.deepEqual(f.copies, [ipv6]);\n    assert.equal(item.box.dataset.ipFamily, '6');\n    f.listeners.get('keydown')({ target: item.box, key: 'Enter', preventDefault() {}, stopImmediatePropagation() {} });\n    assert.equal(item.box.dataset.ipFamily, '4');\n});\n\ntest('IPv6-only node data uses the available family and card markup includes both choices', () => {\n    const f = fixture();\n    assert.equal(f.context.nodeIpBadgeState({ id: 3, ip: ipv6 }).ip, ipv6);\n    const html = f.context.renderNodeIpBadge({ id: 3, ip: ipv4, ipv6 });\n    assert.ok(html.includes('data-ipv6=\"' + ipv6 + '\"'));\n    assert.ok(html.includes('data-ip-switch=\"true\"'));\n});\n\ntest('agent address requests share in-flight work and use secure transport for both families', async () => {\n    const dashboard = fs.readFileSync('core/static/js/dashboard.js', 'utf8');\n    const a = dashboard.indexOf('async function fetchAgentAddressPair()');\n    const b = dashboard.indexOf('async function initAgentIpBadge()', a);\n    const calls = [];\n    const context = createBrowserContext({ window: { secureFetch: async url => {\n        calls.push(url);\n        return { ok: true, json: async () => ({ primary: url.endsWith('4') ? ipv4 : ipv6 }) };\n    } } });\n    vm.runInContext('let agentAddressData = null; let agentIpRequest = null;\\n' + dashboard.slice(a, b), context);\n    const [pair] = await Promise.all([context.fetchAgentAddressPair(), context.fetchAgentAddressPair()]);\n    assert.deepEqual(calls, ['/api/agent/ipv4', '/api/agent/ipv6']);\n    assert.equal(pair.ipv4.primary, ipv4);\n    assert.equal(pair.ipv6.primary, ipv6);\n});\n\ntest('the address modal requires two addresses of the same family, not one of each', async () => {\n    const source = fs.readFileSync('core/static/js/dashboard.js', 'utf8');\n    const start = source.indexOf('function agentHasAdditionalAddresses(');\n    const end = source.indexOf('function closeAgentIpsModal()', start);\n    for (const [v4, v6, expected] of [[1,1,false], [1,0,false], [0,1,false], [0,0,false], [2,0,true], [0,2,true], [2,1,true], [1,2,true]]) {\n        let opened = 0, loaded = 0;\n        const context = createBrowserContext({\n            agentAddressData: { ipv4: { count: v4 }, ipv6: { count: v6 } },\n            document: { getElementById: () => ({}) },\n            animateModalOpen: () => { opened++; },\n            loadAgentIpv4: async () => { loaded++; }\n        });\n        vm.runInContext(source.slice(start, end), context);\n        assert.equal(context.agentHasAdditionalAddresses(context.agentAddressData), expected);\n        await context.openAgentIpsModal();\n        assert.equal(opened, Number(expected));\n        assert.equal(loaded, Number(expected));\n    }\n});\n\nfunction createBrowserContext(globals) {\n    if (globals.window === globals) return vm.createContext(globals);\n    const browser = globals.window || {};\n    Object.assign(globals, browser);\n    for (const key of Object.keys(globals)) {\n        if (key === 'window') continue;\n        Object.defineProperty(browser, key, {\n            configurable: true,\n            get: () => globals[key],\n            set: value => { globals[key] = value; }\n        });\n    }\n    globals.window = new Proxy(browser, {\n        get: (target, key) => Reflect.has(target, key) ? Reflect.get(target, key) : Reflect.get(globals, key),\n        set: (target, key, value) => { globals[key] = value; Reflect.set(target, key, value); return true; }\n    });\n    return vm.createContext(globals);\n}\n\nfunction runBrowserCode(source, globals) { return vm.runInContext(source, createBrowserContext(globals)); }\n",
}

_PYTHON_MODULES = ["tests.test_backups","tests.test_client_alerts","tests.test_codacy_core","tests.test_codacy_modules","tests.test_deploy_backup_cleanup","tests.test_endpoint_migration","tests.test_log_maintenance","tests.test_manage_cli_bootstrap","tests.test_node_client_updates","tests.test_node_confirmations","tests.test_operations_integration","tests.test_telegram_auth","tests.test_telegram_runtime","tests.test_telegram_runtime_integration","tests.test_tls_config","tests.test_tls_finalize","tests.test_traffic","tests.test_update_backups","tests.test_watchdog","tests.test_web_cache_policy","tests.test_web_notifications"]
_JAVASCRIPT_FILES = ["tests/test_browser_utils.cjs","tests/test_chart_range.cjs","tests/test_click_spam.cjs","tests/test_dashboard_widgets.cjs","tests/test_operations_live.cjs","tests/test_panel_bootstrap.cjs","tests/test_panel_navigation.cjs","tests/test_ping_notifications_ui.cjs","tests/test_service_worker.cjs","tests/test_twemoji.cjs","tests/test_ip_badges.cjs"]


@contextmanager
def _stage_cases():
    created = []
    try:
        for name, content in _BUNDLED_CASES.items():
            target = TEST_DIR / name
            if target.exists():
                raise RuntimeError(f"Refusing to overwrite existing test: {target}")
            target.write_text(content, encoding="utf-8")
            created.append(target)
        yield
    finally:
        for target in reversed(created):
            target.unlink(missing_ok=True)


def _run_suite(command):
    try:
        result = subprocess.run(
            command,
            cwd=ROOT,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            timeout=300,
            check=False,
        )
    except FileNotFoundError as error:
        raise AssertionError(f"Test runner missing: {error}") from error
    except subprocess.TimeoutExpired as error:
        raise AssertionError(f"Test command timed out: {command!r}") from error
    if result.returncode:
        raise AssertionError(
            f"Failed test command (exit {result.returncode}): {command!r}\n"
            + result.stdout[-24000:]
        )
    print(result.stdout[-5000:])


class AllComponentsTest(unittest.TestCase):
    def test_01_python_and_integrations(self):
        with _stage_cases():
            _run_suite([sys.executable, "-m", "unittest", "-v", *_PYTHON_MODULES])

    def test_02_javascript_and_spa(self):
        with _stage_cases():
            _run_suite(["node", "--test", *_JAVASCRIPT_FILES])


if __name__ == "__main__":
    unittest.main()
